window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-14"]={"block":"med:med-clinica-medica-med-clm-14","label":"MED · MED CLM 14","count":419,"questions":[{"id":"med-clinica-medica-med-clm-14-345436","number":"345436","sourceNumber":"345436","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A cefaleia é um dos sintomas mais frequentes atendidos pelas equipes da atenção\nprimária. Dentro do universo das cefaleias, a causa mais comum nesse nível de atenção é a:","options":{"A":"Cefaleia tensional.","B":"Cefaleia tipo migrânea (enxaqueca).","C":"Cefaleia causada por infecções sistêmicas agudas.","D":"Cefaleia associada a doenças intracranianas graves como tumores ou infecções cerebrais."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-345440","number":"345440","sourceNumber":"345440","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Assinale a alternativa que apresenta CORRETAMENTE uma característica de\ngravidade ou sinal de alerta (red flag) durante um episódio de cefaléia:","options":{"A":"Presença de aura.","B":"Associação com náuseas e vômitos.","C":"Início súbito, atingindo intensidade máxima em até um minuto.","D":"Cefaleia bilateral em aperto associada à dor à palpação do trapézio."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-345443","number":"345443","sourceNumber":"345443","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na Doença Meningocócica, a antibioticoterapia deve ser instituída o mais precocemente\npossível, de preferência, logo após a\npunção lombar e a coleta de sangue para hemocultura. O uso\nde antibiótico deve ser associado a outros tipos de tratamento de suporte, como reposição de\nlíquidos e cuidadosa assistência. (Ministério da Saúde, 2019). Recomenda-se para o tratamento da\ndoença meningocócica de um paciente adulto a utilização do seguinte antibiótico:","options":{"A":"Amoxicilina.","B":"Penicilina.","C":"Vancomicina.","D":"Ceftriaxona."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-343779","number":"343779","sourceNumber":"343779","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Adolescente procura atendimento em Unidade de Pronto Atendimento com queixa de\ncefaleia hemicraniana esquerda, de característica pulsátil, de forte intensidade, com duração média\nde 48 horas, precedida por alteração da visão. Relata não ser o primeiro episódio. O exame físico\nnão apresenta alterações e a pressão arterial está normal. Apresenta antecedentes de migrânea na\nfamília. Qual das opções abaixo pode ser o tratamento sintomático para essa condição clínica?","options":{"A":"Dipirona, Flunarizina, Amitriptilina.","B":"Gabapentina, Paracetamol, Dipirona.","C":"Propanolol, Ibuprofeno, Gabapentina.","D":"Dipirona, Ibuprofeno, Naproxeno."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-345464","number":"345464","sourceNumber":"345464","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A unidade de saúde da família foi notificada de um caso internado com doença\nmeningocócica. Sobre este tema, assinale a alternativa CORRETA:","options":{"A":"O uso da máscara PFF1 é indicado, considerando o contato por aerossóis na UBS.","B":"Óculos de proteção é indicado no atendimento aos pacientes atendidos na UBS ou internados\naté o quinto dia de tratamento com antibiótico\nadequado.","C":"Considerando o risco de contato por gotículas, os casos internados devem obrigatoriamente ficar\nisolados e em ambientes com filtro HEPA.","D":"Em geral, a bactéria é eliminada da nasofaringe depois de 24 horas de antibioticoterapia\nadequada."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-283272","number":"283272","sourceNumber":"283272","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 25 anos, sexo feminino, em uso de contraceptivo oral comparece em\npronto atendimento referindo cefaleia\nholocraniana, de forte intensidade, em aperto, associada a\nnáuseas e vômitos, confusão mental com alteração do nível de consciência. Nega crises\nconvulsivas prévias e quaisquer outras doenças. Assinale a alternativa correta quanto ao\ndiagnóstico provável.","options":{"A":"Migrânea.","B":"Cefaleia em salvas.","C":"Arterite temporal.","D":"Trombose do seio cavernoso."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-281097","number":"281097","sourceNumber":"281097","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 20 anos, informa que nos últimos 3 anos, vem apresentando quadros\ncaracterizados por: zumbido, tinitus,\nvertigem e hipoacusia. Minutos após, paciente apresenta\ndificuldade para articular a palavra e formigamento do pescoço para baixo, queixas que duram 50\nmin. Esse quadro é seguido por dor pulsátil em região occipital bilateral que se inicia da fraca\nintensidade em que se observa mudança de quadro para forte intensidade com fonofobia e náusea.\nA dor dura por 3 dias e a determinada situação, repete-se de 4 a 5x/mês. Qual poderia ser o\npossível diagnóstico?","options":{"A":"Migrânea sem aura.","B":"Migrânea com aura.","C":"Hemivrania paroxística.","D":"Migrânea basilar.","E":"Migrânea hipoestésica familiar."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-283280","number":"283280","sourceNumber":"283280","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, 32 anos, dá entrada no pronto atendimento com quadro\nagudo de febre, convulsões e rebaixamento do\nnível de consciência. Tomografia de crânio normal.\nO exame do líquor revelava 40 células, com 67% de linfócitos, 30% de monócitos e 3% de\nneutrófilos. Proteínas de 59 mg/dl, glicose de 65 mg/dl e lactato de 24 mg/dl. Baseado nestes\ndados, qual diagnóstico provável?","options":{"A":"Meningoencefalite por tuberculose.","B":"Meningoencefalite por herpes.","C":"Meningoencefalite por HIV.","D":"Meningoencefalite auto-imune."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-283282","number":"283282","sourceNumber":"283282","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Das abaixo, a melhor terapêutica abortiva para cefaleia em salvas é:","options":{"A":"Acupuntura.","B":"Haloperidol.","C":"Inalação máscara de oxigênio.","D":"Gababentina."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-247164","number":"247164","sourceNumber":"247164","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação à Polimialgia Reumática (PMR) indique se são Verdadeiras (V) ou Falsas\n\n(F) as afirmativas a seguir. ( ) A incidência da PMR aumenta com a idade, atingindo pico entre 70 e\n80 anos de idade. ( ) Existe forte\nassociação entre PMR e arterite de células gigantes, sendo que\nmais de 50% dos pacientes com PMR vão apresentar arterite de células gigantes. ( ) O uso de\ncorticosteroides para o tratamento da PMR previne o aparecimento da arterite de rigidez matinal. ( )\nA instalação do quadro na PMR costuma ser insidiosa e arrastada. ( ) O quadro característico da\nPMR é de acometimento de cinturas escapular e pélvica, associado à rigidez matinal. ( ) A biópsia\nde artéria temporal deve ser realizada em todos os pacientes com diagnóstico de PMR. Assinale a\nalternativa que apresenta a sequência CORRETA, de cima para baixo.","options":{"A":"V-F-F-F-V-F","B":"V-V-V-F-V-F","C":"V-F-V-V-F-F","D":"F-V-F-F-V-V","E":"F-F-V-V-F-V"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-247187","number":"247187","sourceNumber":"247187","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Você atende no pronto-socorro um menino de 5 anos com petéquias e equimoses em\ntronco, abdome, membros inferiores e superiores há 1 dia, Antecedente de quadro gripal há 20 dias\ncom melhora completa dos sintomas. Ao exame físico, você observa as referidas lesões e, na\ninspeção da cavidade oral, encontra petéquias em mucosa jugal e equimose de 0,7 cm de diâmetro\nem língua. Não havia alterações no restante do exame, nem sinais de sangramento em outros\nsítios. Foram coletados exames: Hemoglobina 12,1 g/dL, leucócitos de 9 500/mm³ com diferencial\nnormal e plaquetas 17 000/mm³. Qual conduta mais adequada a ser tomada neste momento?","options":{"A":"Esplenectomia de urgência.","B":"Transfusão de concentrado de plaquetas.","C":"Transfusão de crioprecipitado.","D":"Transfusão de plasma.","E":"Imunoglobulina endovenosa."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-247190","number":"247190","sourceNumber":"247190","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Lactente de 10 meses com meningite por Haemophilus influenzae tipo B, recebendo\nceftriaxone há seis dias, evolui com\npersistência da febre e fontanela discretamente abaulada\napesar da melhora clínica. O líquido cefalorraquidiano mantém-se com proteína elevada e melhora\ndos outros parâmetros. A complicação mais frequente com esse quadro é:","options":{"A":"Coleção subdural.","B":"Hidrocefalia.","C":"Abscesso cerebral.","D":"Ventriculite.","E":"Empiema parenquimatoso."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-251917","number":"251917","sourceNumber":"251917","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre enxaqueca, assinale a alternativa INCORRETA:","options":{"A":"Existem pontos de gatilho que desencadeiam a dor, como: odores fortes, tensão, ingesta de\ngorduras. Os anticonvulsivantes estão incluídos no arsenal terapêutico.","B":"Existem duas formas de enxaqueca: com áurea e sem áurea, sendo esta última, a forma mais\ncomum. Os benzodiazepínicos podem ser prescritos.","C":"É uma doença Crônica comum, considerada pela OMS (Organização Mundial da Saúde) como\numa das quatro doenças mais incapacitantes,\ninclusive, pode ser tratada com antidepressivos.","D":"É uma afecção que pode ser prevenida e tratada. Dentre as classes medicamentosas, os\nbetabloqueadores podem ser usados no tratamento."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-251929","number":"251929","sourceNumber":"251929","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com relação às manifestações clínicas da meningite em lactentes menores de 3\nmeses, assinale qual das abaixo NÃO é frequente nesta faixa etária.","options":{"A":"Febre.","B":"Vômitos.","C":"Irritabilidade.","D":"Rigidez de nuca."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-217647","number":"217647","sourceNumber":"217647","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, de 28 anos, mudou-se para área de abrangência da USF do\nMocinha Magalhães e procura o acolhimento da unidade com queixa de cefaleia há 8 horas, de\nmoderada intensidade, hemicraniana à direita, acompanhada de fotofobia, fonofobia, náuseas e\nvômitos. Tem crises semelhantes, 1 a 2 vezes por semana (exceto no período perimenstrual,\nquando tem crises diárias), desde os 15 anos de idade. Não fuma, não bebe e não usa drogas.\n\nMora com os pais e com um irmão de 20 anos. Refere que sua mãe tem o mesmo quadro e ambas\nprocuram atendimento médico apenas nos momentos da crise, geralmente no pronto-socorro da\ncidade onde moravam. O exame clínico é normal. Qual diagnóstico é compatível com o quadro\nclínico da paciente?","options":{"A":"Cefaleia tensional.","B":"Enxaqueca sem aura.","C":"Cefaleia em salvas.","D":"Cefaleia secundária."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-183171","number":"183171","sourceNumber":"183171","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, 20 anos, relata que, nos últimos 3 anos, vem apresentando\nquadros caracterizados por: zumbido, tinnitus,\nvertigem e hipoacusia, e alguns minutos após,\ndificuldade para articular a palavra e formigamento do pescoço para baixo, queixas que duram 60\nmin. Esse quadro é seguido por dor pulsátil em região occipital bilateral que se inicia de fraca\nintensidade e evolui para forte intensidade com fonofobia/fotofobia e náusea. A dor dura 3 dias e\ntal\nepisódio tem se repetido 4 a 5x mês. Qual é a sua hipótese diagnóstica?","options":{"A":"Migrânea basilar.","B":"Migrânea com aura.","C":"Migrânea sem aura.","D":"Migrânea hipoestésica familiar.","E":"Hemicrania paroxística."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-182699","number":"182699","sourceNumber":"182699","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Lactente de 4 meses, mama exclusivamente ao seio materno, procura o pronto socorro\ncom história de febre aferida há 2 dias com\ntemperatura variando de 38,5 a 39,5ºC, além de\nvômitos. Mãe informa irritabilidade, recusa alimentar e 1 episódio de crise convulsiva. Ao exame\nfísico os achados pertinentes são irritabilidade e fontanela anterior normotensa. O cartão vacinal\nestá completo para a idade e o menor nasceu de parto à termo com boa vitalidade. Qual a melhor\nconduta pediátrica no momento?","options":{"A":"Internação hospitalar, solicitar hemograma e PCR quantitativo, realizar punção lombar para\nanálise liquórica, pensando em meningite bacteriana.","B":"Internação hospitalar, solicitar TC de crânio e solicitar parecer da neurologia pediátrica,\npensando em crise convulsiva associada a tumor intracraniano.","C":"Internação hospitalar, solicitar hemograma, PCR quantitativo e exame de urina, prescrever\nanticonvulsivante, pensando em infecção do trato urinário e epilepsia.","D":"Tratamento ambulatorial, com prescrição de antitérmico e encaminhamento para o ambulatório\nde neurologia, pensando em crise convulsiva febril."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-183216","number":"183216","sourceNumber":"183216","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação a um achado de hemianopsia homônima diante da avaliação subjetiva do\ncampo de visão, ou seja, o exame do campo\nvisual que justifica o diagnóstico de lesão,\ncaracteriza-se como:","options":{"A":"Quiasma óptico.","B":"Radiações ópticas.","C":"Nervo oculomotor.","D":"Nervo zigomático facial.","E":"Segundo nervo craniano."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-183197","number":"183197","sourceNumber":"183197","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Nas paralisias do nervo oculomotor, é CORRETO afirmar que:","options":{"A":"Com ataxia contralateral e tremulação, a condição é síndrome de Weber.","B":"Com hemiplegia contralateral, a lesão se situa na área do núcleo vermelho.","C":"No diabetes, a pupila é poupada.","D":"Causada por aneurisma, é indolor.","E":"O olho fica em extorsão é abdução."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-108822","number":"108822","sourceNumber":"108822","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre as etiologias das DEMÊNCIAS, pode-se afirmar que:","options":{"A":"Pode definir a possibilidade de tratamento, e em alguns casos, a reversão dos sintomas.","B":"Não é importante, já que os processos demenciais são inexoráveis e progressivos.","C":"Geralmente a etiologia pode ser definida com anamnese e exame físico cuidadoso.","D":"Só pode ser realizada por neurologista especializado em demências."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-84487","number":"84487","sourceNumber":"84487","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação à estenose de artéria carótida, quando temos contraindicação absoluta do\ntratamento cirúrgico:","options":{"A":"Estenose de 65%, paciente sintomático.","B":"Estenose de 75%, paciente sintomático.","C":"Estenose de 85%, paciente sintomático.","D":"Estenose de 95%, paciente sintomático.","E":"Estenose de 100%, paciente assintomático."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-66974","number":"66974","sourceNumber":"66974","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre propedêutica neurológica armada (exames imagem), correlacione as colunas\ncom as características de cada exame: 1.\nTomografia computadorizada; 2. Angiografia\nconvencional; 3. Ressonância magnética; 4. Tomografia por Emissão de Pósitrons (PET). A.\nMelhor modalidade para avaliação por imagem de aneurismas. B. Não invasiva, sem radiação,\nmultiplanar, sensível e agente de contraste seguro. C. Rápida, melhor teste para hemorragia aguda\ne excelente para ossos. D. Útil no diagnóstico de doença de Alzheimer e epilepsia.","options":{"A":"1.A; 2.B; 3.C; 4.D.","B":"1.C; 2.A; 3.B; 4.D.","C":"1.B; 2.C; 3.A; 4.D.","D":"1.D; 2.A; 3.B; 4.C."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-37069","number":"37069","sourceNumber":"37069","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem com 35 anos de idade, sedentário, hipertenso com níveis médios de PA 160 x\n90 mmHg, com sobrepeso, após ser submetido à\nsituação estressante passou a sentir cefaleia\ndifusa crescente em intensidade, tontura, náuseas e dificuldade para falar. Foi atendido e feito o\ndiagnóstico de crise hipertensiva com níveis tensionais de 180 x 100 mmHg e medicado com\nnifedipina sublingual e diazepam 10 mg IM. Após 20 minutos da administração dos remédios, o\ndoente estava não responsivo (coma), com hemiplegia direita e respiração de Cheyne-Stokes.\n\nAcerca do caso descrito, assinale a alternativa correta.","options":{"A":"A conduta adotada é a indicada em quadros clínicos semelhantes, já que é fundamental a\nredução rápida da hipertensão.","B":"O quadro clínico inicial sugeria AVC hemorrágico.","C":"O quadro clínico inicial sugeria AVC isquêmico, no qual a redução da hipertensão é item básico\ndo atendimento da fase aguda.","D":"Nifedipina SL e diazepam são partes do tratamento proposto no Consenso Brasileiro de AVC -\nfase aguda.","E":"O déficit motor e coma indicam localização de lesões prévias (lacunas) em tronco cerebral,\nagravadas pela crise hipertensiva."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-372086","number":"372086","sourceNumber":"372086","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Assinale a alternativa correta sobre a apresentação e as características clínicas da\ndoença meningocócica invasiva:","options":{"A":"O choque meningocócico e a meningite nunca estão associados, e quando presente um ou outro\npodem representar um desafio de manejo extraordinário, uma vez que a doença meningocócica\ninvasiva pode progredir e evoluir rapidamente mesmo com suporte adequado.","B":"Meningococcemia é a forma clínica mais temida da infecção meningocócica e é causada por\numa resposta inflamatória fulminante do\nhospedeiro à invasão bacteriana, caracterizando-se por um\nquadro de choque séptico com disfunção endotelial e coagulopatia grave.","C":"Sintomas gastrointestinais agudos como apresentação primária de doença meningocócica\ninvasiva são bastante frequentes, sendo um dos\nprincipais sintomas, e são mais frequentemente\ndescritos em infecções por MenW.","D":"Bacteremia oculta é uma forma clínica descrita frequentemente com N. meningitidis, e casos de\ndoença meningocócica sem suspeita clínica são\nfrequentes em pacientes ambulatoriais pediátricos\nfebris."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-369502","number":"369502","sourceNumber":"369502","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Considerando a situação proposta, indique a definição correta para um surto\ncomunitário de meningite meningocócica:","options":{"A":"Dois ou mais casos confirmados em uma mesma escola, dentro de 3 meses.","B":"Três ou mais casos confirmados em uma mesma área residencial em 3 meses.","C":"Um único caso confirmado com alta taxa de letalidade.","D":"Qualquer ocorrência de caso confirmado em área urbana."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-369503","number":"369503","sourceNumber":"369503","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Menino, 5 anos de idade, foi levado em urgência ao hospital com febre alta, dor de\ncabeça intensa, rigidez na nuca e\naparecimento súbito de manchas roxas na pele. Após exames,\nfoi diagnosticado com meningite meningocócica. O menor frequenta uma escola local e tem um\nirmão de 2 anos em casa. O caso gerou preocupação na comunidade local sobre o risco de\ndisseminação da doença. Considerando os contatos com um alto grau de exposição, em relação ao\nmenor a melhor quimioprofilaxia, indicada no SUS, é feita com:","options":{"A":"Rifampicina.","B":"Amoxacilina.","C":"Ceftriaxona.","D":"Amicacina."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-341038","number":"341038","sourceNumber":"341038","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 70 anos de idade, procura atendimento clínico por quadro de cefaleia intensa\nem região temporal, há 4 meses. Queixa-se\nainda de fadiga importante, perda da acuidade visual e\nperda ponderal não aferida. Ao exame, apresenta-se em regular estado geral, emagrecida,\nsubfebril; demais sinais vitais estáveis. Apresenta alodínia em região de couro cabeludo e\nclaudicação de mandíbula. Considerando o caso clínico descrito, indique o diagnóstico mais\nprovável para o paciente:","options":{"A":"Neuromielite óptica.","B":"Arterite de células gigantes","C":"Cefaleia em salvas.","D":"Nevralgia do nervo trigêmeo."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-341039","number":"341039","sourceNumber":"341039","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 70 anos de idade, procura atendimento clínico por quadro de cefaleia intensa\nem região temporal, há 4 meses. Queixa-se\nainda de fadiga importante, perda da acuidade visual e\nperda ponderal não aferida. Ao exame, apresenta-se em regular estado geral, emagrecida,\nsubfebril; demais sinais vitais estáveis. Apresenta alodínia em região de couro cabeludo e\nclaudicação de mandíbula. Indique o exame padrão-ouro para o diagnóstico mais provável:","options":{"A":"Ressonância magnética de crânio.","B":"Tomografia computadorizada de crânio.","C":"Biópsia da artéria temporal.","D":"Eletroencefalograma."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-341040","number":"341040","sourceNumber":"341040","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 70 anos de idade, procura atendimento clínico por quadro de cefaleia intensa\nem região temporal, há 4 meses. Queixa-se\nainda de fadiga importante, perda da acuidade visual e\nperda ponderal não aferida. Ao exame, apresenta-se em regular estado geral, emagrecida,\nsubfebril; demais sinais vitais estáveis. Apresenta alodínia em região de couro cabeludo e\nclaudicação de mandíbula. Frente ao caso, indique a opção terapêutica mais adequada:","options":{"A":"Tramadol e oxigenioterapia.","B":"Analgésico comum e escalonar para opioides, conforme resposta.","C":"Carbamazepina, oxcarbamazepina ou gabapentina.","D":"Corticoterapia, imunossupressores e/ou imunobiológicos."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-279023","number":"279023","sourceNumber":"279023","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"As cefaleias primárias são doenças com episódios recorrentes de dor de cabeça, sendo\ncorreto que","options":{"A":"Migrânea (enxaqueca) caracteriza-se por crises não recorrentes constituídas por até cinco fases\n(nem sempre estão presentes todas elas).","B":"Migrânea (enxaqueca) caracteriza-se por crises recorrentes constituídas por até dez fases (nem\nsempre estão presentes todas elas).","C":"Migrânea (enxaqueca) caracteriza-se por crises recorrentes constituídas por até cinco fases\n(sempre estão presentes todas elas).","D":"Migrânea (enxaqueca) caracteriza-se por crises recorrentes constituídas por até cinco fases\n(nem sempre estão presentes todas elas)."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-278604","number":"278604","sourceNumber":"278604","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na Cefaleia do tipo tensional episódica, ocorre cefaleia em pressão, holocraniana de\nleve a moderada intensidade, podendo beneficiar-se com atividade física. Aparece geralmente no\nfim do dia, durando de 30 minutos a sete dias. Está correto que","options":{"A":"Não pode haver foto e/ou fonofobia, náuseas e vômitos estão ausentes. O exame neurológico é\nnormal, hipertonia e hiperestesia da musculatura pericraniana podem estar presentes.","B":"Pode haver foto e/ou fonofobia, mas náuseas e vômitos estão ausentes. O exame neurológico é\nanormal, hipertonia e hiperestesia da musculatura pericraniana podem estar presentes.","C":"Pode haver foto e/ou fonofobia, mas náuseas e vômitos estão presentes. O exame neurológico é\nnormal, hipertonia e hiperestesia da musculatura pericraniana podem estar presentes.","D":"Pode haver foto e/ou fonofobia, mas náuseas e vômitos estão ausentes. O exame neurológico é\nnormal, hipertonia e hiperestesia da musculatura pericraniana podem estar presentes."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-279025","number":"279025","sourceNumber":"279025","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"São considerados sinais de alerta para cefaleias secundárias os listados corretamente\nno item.","options":{"A":"Presença de déficits neurológicos focais, edema de papila, convulsão.","B":"O (Older) Cefaleia que iniciou após os 20 anos.","C":"O (Onset) Cefaleia de início súbito, nunca a primeira cefaleia.","D":"P (Pattern) Manutenção de padrão da cefaleia prévia ou cefaleia progressiva (intensidade,\nfrequência ou duração) ou cefaleia refratária."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-279029","number":"279029","sourceNumber":"279029","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Nos casos de cefaleia do tipo tensional episódica , o Médico da unidade de urgência\norienta paciente e familiares quanto à baixa\ngravidade do quadro e de não haver necessidade de\nencaminhá-lo a um especialista ou realização de exames complementares. Sendo adequado o\nitem.","options":{"A":"Orientação de medidas educativas como: sono regular, evitar bebidas alcoólicas, controle de\nestresse (técnicas de relaxamento, atividade física leve), lazer.","B":"Orientação de medidas educativas como: sono irregular, evitar bebidas alcoólicas, controle de\nestresse (técnicas de relaxamento, atividade física leve) não ao lazer.","C":"Orientação de medidas educativas como: sono regular, evitar bebidas alcoólicas, controle de\nestresse sem uso de técnicas de relaxamento, atividade física leve.","D":"Nunca orientação de medidas educativas como: sono regular, evitar bebidas alcoólicas, controle\nde estresse (técnicas de relaxamento, atividade\nfísica leve), lazer."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-252882","number":"252882","sourceNumber":"252882","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem, 32 anos de idade, procura atendimento na UPA por quadro de cefaleia intensa\nem pontada, unilateral, em região\nperiorbitária a esquerda, há 30 minutos, associada a fotofobia e\nnáuseas. Nega comorbidades. Ao exame, paciente bastante ansioso, com fácies de dor. Nota-se\nlacrimejamento e hiperemia conjuntival em olho esquerdo. De acordo com o quadro descrito,\nindique o diagnóstico mais provável.","options":{"A":"Migrânea com aura.","B":"Neuralgia do trigêmeo.","C":"Cefaleia em salvas.","D":"Cefaleia em trovoada."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-252883","number":"252883","sourceNumber":"252883","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem, 32 anos de idade, procura atendimento na UPA por quadro de cefaleia intensa\nem pontada, unilateral, em região\nperiorbitária a esquerda, há 30 minutos, associada a fotofobia e\nnáuseas. Nega comorbidades. Ao exame, paciente bastante ansioso, com fácies de dor. Nota-se\nlacrimejamento e hiperemia conjuntival em olho esquerdo. Considerando o caso, indique a conduta\nterapêutica mais efetiva nesse momento.","options":{"A":"Oxigenoterapia sob máscara.","B":"Dexametasona intravenosa.","C":"Tramadol intravenoso.","D":"Naproxeno via oral."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-252884","number":"252884","sourceNumber":"252884","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem, 32 anos de idade, procura atendimento na UPA por quadro de cefaleia intensa\nem pontada, unilateral, em região\nperiorbitária a esquerda, há 30 minutos, associada a fotofobia e\nnáuseas. Nega comorbidades. Ao exame, paciente bastante ansioso, com fácies de dor. Nota-se\nlacrimejamento e hiperemia conjuntival em olho esquerdo. Cite o fármaco mais adequado para\nprofilaxia de novos quadros semelhantes.","options":{"A":"Propranolol.","B":"Verapamil.","C":"Indometacina.","D":"Amitriptilina."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-249206","number":"249206","sourceNumber":"249206","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Levando-se em consideração a epidemiologia das meningites no Brasil, assinale a\nalternativa correta em relação ao fármaco de escolha para a realização de terapia empírica no caso\nde suspeita para a meningite.","options":{"A":"Ganciclovir.","B":"Penicilina Cristalina.","C":"Vancomicina.","D":"Aciclovir."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-249211","number":"249211","sourceNumber":"249211","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"No tratamento da encefalite herpética, qual das medicações abaixo dever ser utilizada\ncomo escolha?","options":{"A":"Aciclovir.","B":"Valaciclovir.","C":"Fanciclovir.","D":"Valciclovir e aciclovir combinados."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-219868","number":"219868","sourceNumber":"219868","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança de 3 anos foi levada a consulta com história de cefaleia iniciada há 20 dias,\nholocraniana, de forte intensidade, incapacitante ( 'para de brincar e não quer se mexer'). Mãe\nrelata que criança apresenta cefaleia diária, mais matutina e já despertou durante o sono com\nqueixa de dor, Refere melhora da cefaleia após vômitos, mas resposta parcial ao uso de dipirona,\nTia paterna tem diagnóstico de enxaqueca. Pais estão em processo de divórcio. Diante desta\nhistória clínica, a conduta CORRETA deve ser:","options":{"A":"Descartar causas orgânicas de cefaleia na infância e solicitar tomografia de encéfalo na\nurgência.","B":"Encaminhar a criança para acompanhamento psicológico e agendar retorno em um mês.","C":"Prescrever uso de analgésicos mais potentes nas crises de dor e retornar em um mês com\nagenda de dor.","D":"Tranquilizar a criança e a família sobre a benignidade do quadro e realizar alta médica"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-201792","number":"201792","sourceNumber":"201792","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual resultado de LCR é mais sugestivo de meningite pneumocócica?","options":{"A":"Turvo, 600 células, 90% neutrófilos, diplococos Gram-positivos.","B":"Turvo, 900 células, 95% neutrófilos, diplococos Gram-negativos.","C":"Turvo, 180 células, 70% linfócitos, cultura em andamento.","D":"Turvo, 100 células, 60% linfócitos, proteínas: 280 mg%.","E":"Nenhuma das alternativas."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-183628","number":"183628","sourceNumber":"183628","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"No tocante aos inibidores da monoaminoxidase (IMAO), as interações medicamentosas\ne alimentares determinadas por este grupo de\ndrogas desaconselham seu uso em profilaxia de\nmigrânea, estando INCORRETO que:","options":{"A":"Os antidepressivos tricíclicos não têm eficácia comprovada por vários estudos em profilaxia de\nmigrânea.","B":"Admite-se antidepressivos tricíclicos que ajam por inibir a receptação da serotonina.","C":"Admite-se antidepressivos tricíclicos que ajam por inibir a receptação da noradrenalina.","D":"Os antidepressivos tricíclicos têm sua ação antimigranosa independe da ação antidepressiva."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-183643","number":"183643","sourceNumber":"183643","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"O tratamento profilático da migrânea menstrual, não deve apenas considerar como\nCORRETO o seguinte:","options":{"A":"Antes de iniciar o tratamento é fundamental estabelecer os períodos em que as crises ocorrem\ncom maior frequência através do preenchimento\nde um diário de dor pelo paciente.","B":"O tratamento profilático da migrânea menstrual deve ter caráter temporário, iniciando-se em\nintervalo de 1 a 14 dias antes do dia em que, usualmente, a cefaleia se inicia, sempre obedecendo\nao padrão estabelecido pelo diário.","C":"Se na terapia com anti-inflamatório não-esteroides (AINEs), derivados da ergotamina ou\ntriptanos controlam adequadamente a migrânea\nmenstrual, deve ser considerada a possibilidade de\nterapia hormonal.","D":"Essa terapia pode ser realizada através da utilização do estrógeno em combinação com a\nprogesterona."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-183585","number":"183585","sourceNumber":"183585","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Marque a opção INCORRETA.","options":{"A":"Na suspeita clínica de encefalite viral aguda o liquor normal não descarta o diagnóstico, e os\nconsensos mais recentes sugerem a realização\nde segunda punção lombar em 24 a 72 horas.","B":"Entre os exames de rotina sugeridos para crianças com encefalite, estão hemograma, provas de\nfunção hepática, gasometria e hemocultura.","C":"Recomenda-se em todos os pacientes com encefalite a pesquisa de PCR no liquor para vírus\nherpes simples tipo 1 e 2, varicela zoster e enterovírus, o que permitirá a identificação da maioria\ndos casos virais conhecidos.","D":"Em pacientes imunodeficientes sugere-se ampliar a investigação de PCR no liquor para Epstein\nBarr, CMV, herpes vírus humano 6 e 7, bem\ncomo avaliação diagnóstica para tuberculose, sífilis,\nlisteriose, criptococose e toxoplasmose."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-182756","number":"182756","sourceNumber":"182756","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Os sítios primários mais comuns dos tumores cerebrais metastáticos são, EXCETO","options":{"A":"câncer de pulmão.","B":"câncer de pâncreas.","C":"câncer de mama.","D":"melanoma."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-187857","number":"187857","sourceNumber":"187857","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente com 60 anos, sexo feminino, apresenta dor na cabeça com localização\nholocraniana, de forte intensidade, que se inicia\napós início do sono. A paciente refere que a dor\nmelhora ou desaparece quando ela desperta. Assinale a alternativa CORRETA quanto ao\ndiagnóstico MAIS PROVÁVEL desse caso:","options":{"A":"Cefaleia tensional.","B":"Cefaleia em salvas.","C":"Cefaleia hípnica.","D":"Enxaqueca."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-161360","number":"161360","sourceNumber":"161360","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A punção liquórica para diagnóstico de meningite é contraindicada nos casos seguintes,\ncom EXCEÇÃO de um. Indique-o.","options":{"A":"Aumento da pressão intracraniana.","B":"Encefalopatia crônica não evolutiva.","C":"Comprometimento cardiopulmonar.","D":"Infecção no local da punção."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-161382","number":"161382","sourceNumber":"161382","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Considerando o diagnóstico de meningite, analise as seguintes proposições. I. A\npunção liquórica deve ser realizada após o\nexame físico, sempre que se considerar um caso\nsuspeito de meningite e desde que o paciente não apresente instabilidade respiratória ou\ncirculatória, alterações neurológicas ou infecções no local da punção. II. A hemocultura mostra o\ngerme em 80 a 90% das meningites bacterianas. III. A tomografia computadorizada de crânio deve\nser realizada quando houver sinais de hipertensão intracraniana e suspeita de abscesso cerebral.\nEstão CORRETAS as proposições contidas em:","options":{"A":"I e II, apenas.","B":"II e III, apenas.","C":"I e III, apenas.","D":"I, II e III."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-161157","number":"161157","sourceNumber":"161157","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na meningite ocorrem várias alterações fisiopatológicas, destacando-se as contidas a\nseguir, com EXCEÇÃO de uma delas. Assinale-a:","options":{"A":"Rompimento da barreira hematoencefálica.","B":"Diminuição da pressão intracraniana com paralisia do nervo oculomotor.","C":"Morte cerebral.","D":"Inflamação de nervos espinhais e cranianos."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-161161","number":"161161","sourceNumber":"161161","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação ao tratamento das meningites, assinale a alternativa INCORRETA.","options":{"A":"Na suspeita de meningite bacteriana, o antibiótico deve ser iniciado logo após a coleta de liquor\ne culturas.","B":"O pneumococo deve ser tratado por 21 dias.","C":"Em criança imunocompetente, a escolha do antibiótico é influenciada pela epidemiologia local.","D":"O liquor deve ser repetido em recém-nascido com germes Gram negativos, em crianças sem\nmelhora após quatro dias, na presença de novos sintomas e em caso de germe resistente ou não\nusual sem melhora em 48 horas."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-134802","number":"134802","sourceNumber":"134802","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente deu entrada com queixa de cefaleia súbita seguida de perda motora e\ndisartria. Foi, então, solicitada Tomografia de\nCrânio que não demonstrou achados de imagem. A\nseguir, foi colhido liquor que também se mostrou inespecífico. Nesse caso, podemos afirmar que","options":{"A":"A Tomografia mostrava-se essencial para afastar sangramentos.","B":"O liquor mostrou-se mal indicado, pois se não ocorrem achados na Tomografia o mesmo\nmostra-se desnecessário.","C":"A abordagem inicial deveria considerar RNM e não Tomografia.","D":"O liquor é mais sensível que a Tomografia para diversos diagnósticos."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-134094","number":"134094","sourceNumber":"134094","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Quando abordamos emergências hipertensivas relacionadas ao sistema nervoso\ncentral, podemos afirmar que apresentam correlação\nde lesão de órgão alvo e hipertensão os\nseguintes quadros clínicos, EXCETO o contido em uma das alternativas. Aponte-a.","options":{"A":"Edema de papila de nervo óptico.","B":"Edema cerebral visível na tomografia.","C":"Cluster.","D":"Sangramento cerebral."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-134123","number":"134123","sourceNumber":"134123","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente com midríase unilateral, fotorreatividade pupilar com reação cruzada (Sinal de\nMarcus Gunn) apresenta lesão do nervo:","options":{"A":"Facial.","B":"Auricular.","C":"Oculomotor.","D":"Óptico."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-109725","number":"109725","sourceNumber":"109725","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo masculino, 27 anos, refere coriza hialina, tosse produtiva e mialgia de\ninício há três semanas com melhora espontânea após quatro dias. No entanto, após alguns dias,\npassou a apresentar fraqueza em membros inferiores, com dificuldade para deambular, que\nprogrediu para discreta redução da força muscular em membros superiores. Ao exame físico,\napresenta força muscular grau III em membros inferiores e grau IV em membros superiores.\n\nReflexos osteotendíneos normais, ausência de sinais de liberação piramidal, sensibilidade normal.\nAssinale abaixo a hipótese diagnóstica mais provável e o exame a ser solicitado para sua\nconfirmação, RESPECTIVAMENTE.","options":{"A":"Acidente vascular medular cervical / Ressonância magnética.","B":"Encefalopatia de Wernicke / Dosagem de tiamina.","C":"Síndrome de Guillain-Barré / Coleta de liquor.","D":"Esclerose lateral amiotrófica / Eletroneuromiografia."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-110062","number":"110062","sourceNumber":"110062","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Assinale abaixo a conduta apropriada em paciente com Acidente Vascular Cerebral\nIsquêmico Cerebelar que evolui com hidrocefalia e rebaixamento do nível de consciência.","options":{"A":"Derivação ventricular externa.","B":"Solução salina hipertônica.","C":"Nimodipina endovenosa.","D":"Medidas de suporte clínico."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-86668","number":"86668","sourceNumber":"86668","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A conduta a seguir faz parte do manejo da fase aguda: Cuidados gerais de manter as\nvias aéreas, respiração e condições circulatórias, anticonvulsivantes, nimodipina, repouso absoluto\nno leito, ansiolíticos, controle da glicemia. I ? Acidente vascular isquêmico. II ? Acidente\nvascular\nisquêmico transitório. III ? Hemorragia subaracnoide.","options":{"A":"Apenas afirmativas I, II estão corretas.","B":"Apenas afirmativa I está correta.","C":"Apenas afirmativa II está correta.","D":"Apenas afirmativas I e III estão corretas.","E":"Apenas afirmativa III está correta."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-86877","number":"86877","sourceNumber":"86877","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente 20 anos, mulher, teve exposição à brusca variação de temperatura ambiente,\nverificou que sua comissura labial estava desviada para a direita. Concomitante, notou a\nimpossibilidade de fechar a pálpebra esquerda e hipostesia em hemiface esquerda. Nenhuma\noutra alteração no exame neurológico. Esse diagnóstico de paralisia facial é do tipo:","options":{"A":"Periférica esquerda;","B":"Periférica direita;","C":"Central esquerda;","D":"Central direita;","E":"Complexa."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-86798","number":"86798","sourceNumber":"86798","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Albina é uma senhora de 82 anos hipertensa e diabética, viúva há 5 anos. Vem à\nconsulta trazida por sua filha, que relata que\na mãe vem apresentando há 3 anos quadro\nprogressivo de perda de memória e agressividade com os filhos. Até 1 mês atrás, morava sozinha\nem outra cidade, mas teve que se mudar para a casa da filha após quase ter incendiado a casa ao\ndeixar a panela no fogo e ter ido dormir. Em relação a esse caso clínico, assinale a alternativa\ncorreta.","options":{"A":"O diagnóstico de depressão é improvável, pois geralmente não cursa com perda de memória;","B":"A possibilidade de demência vascular deve\n\nser considerada mesmo na ausência de história de acidente vascular cerebral;","C":"O miniexame do estado mental, o teste do relógio e testes de fluência verbal são úteis para\nrastreamento, mas têm valor limitado na avaliação e no acompanhamento clínico de pacientes\ncom demência;","D":"Benzodiazepínicos devem ser usados para conter a agressividade, de preferência o diazepam;","E":"O diagnóstico de delirium deve ser fortemente considerado devido ao curso progressivo do\nquadro."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-86650","number":"86650","sourceNumber":"86650","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre a demência, é CORRETO afirmar:","options":{"A":"É um aspecto inevitável ao processo de envelhecimento.","B":"Existem medicações bem estabelecidas para o tratamento das demências primárias, como a\nDoença de Alzheimer.","C":"O diagnóstico das demências depende de achados tomográficos.","D":"A avaliação de depressão é recomendável, pois pode mascarar um quadro de demência.","E":"Os familiares devem confrontar todos os erros e discutir com o paciente para que não os repita."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-158392","number":"158392","sourceNumber":"158392","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a afirmação abaixo. Sobre o uso\nde corticoide nas meningites bacterianas,\nobjetivando reduzir a incidência de sequelas auditivas e\nneurológicas, recomenda-se:","options":{"A":"Limitar seu uso aos pacientes graves.","B":"Iniciá-lo após a negativação da bacterioscopia no LCR.","C":"Administrá-lo antes da antibioticoterapia.","D":"Usá-lo apenas nos pacientes com edema cerebral.","E":"Mantê-lo durante toda a antibioticoterapia."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-362484","number":"362484","sourceNumber":"362484","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma mulher de 29 anos apresenta-se com episódios recorrentes de cefaleia que duram\nde 4 a 72 horas quando não tratados. As\ndores de cabeça são frequentemente unilaterais,\npulsáteis, de intensidade moderada a severa, e agravadas pela atividade física rotineira. Ela\ntambém relata náuseas e fotofobia durante os episódios. Qual é o tratamento abortivo mais\napropriado para os episódios de cefaleia desta paciente?","options":{"A":"Triptanos.","B":"Amitriptilina.","C":"Topiramato.","D":"Profilaxia com beta-bloqueadores."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-252217","number":"252217","sourceNumber":"252217","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma médica residente foi diagnosticada como Migrânea na emergência clínica. Qual\nalternativa abaixo preenchem os Critérios diagnósticos da migrânea sem aura?","options":{"A":"Cefaleia durando de 4 a 72 horas; localização unilateral; caráter pulsátil; intensidade moderada\nou forte; exacerbada por ou levando o indivíduo\na evitar atividades físicas rotineiras. Durante a\ncefaleia, apresenta pelo menos um dos seguintes sintomas: náuseas e/ou vômitos; fotofobia e\nfonofobia.","B":"Cefaleia durando de 30 minutos a 7 dias; localização unilateral; caráter pulsátil; intensidade\nmoderada ou forte; exacerbada por ou levando o indivíduo a evitar atividades físicas rotineiras.\nDurante a cefaleia, apresenta pelo menos um dos seguintes sintomas: náuseas e/ou vômitos;\nfotofobia e fonofobia.","C":"Cefaleia durando de 4 a 72 horas; localização unilateral; caráter pulsátil; intensidade leve ou\nmoderada; exacerbada por ou levando o indivíduo a evitar atividades físicas rotineiras. Durante a\ncefaleia, apresenta pelo menos um dos seguintes sintomas: náuseas e/ou vômitos; fotofobia e\nfonofobia.","D":"Cefaleia durando de 30 minutos a 7 dias; localização unilateral; caráter pulsátil; intensidade\nleve\nou moderada; exacerbada por ou levando o indivíduo a evitar atividades físicas rotineiras. Durante\na cefaleia, apresenta pelo menos um dos seguintes sintomas: náuseas e/ou vômitos; fotofobia e\nfonofobia."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-208391","number":"208391","sourceNumber":"208391","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Como se apresenta a análise do líquido cefalorraquidiano compatível com\nneurotuberculose?","options":{"A":"Pleocitose com predomínio de linfomononucleares; concentrações de proteína e glicose normais.","B":"Pleocitose com predomínio de linfomononucleares; elevação da concentração de proteínas e\nredução da glicose.","C":"Pleocitose com predomínio de neutrófilos; redução da concentração de proteína e redução da\nglicose.","D":"Pleocitose com predomínio de neutrófilos; concentrações de proteína e glicose normais."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-176008","number":"176008","sourceNumber":"176008","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 34 anos de idade apresentando cefaleia recorrente foi diagnosticado\ncom cefaleia em salvas ou ?cluster headache?.\nQuais os sinais e sintomas são os mais prováveis\npara este diagnóstico?","options":{"A":"Cefaleia geralmente de moderada ou forte intensidade, pulsátil, unilateral com náuseas e/ou\nfotofobia, persistindo por 4?72 horas.","B":"Cefaleia geralmente de leve ou moderada intensidade, sensação difusa e dolorosa ou em\ncompressão em torno da cabeça, dor em couro cabeludo, persistindo por 30 minutos a 7 dias.","C":"Cefaleia geralmente intensa, excruciante, com congestão ocular, obstrução nasal, sudorese da\nfronte e da face ipsilateral, durando de 15?80 minutos.","D":"Ataques recorrentes de dor lancinante e súbita, descrita como um choque doloroso intenso e\nincapacitante. A dor pode ser desencadeada por falar, escovar os dentes, mastigar ou tocar\nlevemente no rosto."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-103827","number":"103827","sourceNumber":"103827","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A rápida correção do sódio em pacientes com hiponatremia crônica pode levar a\nmielinólise pontinha central que se caracteriza por:","options":{"A":"síndrome de liberação inadequada de hormônio antidiurético.","B":"paralisia flácida.","C":"hipotensão postural.","D":"paralisia pseudônimo bulhar e queda do nível de consciência."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-107822","number":"107822","sourceNumber":"107822","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A doença de Alzheimer (DA) é um transtorno neurodegenerativo progressivo e fatal que\nse manifesta por deterioração cognitiva e da\nmemória, comprometimento progressivo das\natividades de vida diária e uma variedade de sintomas neuropsiquiátricos e de alterações\ncomportamentais. Qual abordagem terapêutica NÃO é recomendada para esta doença:","options":{"A":"Os agonistas muscarínicos e nicotínicos e seus compostos, por aumentar a liberação da\nacetilcolina, são de grande benefício, pois apresentam efeitos clínicos importantes na DA.","B":"O tratamento da DA deve ser multidisciplinar, envolvendo os diversos sinais e sintomas da\ndoença e suas peculiaridades de condutas.","C":"Os fármacos colinérgicos donepezila, galantamina e rivastigmina são considerados os de\nprimeira linha, estando todos recomendados para tratamento da DA leve e moderada.","D":"Os benefícios esperados com o tratamento da DA são redução na velocidade de progressão da\ndoença e a melhora da memória e da\natenção."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-107850","number":"107850","sourceNumber":"107850","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação ao Acidente Vascular Encefálico (AVE) assinale a alternativa incorreta:","options":{"A":"O AVE é uma emergência médica e, eventualmente, poderá necessitar de tratamento cirúrgico.","B":"O AVE é a principal hipótese para o diagnóstico diferencial em pacientes com déficits\nneurológicos de início súbito.","C":"A desidratação em pacientes com AVE é geralmente associada a um pior prognóstico, e o uso\nde fluidos hipotônicas são melhor indicados,\numa vez que reduzem o risco de edema cerebral e\nhipertensão intracraniana, especialmente no infarto extenso.","D":"A hiperglicemia ocorre em mais da metade dos pacientes na fase aguda do AVE, mesmo\naqueles sem historia de diabetes mellitus, e está associada com aumento da morbidade e\nmortalidade."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-103858","number":"103858","sourceNumber":"103858","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na investigação da fase aguda do acidente vascular encefálico (AVE), qual é o método\nde exame de imagem mais recomendado, devendo\nser realizada o mais rapidamente possível?","options":{"A":"Tomografia computadorizada do crânio.","B":"Ressonância Magnética encefálica.","C":"Angiografia cerebral.","D":"Doppler transcraniano."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-26445","number":"26445","sourceNumber":"26445","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente é trazido ao Pronto Socorro uma hora após apresentar hemiparesia\ndesproporcionada à esquerda. Apresenta PA de 150 x 95 mmHg. Neste caso:","options":{"A":"dependendo do exame de imagem e do coagulograma, o paciente poderá receber r-tPA ou\naspirina","B":"deve-se administrar anticonvulsivante preventivo","C":"deve-se fazer tomografia de crânio e ecocardiograma transesofágico","D":"o paciente deve receber estreptoquinase e aspirina, se tiver tomografia de crânio normal","E":"a pressão arterial deve ser controlada com droga de ação lenta"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-26446","number":"26446","sourceNumber":"26446","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente apresentou-se no ambulatório queixando-se de que pela manhã, sentiu o\nolho direito irritado, e ao olhar no espelho notou que não conseguia fechá-lo. Verificou ainda que o\nlado direito da face parecia imóvel. Tentou beber água e notou que ela escapava pelo canto da\nboca. Em sua opinião ele tem lesão de que nervo?","options":{"A":"3°, 4° e 6° pares cranianos","B":"5° par craniano","C":"7° par craniano","D":"5° e 7° pares cranianos","E":"5°, 7° e 12° pares cranianos"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-26680","number":"26680","sourceNumber":"26680","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem de 72 anos de idade, tabagista, diabético com hipertensão arterial apresentou\nquadro súbito de afasia e déficit motor à\ndireita, força muscular graduada em 3 em Membro\nSuperior Direito e 4 em Membro Inferior Direito. A causa mais comum de infarto cerebral é:","options":{"A":"aterosclerose","B":"Síndrome de anticorpos antifosfolipidios.","C":"fibrilação atrial","D":"Hiperplasia hipertensiva da íntima","E":"Vasculites"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-26674","number":"26674","sourceNumber":"26674","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual das medidas abaixo não é mandatória no acompanhamento dos pacientes com\nhipertensão intracraniana?","options":{"A":"Uso de diuréticos","B":"Drenagem liquórica","C":"Hiperventilação","D":"Uso de barbitúricos","E":"Traqueostomia"},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-7453","number":"7453","sourceNumber":"7453","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com relação à hemorragia subaracnoidea analise as afirmativas abaixo e identifique\nqual não é verdadeira:","options":{"A":"O declínio da hipertensão arterial sistêmica na população se acompanhou de marcada queda na\nincidência da hemorragia subaracnoidea.","B":"Os fatores de risco incluem: tabagismo, abuso de álcool, drogas ilícitas, entre outros.","C":"A principal causa dessa hemorragia é: ruptura de aneurismas saculares (congênitos).","D":"O sintoma clássico é uma cefaleia intensa, de aparecimento súbito em geral descrita como ?a\npior dor de cabeça da minha vida?.","E":"A angiografia cerebral continua a ser o estudo definitivo para fechar o diagnóstico de hemorragia\nsubaracnoidea."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-10029","number":"10029","sourceNumber":"10029","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual das alternativas abaixo exibe os sinais cardinais da Doença de Parkinson?","options":{"A":"Tremor de intenção, hipertonia, bradicinesia e instabilidade postural.","B":"tremor de repouso, hipertonia, bradicinesia e instabilidade postural.","C":"tremor de repouso, hipotonia, bradicinesia e instabilidade postural.","D":"tremor de intenção, hipertonia, hipercinesia e instabilidade postural.","E":"tremor de repouso, hipertonia, bradicinesia e demência."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-324665","number":"324665","sourceNumber":"324665","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 76 anos de idade, procura atendimento na UBS por episódios de dor intensa\nem hemiface esquerda, principalmente em região\nmaxilar e de mandíbula, graduando até 8/10 na\nescala de dor. O quadro se repete há 3 anos, associado a sensação de choques e é precipitado\npela mastigação ou frio. Tem hipertensão arterial sistêmica, em uso de hidroclorotiazida e\nenalapril.\nAo exame, apresenta-se em bom estado geral, com sinais vitais estáveis, com alodínia térmica em\nhemiface esquerda. Demais exames segmentares sem alterações. Considerando o caso clínico\ndescrito, indique o diagnóstico mais provável:","options":{"A":"Nevralgia do nervo facial.","B":"Nevralgia do nervo trigêmeo.","C":"Cefaleia em salvas.","D":"Arterite de células gigantes."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-324666","number":"324666","sourceNumber":"324666","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 76 anos de idade, procura atendimento na UBS por episódios de dor intensa\nem hemiface esquerda, principalmente em região\nmaxilar e de mandíbula, graduando até 8/10 na\nescala de dor. O quadro se repete há 3 anos, associado a sensação de choques e é precipitado\npela mastigação ou frio. Tem hipertensão arterial sistêmica, em uso de hidroclorotiazida e\nenalapril.\nAo exame, apresenta-se em bom estado geral, com sinais vitais estáveis, com alodínia térmica em\nhemiface esquerda. Demais exames segmentares sem alterações. O exame complementar mais\nadequado para diagnóstico etiológico nesse caso:","options":{"A":"Ressonância magnética de crânio.","B":"Tomografia computadorizada de crânio.","C":"Eletroencefalograma.","D":"Biópsia da artéria temporal."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-324667","number":"324667","sourceNumber":"324667","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 76 anos de idade, procura atendimento na UBS por episódios de dor intensa\nem hemiface esquerda, principalmente em região\nmaxilar e de mandíbula, graduando até 8/10 na\nescala de dor. O quadro se repete há 3 anos, associado a sensação de choques e é precipitado\npela mastigação ou frio. Tem hipertensão arterial sistêmica, em uso de hidroclorotiazida e\nenalapril.\nAo exame, apresenta-se em bom estado geral, com sinais vitais estáveis, com alodínia térmica em\nhemiface esquerda. Demais exames segmentares sem alterações. Diante do quadro, indique a\nmelhor opção terapêutica para controle da dor:","options":{"A":"Tramadol e oxigenioterapia.","B":"Analgésico comum e escalonar para opioides, conforme resposta.","C":"Carbamazepina, oxcarbamazepina ou gabapentina.","D":"Analgésico comum associado à corticoterapia."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-34924","number":"34924","sourceNumber":"34924","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente, 30 anos de idade, sexo masculino, previamente sadio, é internado com\nhistória de cefaleia súbita e diminuição do\nnível de consciência. Chega sonolento ao hospital,\nrespondendo de modo coerente ao examinador, quando é solicitado . Não havia déficit motor focal\naparente. Dados vitais eram normais. É, então, submetido a uma TC de crânio, que mostra\nhemorragia subaracnoide difusa, sem camadas verticais de sangue maiores que 1 mm. Diante do\nquadro, é correto afirmar:","options":{"A":"O paciente está em escore (1) da escala de Fisher e seu risco de vasoespasmo arterial cerebral\né baixo.","B":"O paciente está em escore (4) da escala de Hunt-Hess e seu risco de vasoespasmo arterial\ncerebral é alto, devendo receber nimodipina venosa.","C":"O paciente está em escore (2) da escala de Fisher e seu risco de vasoespasmo arterial cerebral\né intermediário.","D":"O paciente está em escore 13 da escala de Glasgow, portanto seu risco de vasoespasmo\narterial cerebral é baixo.","E":"O paciente está em escore (3) da escala de Fisher, portanto seu risco de vasoespasmo arterial\ncerebral é alto, devendo receber nimodipina oral."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-34933","number":"34933","sourceNumber":"34933","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem, 70 anos de idade, hipertenso, dislipidêmico, diabético, chega ao hospital\nalerta, orientado, com disartria moderada,\nsorriso assimétrico (normal em repouso), paresia do\nolhar conjugado, sem déficit motor nos quatro membros e sensibilidade preservada. Realiza uma\nTC de crânio, sem anormalidades iniciais. Frente ao caso, é CORRETO afirmar que esse paciente,\nsegundo o National Institute of Health (NIH):","options":{"A":"Está em escore 5 da escala da NIH para AVC e, portanto, deve ser submetido à trombólise pelo\nalto risco de lesão isquêmica definitiva.","B":"Está em escore 2 da escala da NIH para AVC e, portanto, deve receber AAS, estatina e\nhidratação venosa, devendo permanecer em observação para monitorização de dados vitais e\nrepetição de nova TC de crânio em 48 horas.","C":"Está em escore 3 da escala da NIH, com alta probabilidade de melhora espontânea,\nindependente de trombólise.","D":"Está em escore 4 de AVC agudo na escala da NIH, portanto, com indicação de trombólise pelo\nalto risco de lesão isquêmica definitiva.","E":"Preenche 5 pontos na escala de AVC agudo da NIH, devendo receber AAS, estatina, além de\nindicação de trombólise, devendo permanecer internado para monitorização de dados vitais e\nrepetição de TC de crânio."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-34987","number":"34987","sourceNumber":"34987","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na avaliação de um paciente com quadro clínico de encefalopatia metabólica, é\nincorreto afirmar:","options":{"A":"Hipoxemia e hipercapnia podem provocar alterações típicas de encefalopatia metabólica em\npacientes com insuficiência pulmonar subjcente.","B":"Hiperglicemia grave é o suficiente para provocar alterações do estado mental e raramente ocorre\nisolada de outros transtornos\n\nmetabólicos.","C":"A encefalopatia urêmica pode surgir de maneira aguda, convulsões não são esperadas nessa\nsituação, sendo um dos sinais dessa\n\nsíndrome a ocorrência de delirium, um dos últimos sinais de uremia a aparecer.","D":"A terapia da encefalopatia hepática é dirigida para a redução das concentrações de substâncias\ntóxicas, que estão sendo desviadas para o\ncérebro. A recuperação neurológica está relacionada à\ncapacidade do fígado de regenerar, pelo menos, 25% de sua função.","E":"Episódios de encefalopatias hepáticas, repetidas ou prolongadas, podem levar ao aparecimento\nde sinais persistentes e irreversíveis de\ndisfunção dos núcleos da base, como tremores e\nparkinsonismos, quadro clínico que é conhecido como degeneração\n\nhepatocerebral."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-27487","number":"27487","sourceNumber":"27487","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente, 7 anos de idade, residente em zona rural, queixou-se de dormência na\nnádega esquerda, de início havia 40 dias. Nos\núltimos 15 dias, notou dor lombar de intensidade\ncrescente, dormência na perna esquerda, não conseguindo andar e retenção urinária. Ao exame\nclínico, hepatoesplenomegalia. Hemograma revelou leucocitose moderada sem desvio à esquerda.\nLiquor com elevação de proteínas e de células linfócitos não se isolando agente bacteriano. A\nressonância magnética da medula espinhal revelou aumento volumétrico da medula torácica baixa\ne do cone medular com captação de contraste (níveis T11, T12 e L1), conforme a figura (VER\nIMAGEM). A terapêutica, para esse paciente, é indicar","options":{"A":"anticoagulantes e corticoide.","B":"penicilina e ceftriaxona venoso.","C":"hidratação e oxacilina venosa.","D":"cirurgia.","E":"esquistossomicidas e corticoide."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-343342","number":"343342","sourceNumber":"343342","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Outra forma de TB do sistema nervoso central é a forma localizada (tuberculomas).\nPodemos indicar como correto o item:","options":{"A":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento rápido , com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode\nnão estar presente.","B":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre sempre\ndeve estar presente.","C":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode não\nestar presente.","D":"Nessa apresentação, o quadro clínico não é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode não\nestar presente."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-218153","number":"218153","sourceNumber":"218153","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um adulto de 32 anos, sexo masculino, comparece à consulta na Unidade de Saúde da\nFamília do seu bairro, queixando-se de: cefaleia com forte intensidade, unilateral à direita, de\nduração aproximada de 30 minutos, podendo chegar até duas horas, acompanhada de hiperemia\nconjuntival, lacrimejamento no olho direito, rubor em hemiface direita e, eventualmente, congestão\nnasal. Os sintomas iniciaram há dois meses e os ataques de dor ocorrem várias vezes ao dia.\n\nSobre esse caso clínico, é CORRETO afirmar que o diagnóstico é e o\ntratamento profilático recomendado é\n. A alternativa que preenche, CORRETA\ne sequencialmente, as lacunas do trecho acima é:","options":{"A":"Cefaleia em salvas / Verapamil.","B":"Cefaleia em salvas / Amitriptilina.","C":"Cefaleia tensional / Sumatriptana.","D":"Enxaqueca com aura / Amitriptilina.","E":"Enxaqueca sem aura / Sumatriptana."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-218171","number":"218171","sourceNumber":"218171","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre as cefaleias, analise as assertivas e identifique com V as verdadeiras e com F as\nfalsas. ( ) Pode-se estabelecer o diagnóstico para migrânea se um(a) usuário(a) apresentar mais de\numa crise cefaleia com duas das seguintes características: caráter pulsátil, náuseas ou vômitos,\nintensidade moderada a grave e localização unilateral. ( ) São consideradas indicações para o início\nda terapia profilática da enxaqueca crises com frequência maior que uma vez na semana, quando\ninterferem significativamente no dia a dia do usuário, quando há uso excessivo de medicamentos\npara outras patologias, quando os medicamentos da terapia abortiva apresentam efeitos adversos\ne/ou são ineficazes e de acordo com a preferência do usuário. ( ) O tratamento da migrânea pode\nser feito com a estratégia \"passo a passo\", na qual se introduz um medicamento por vez, do menos\npotentes ao mais, e se ajusta ou associa em função da resposta terapêutica do usuário, ou com a\nestratégia que estratifica o tratamento em função da intensidade e das características do problema\ndo usuário. A segunda apresenta melhores resultados clínicos e evita maior tempo de dor com\nsofrimento do usuário, mas a primeira tem menos efeitos colaterais. A alternativa que contém a\nsequência CORRETA, de cima para baixo, é:","options":{"A":"F, F, V.","B":"F, V, V.","C":"F, V, F.","D":"V, V, F.","E":"V, F, V."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-157684","number":"157684","sourceNumber":"157684","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Escolha a associação INCORRETA entre o segmento do nervo espinhal e a respectiva\nárea de inervação:","options":{"A":"S4 e S5 ? Região perianal.","B":"T10 ? Mamilo.","C":"C7 ? Dedo médio.","D":"L4 ? Face medial da perna."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-157694","number":"157694","sourceNumber":"157694","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Nos doentes portadores de lesão medular, são encontrados com frequência alguns\npadrões característicos de lesão neurológica. Sobre a Síndrome de Brown-Séquard, indique a\nalternativa CORRETA.","options":{"A":"É caracterizada pela desproporção entre a perda motora nas extremidades superiores, que é\nmuito mais acentuada que nos membros inferiores.","B":"Caracteriza-se por paraplegia e por dissociação da perda sensorial com a perda de sensibilidade\na dor e temperatura.","C":"Caracteriza-se por comprometimento motor ipsilateral e perda da sensibilidade postural,\nconcomitantes com a perda contralateral da sensibilidade térmica e dor.","D":"De todas as lesões incompletas, é a que tem pior prognóstico."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-157677","number":"157677","sourceNumber":"157677","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"?Tradicionalmente, considera-se que a lesão cerebral traumática é leve quando o\nquadro evolui com ausência de sinais\nneurológicos focais e o paciente apresenta um nível de\nconsciência igual ou superior a na avaliação pela escala de coma de Glasgow.? Assinale a\nalternativa que preenche a lacuna ADEQUADAMENTE.","options":{"A":"10","B":"11","C":"12","D":"13"},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-157640","number":"157640","sourceNumber":"157640","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente masculino, 67 anos de idade, foi transportado ao hospital por resgate com\nquadro de prostração intensa, dificuldade de\nfala, perda dos movimentos do lado direito do corpo.\nEle foi encontrado assim em sua casa há 1 hora, sendo que previamente estava em bom estado\ngeral, segundo familiares. Sua pressão era de 220 x 130 mmHg. Sobre esse quadro, aponte a\nalternativa CORRETA:","options":{"A":"Caso indicado trombólise, devemos tolerar essa PA a fim de proteger área de penumbra.","B":"No máximo, podemos tolerar uma PA de 180 x 110 mmHg.","C":"Em caso de sangramento, a redução da PA a nível de 140 mmHg reduz sequelas no desfecho.","D":"A fim de preservarmos área de penumbra, o ideal seria normotensão em 24 horas."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-134776","number":"134776","sourceNumber":"134776","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Pacientes, com graves patologias neurológicas, necessitam tanto de\nmonitorização, quanto de intervenção na dita\nPressão Intra Craniana. Qual dos parâmetros,\ncondutas ou achados abaixo listados, NÃO causa influência direta na Pressão Intra craniana?","options":{"A":"PCO2 arterial.","B":"Pressão arterial média.","C":"Posicionamento da cervical.","D":"Hiperemia Cerebral."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-139767","number":"139767","sourceNumber":"139767","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente masculino, 73 anos de idade, previamente diabético e hipertenso, procura\nhospital com ajuda dos filhos, com quadro de\nmal-estar geral, perda motora no membro inferior\nesquerdo e que agora se estende também para o membro superior homolateral. Sua pressão está\nelevada com valor de 210 x 110 mmHg. Sobre esse caso, assinale a alternativa CORRETA:","options":{"A":"O valor tolerável da pressão nessa situação depende de se existem complicações ou de se está\nproposta trombólise, caso confirmado AVC isquêmico com critério de trombólise.","B":"Reduzir a PA a 180 x 110 mmHg.","C":"Tolerar essa PA.","D":"Normalizar a PA em uma hora, pois se trata de emergência hipertensiva."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-139771","number":"139771","sourceNumber":"139771","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente hipertensa e diabética tipo 2 refere intensa cefaleia, a pior de sua via,\nalém de vômitos e turvação visual. Utiliza ambulatoriamente Captopril, Hidroclorotiazida e\nMetiformina. Realizada tomografia de crânio sem achados, assim decidido por Tomografia com\ncontraste, a pedido do neurologista. Podemos assim AFIRMAR que:","options":{"A":"a tomografia exclui lesões isquêmicas.","B":"o uso de contraste não consegue mudar a conduta.","C":"é necessário suspender metiformina para realização do exame com contraste.","D":"não existe necessidade de mudança de conduta no momento."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-111825","number":"111825","sourceNumber":"111825","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma medida necessária, a fim de abordarmos adequadamente o paciente com\nhipertensão intracraniana, é a pressão de perfusão\ncerebral. Qual dos itens abaixo NÃO faz parte\ndo seu cálculo?","options":{"A":"Pressão intracraniana.","B":"Pressão arterial média.","C":"Pressão venosa central.","D":"Pressão sistólica."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-350893","number":"350893","sourceNumber":"350893","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 40 anos é atendida no ambulatório com queixa de cefaleia. Relata que o\nquadro iniciou-se na adolescência, inicialmente\nno período menstrual. Sempre foi caracterizado por\ndor em lado direito da cabeça, associada a náuseas e fotofobia, com duração de 3 a 8 horas.\n\nConseguia lidar bem com isso até cerca de 3 meses, quando recebeu diagnóstico de esclerose\nsistêmica durante investigação de desconforto em\nmãos associado a palidez local seguida de\narroxeamento e vermelhidão. Refere quadro de tristeza após essa descoberta, mas nega\nalterações do sono, alimentação ou perda de interesse por atividades prazerosas. Entretanto, relata\nque a frequência das dores de cabeça passou a ser a cada 2 ou 3 semanas e tem interesse em\nfazer uso de profilaxia medicamentosa. Qual das medicações abaixo é mais apropriada para esta\npaciente?","options":{"A":"Verapamil.","B":"Propranolol.","C":"Amitriptilina.","D":"Sumatriptano."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-321320","number":"321320","sourceNumber":"321320","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Adolescente, 12 anos, iniciou quadro de tosse produtiva e descarga nasal amarelada\nhá 2 semanas, evoluindo há 24 horas com\nfebre, cefaleia intensa, vômitos, proptose, dor e edema\nperiorbitário à direita, associado a oftalmoparesia ipsilateral. Qual é a principal hipótese\ndiagnóstica?","options":{"A":"Meningite.","B":"Pseudotumor cerebral.","C":"Leucemia mieloide aguda.","D":"Trombose de seio cavernoso."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-292824","number":"292824","sourceNumber":"292824","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 30 anos procura atendimento no posto de saúde devido a episódios de\ncefaleia holocraniana em aperto, desde os 20 anos.\nDurante os episódios, a paciente deixa de fazer\natividades cotidianas, assim como prefere ficar em seu quarto com janela fechada e sem barulho.\n\nAo tentar fazer atividade física durante os episódios, relata piora dos sintomas com dor pulsátil em\nregião temporal. Nega vômitos durante os episódios. Se não tomar analgésicos, a paciente refere\nque fica até dois dias com dor. Faz uso de paracetamol 1 grama durante os episódios e, em\nalgumas ocasiões, faz uso deste medicamento mais de duas vezes ao dia. Nos últimos meses,\napresenta em média 8 crises ao mês. É portadora de asma e tem exame físico e neurológico\nnormais. Qual das medicações a seguir deve ser utilizada na paciente acima para diminuir a\nocorrência de crises de cefaleia?","options":{"A":"Topiramato.","B":"Naratriptano.","C":"Propranolol.","D":"Dipirona."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-259713","number":"259713","sourceNumber":"259713","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente 30 anos, feminino, procura atendimento em UPA devido a quadro de cefaleia.\nA paciente apresenta crises de cefaleia desde\nos 15 anos, algumas vezes incapacitantes,\npreferindo locais mais calmos e com pouca luminosidade, deixando de fazer atividades de rotina\nquando está com dor de cabeça. Alguma das crises são associadas com náuseas e vômitos. Ela\nprocura o atendimento com crise semelhante, com vômitos, iniciada há aproximadamente 20 horas,\nporém sem apresentar melhora com o uso de analgésicos que usa de rotina. Nega outras queixas\nou condições médicas relevantes. Exame físico e neurológico sem alterações. Pressão Arterial\n110x70mmHg, Pulso 90 batimentos por minuto. Qual a melhor conduta farmacológica para essa\npaciente, no momento?","options":{"A":"Dipirona 1 grama via oral.","B":"Tramadol 100mg endovenoso.","C":"Dexametasona 10mg endovenoso.","D":"Metoclopramida 10mg endovenoso."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-234063","number":"234063","sourceNumber":"234063","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Pedro, lactente de 11 meses, com anemia falciforme, há 2 dias vem apresentando febre\nmoderada acompanhada de inapetência e três episódios de vômitos. Há 6 horas o lactente foi\natendido na emergência com piora do estado geral, toxemia e aparecimento de lesões purpúricas\ndisseminadas. Realizado exame do líquor que mostrou pleocitose e presença de diplococos\n\ngram-negativo. Cultura do líquor evidenciou Neisseria meningitidis. Pedro frequentou a creche em\nperíodo integral até ser encaminhado a emergência. Sabendo-se que a rifampicina está em falta\nnas farmácias do SUS, qual outra medicação pode ser utilizada na quimioprofilaxia dos lactentes\ncomunicantes dessa creche?","options":{"A":"Isoniazida via oral durante 2 dias, apenas nos lactentes com vacinação incompleta.","B":"Ciprofloxacino via oral durante 2 dias, independente do estado vacinal dos lactentes.","C":"Ceftriaxona intramuscular em dose única, independente do estado vacinal dos lactentes.","D":"Penicilina benzatina intramuscular em dose única, apenas nos lactentes com vacinação\nincompleta."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-199802","number":"199802","sourceNumber":"199802","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente feminina, 38 anos, procura atendimento médico na centro de saúde com\nqueixa de cefaleia quase todos os dias.\nSegundo a paciente, desde os 20 anos ela tem episódios\nde cefaleia holocraniana, de caráter pulsátil, com fotofobia e fonofobia, impedindo de fazer\natividades rotineiras. Ela relata que inicialmente as dores melhoravam com analgésicos, e\naconteciam raramente. Porém, nos últimos anos, observou que as crises estão mais duradouras e\nocorrendo de 2 a 3 vezes por semana. Nega vômitos nos episódios, assim como sintomas\npremonitórios ou desencadeantes. Relata episódios prévios de cálculo renal e asma. Faz uso de\nanticoncepcional oral. Pressão Arterial 140 x 80 mmHg, pulso: 80. Exames físico e neurológico sem\nalterações. Qual a melhor opção terapêutica para a paciente acima?","options":{"A":"Topiramato.","B":"Propranolol.","C":"Candesartana.","D":"Carbonato de Lítio."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-150864","number":"150864","sourceNumber":"150864","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem, 58 anos, chega ao pronto-socorro com rebaixamento do sensório e confusão\nmental há 3 horas. Um familiar conta que há 1\nsemana ele vinha com coriza, obstrução nasal e\ntosse. Há um dia surgiram febre e cefaleia e hoje houve a piora. Ele move os quatro membros e\nsuas pupilas são médias e fotorreagentes. Estudo do líquor revelou 300 células/microlitro (90% de\nneutrófilos), glicose 16mg/dL e proteínas 85mg/dL. Além da vancomicina, quais dos antimicrobianos\nabaixo são a melhor escolha para compor seu esquema terapêutico empírico inicial?","options":{"A":"Cefepime e gentamicina.","B":"Ceftriaxona e ampicilina.","C":"Cefotaxima e piperacilina.","D":"Ceftazidima e metronidazol."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-126966","number":"126966","sourceNumber":"126966","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma criança de sete anos de idade apresenta subitamente quadro febril associado com\nalteração da consciência, manifestações neurológicas focais (hemiparesia), dor de cabeça,\nfotofobia. Há 30 minutos, teve convulsão no domicílio. Qual a principal hipótese diagnóstica?","options":{"A":"Intoxicação por chumbo.","B":"Hematoma subdural subagudo.","C":"Encefalite de provável etiologia viral.","D":"Meningite de provável etiologia bacteriana."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-102153","number":"102153","sourceNumber":"102153","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 67 anos, diabético e sedentário, apresentava quadro insidioso e\nprogressivo de perda de memória há 5 anos\ne, nos últimos 6 meses, vinha evoluindo com\ndificuldade de realizar suas atividades diárias, por prejuízo na linguagem (fluência e articulação\ndas\npalavras) e na realização de cálculos simples. O exame neurológico não demonstrava deficit\nmotores focais, rigidez de nuca ou alterações de pares cranianos. Quais seriam os achados\nhistopatológicos no sistema nervoso central mais característicos do diagnóstico mais provável\ndesse paciente?","options":{"A":"Placas amiloides.","B":"Corpúsculos de Pick.","C":"Corpúsculos de Lewy.","D":"Degeneração espongiforme."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-102165","number":"102165","sourceNumber":"102165","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente masculino, 70 anos, procura-o no consultório com queixas de esquecimentos\nfrequentes (como o número da sua conta\nbancária ou de sua identidade) e distanciamento familiar\npor apatia e déficit de concentração, nas últimas duas semanas. Ao examiná-lo você identifica um\nindivíduo orientado no tempo e no espaço, capaz de recordar seus eventos do dia á dia e fatos\nrelevantes de sua história. Ao ser apresentada uma lista com cinco palavras simples, este é capaz\nde repeti-las imediatamente, após um minuto de concentração e após 10 minutos durante os quais\nele realizou outras tarefas. Esse contexto deve deixá-lo atento para qual diagnóstico mais\nprovável?","options":{"A":"Transtorno depressivo menor.","B":"Demência degenerativa de Pick.","C":"Tumor do lobo temporal medial.","D":"Infarto da artéria cerebral anterior."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-81280","number":"81280","sourceNumber":"81280","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 47 anos é atendida em pronto-socorro por cefaleia. Relata dor em aperto em\ntodo o lado esquerdo da cabeça, associada a náuseas, fotofobia e fraqueza em braço e perna\ndireitos, quadro esse precedido por escotomas visuais cintilantes. Diz que apresenta cefaleia desde\nos 17 anos, com frequência de 2 por mês, principalmente no período perimenstrual. Usa alprazolam\npara síndrome do pânico. Ao exame físico, apresenta-se ansiosa e hiperventilando. O exame dos\nnervos cranianos e da sensibilidade estão normais. Há diminuição da força em membros do dimídio\ndireito (conseguindo vencer resistência leve) com dimídio esquerdo normal, hiperreflexia tendinosa\nprofunda em dimídio direito e reflexos normais em dimídio esquerdo. Com esse quadro, a paciente\nfoi medicada com analgésico e submetida à realização de ressonância nuclear magnética de\nencéfalo, que se mostrou normal. Após 2 horas, estava assintomática e o exame físico normal.\n\nQual o diagnóstico mais provável da paciente?","options":{"A":"Enxaqueca.","B":"Epilepsia focal.","C":"Transtorno conversivo somatoforme.","D":"Acidente isquêmico transitório aterosclerótico."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-65700","number":"65700","sourceNumber":"65700","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 75 anos, masculino, é levado por sua filha para consulta com seu médico\nde família. Esta se queixa de que seu pai\nrecentemente saiu de casa e foi encontrado em outro\nbairro, pois não lembrava seu endereço e nem como chegar em casa. A filha relata que este é o\nterceiro episódio nos últimos 3 meses. Nega outras alterações neurológicas. O paciente não faz uso\nde medicamentos. Nega patologias prévias. Diante desta situação, qual a conduta inicial mais\nadequada?","options":{"A":"Encaminhar o paciente para o geriatra.","B":"Realizar o mini exame do estado mental.","C":"Solicitar uma tomografia computadorizada de crânio.","D":"Encaminhar o paciente para uma unidade de pronto atendimento.","E":"Recomendar observação clínica, pois as alterações são decorrentes do processo natural de\nenvelhecimento."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-51223","number":"51223","sourceNumber":"51223","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 75 anos procura atendimento com ?problemas de memória?. No último ano,\napresenta dificuldades crescentes para transmitir recados e localizar objetos em seu domicílio. É\nhipertensa controlada há 25 anos com uso de hidroclorotiazida, sem outras comorbidades. A\npaciente está alerta, tem discurso organizado e está orientada no espaço, porém tem dificuldade\npara lembrar a data atual. Repete adequadamente 3 palavras não relacionadas quando solicitada,\nmas não consegue recordá-las após alguns minutos. Não consegue desenhar um relógio em um\ncírculo de papel. O restante do exame físico é normal. Hemograma, eletrólitos, glicemia, perfil\nlipídico, funções tiroidiana, renal e hepática estão normais. Qual das alterações abaixo será mais\nprovavelmente encontrada na ressonância nuclear magnética de encéfalo dessa paciente?","options":{"A":"Atrofia de tálamo.","B":"Atrofia de hipocampo.","C":"Atrofia de lobo frontal.","D":"Atrofia de corpos mamilares."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-51266","number":"51266","sourceNumber":"51266","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem de 52 anos, diabético, em uso de metformina, apresenta-se consciente, com\nafasia e hemiparesia direita há 2 horas.\nPreviamente sadio. Tomografia computadorizada do\nencéfalo mostrou ?borramento? do núcleo lenticulado esquerdo. PA 145 x 95 mmHg; Glicemia: 80\nmg/dl; hematócrito: 44%; plaquetas: 250.000/mm³; RNI: 1,0. Qual a principal conduta a ser adotada\nde imediato?","options":{"A":"Administração de aspirina 375 mg por via oral.","B":"Administração de manitol a 20%, 250 ml endovenosos, rápidos.","C":"Administração de ativador de plasminogênio tecidual endovenoso.","D":"Administração de glicose a 50%, cinquenta mililitros endovenosos."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-141575","number":"141575","sourceNumber":"141575","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual a causa mais comum de hemorragia intracraniana?","options":{"A":"Angiopatia amiloide.","B":"Hemorragia subaracnoidea.","C":"Transformação hemorrágica de AVE prévio.","D":"Hemorragia intraparenquimatosa hipertensiva ."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-141576","number":"141576","sourceNumber":"141576","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Quais das opções abaixo apresenta contraindicações ao uso da terapia trombolítica no\nAVE isquêmico?","options":{"A":"Melhora rápida dos sintomas; glicemia < 50 ou > 400; PA persistentemente > 185/110 a despeito\ndo tratamento.","B":"AVE isquêmico prévio; glicemia < 80 ou > 400; PA persistentemente > 160/110 a despeito do\ntratamento.","C":"Melhora rápida dos sintomas; uso crônico de aspirina; PA persistentemente > 185/110 a\ndespeito do tratamento.","D":"Melhora rápida dos sintomas; glicemia < 80 ou > 400; PA persistentemente > 185/110 a despeito\ndo tratamento."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-141587","number":"141587","sourceNumber":"141587","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação aos critérios de diagnóstico de demência, assinale a resposta CORRETA:","options":{"A":"Perda de memória é necessariamente a primeira alteração que o paciente apresenta ou a família\npercebe.","B":"As alterações do comportamento fazem parte dos critérios diagnósticos e ocorrem somente em\nfase avançada da doença.","C":"Perda de memória há de ser necessariamente um elemento presente para se estabelecer o\ndiagnóstico de demência.","D":"Alterações parkinsonianas fazem parte dos critérios diagnósticos da síndrome demencial."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-37606","number":"37606","sourceNumber":"37606","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Dentre as causas reversíveis de demência é possível citar as relacionadas abaixo,\nexceto:","options":{"A":"medicamentosa.","B":"metabólica.","C":"endócrina.","D":"vascular."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-37426","number":"37426","sourceNumber":"37426","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente feminina, 65 anos, diabética e hipertensa, referindo parestesias no membro\nsuperior esquerdo há uma semana e hoje\nevoluindo com hemiplegia esquerda e afasia. Trazida à\nemergência após 8 horas do início dos sintomas, onde é admitida consciente, hipertensa (PA 185 x\n120 mmHg), com exame físico sem alterações significativas, exceto a afasia e hemiplegia\nesquerda. A Tomografia Computadorizada de Crânio (TCC) sem contraste realizada na emergência\nfoi normal. Assinale a alternativa CORRETA:","options":{"A":"A TCC normal não afasta AVC isquêmico e a paciente deve ser internada para monitorização,\ntendo indicação de uso de trombolítico\nintravenoso, por ainda estar na janela de tratamento (até 12\nhoras do início dos\n\nsintomas).","B":"A TCC normal afasta AVC e a paciente deve ser\n\ninternada para monitorização e investigação da causa da plegia, que pode ser secundária à\nhipoglicemia, já que a paciente é diabética, ou a um tumor cerebral.","C":"A TCC normal não afasta AVC isquêmico e a paciente deve ser internada para monitorização,\nadministração de AAS, heparina profilática e controle da pressão arterial, sendo indicada redução\nrápida dos níveis tensionais através de uso de anti-hipertensivo venoso.","D":"A TCC normal não afasta AVC hemorrágico e a paciente deve ser internada para monitorização\ne investigação de possível aneurisma\nintraparenquimatoso através de arteriografia cerebral.","E":"A TCC normal não afasta AVC isquêmico e a paciente deve ser internada para monitorização,\nadministração de AAS, heparina profilática e controle da pressão arterial, não sendo indicada\nredução rápida dos níveis tensionais."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-30907","number":"30907","sourceNumber":"30907","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 29 anos procura atendimento por visão dupla e cegueira. Relata que há uma\nsemana vem tendo sintomas típicos de\ndiplopia e há dois dias consegue perceber somente vultos\nem ambos os olhos. Faz uso de anticoncepcionais orais há dois anos. Não possui nenhuma doença\nsistêmica e nem faz uso de quaisquer outras drogas. Exame físico evidencia: índice de massa\ncorporal = 31 kg/m², fundo de olho com edema de papila bilateral e diminuição importante da\nacuidade visual em ambos os olhos (20/200). Tomografia de crânio contrastada, realizada em\nsequência, foi normal. Punção lombar apresentou pressão de abertura de 43 cmH2O (normal < 20)\ncom análise citológica e bioquímica normais. Para definir-se o diagnóstico, que outro exame é\nnecessário?","options":{"A":"Angiorressonância encefálica.","B":"Ultrassonografia óptica.","C":"Ressonância nuclear magnética de neuroeixo.","D":"Tomografia por emissão de pósitrons.","E":"Doppler transcraniano."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-30911","number":"30911","sourceNumber":"30911","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem 55 anos procura atendimento por queixa de dificuldade para escrever. Para\ndemonstrar sua incapacidade, pede papel e\ncaneta. Ao começar, a escrita está aparentemente\nnormal, porém ainda nas primeiras palavras apresenta lenta e progressiva flexão do punho seguida\nde gradual rotação interna do antebraço que o impede de fazer mais que algumas frases. Qual o\ndistúrbio de movimento observado?","options":{"A":"Mioclonia.","B":"Distonia.","C":"Hemibalismo.","D":"Coreia.","E":"Atetose."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-8824","number":"8824","sourceNumber":"8824","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Posto de enfermagem solicita avaliação de um homem de 55 anos internado em\nenfermaria clínica. Referem que o mesmo\napresentou rebaixamento súbito do nível de consciência.\nDurante o exame, observa-se que o paciente obedece a comandos para abrir e fechar os olhos,\nporém não apresenta quaisquer outros movimentos, nem mesmo com estímulo doloroso. Não fala\nnem emite sons. Estava de olhos abertos durante todo o tempo da avaliação médica. Qual a\npontuação deste paciente segundo a Escala de Coma de Glasgow?","options":{"A":"6.","B":"7.","C":"8.","D":"10.","E":"11."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-17818","number":"17818","sourceNumber":"17818","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Jovem de 20 anos, sexo feminino, procura pronto-socorro com queixa de não conseguir\nfechar o olho esquerdo há cerca de 24h.\nNão houve trauma, nem exposições a medicamentos ou\ntóxicos. A paciente nega quaisquer outras patologias atuais ou prévias. Ao exame físico, nota-se\nincapacidade de ocluir ativamente a fenda palpebral esquerda e atenuação dos sulcos faciais\nesquerdos. Ao sorrir, a boca desvia-se para a direita. Ao enrugar a testa, há grande diferença entre\nas pregas cutâneas formadas na testa: à direita estão normais, à esquerda bem discretos. Além\ndas medidas de proteção da córnea, qual a melhor conduta a ser tomada nesta paciente?","options":{"A":"Solicitar TC de crânio","B":"Solicitar RNM de encéfalo","C":"Iniciar aciclovir e prednisona","D":"Iniciar carbamazepina","E":"Solicitar eletroneuromiografia facial"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-337553","number":"337553","sourceNumber":"337553","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 6 anos é levado ao pronto atendimento sendo relatado quadro febril\npela manhã (38,9°C) e apatia. Foi administrado\nantitérmico com melhora da temperatura. Durante o\ndia, voltou a ter febre e apresentou alguns vômitos e cefaleia. No momento da consulta, se\nencontra febril, prostrado e com falas desconexas. O restante do exame, sem particularidades,\ntendo sido aventada a hipótese de encefalite. Em relação ao caso clínico descrito e aos\nconhecimentos médicos relacionados, julgue o item a seguir. As encefalites são definidas como\ninfecções das membranas que envolvem e protegem o sistema nervoso central.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-337554","number":"337554","sourceNumber":"337554","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 6 anos é levado ao pronto atendimento sendo relatado quadro febril\npela manhã (38,9°C) e apatia. Foi administrado\nantitérmico com melhora da temperatura. Durante o\ndia, voltou a ter febre e apresentou alguns vômitos e cefaleia. No momento da consulta, se\nencontra febril, prostrado e com falas desconexas. O restante do exame, sem particularidades,\ntendo sido aventada a hipótese de encefalite. Em relação ao caso clínico descrito e aos\nconhecimentos médicos relacionados, julgue o item a seguir. O vírus causador de encefalite mais\nfrequente no Brasil é o Epstein-Barr.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-337555","number":"337555","sourceNumber":"337555","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 6 anos é levado ao pronto atendimento sendo relatado quadro febril\npela manhã (38,9°C) e apatia. Foi administrado\nantitérmico com melhora da temperatura. Durante o\ndia, voltou a ter febre e apresentou alguns vômitos e cefaleia. No momento da consulta, se\nencontra febril, prostrado e com falas desconexas. O restante do exame, sem particularidades,\ntendo sido aventada a hipótese de encefalite. Em relação ao caso clínico descrito e aos\nconhecimentos médicos relacionados, julgue o item a seguir. A encefalite é uma doença\nimunomediada, e as opções terapêuticas são a prescrição de corticoide e de imunoglobulina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-337556","number":"337556","sourceNumber":"337556","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 6 anos é levado ao pronto atendimento sendo relatado quadro febril\npela manhã (38,9°C) e apatia. Foi administrado\nantitérmico com melhora da temperatura. Durante o\ndia, voltou a ter febre e apresentou alguns vômitos e cefaleia. No momento da consulta, se\nencontra febril, prostrado e com falas desconexas. O restante do exame, sem particularidades,\ntendo sido aventada a hipótese de encefalite. Em relação ao caso clínico descrito e aos\nconhecimentos médicos relacionados, julgue o item a seguir. Cerca da metade das crianças que\ntiverem encefalite poderão evoluir com transtorno do déficit de atenção com hiperatividade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-337557","number":"337557","sourceNumber":"337557","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 6 anos é levado ao pronto atendimento sendo relatado quadro febril\npela manhã (38,9°C) e apatia. Foi administrado\nantitérmico com melhora da temperatura. Durante o\ndia, voltou a ter febre e apresentou alguns vômitos e cefaleia. No momento da consulta, se\nencontra febril, prostrado e com falas desconexas. O restante do exame, sem particularidades,\ntendo sido aventada a hipótese de encefalite. Em relação ao caso clínico descrito e aos\nconhecimentos médicos relacionados, julgue o item a seguir. Casos confirmados de encefalite por\nherpes-vírus simples devem ser tratados com aciclovir por 14 a 21 dias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-337558","number":"337558","sourceNumber":"337558","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 6 anos é levado ao pronto atendimento sendo relatado quadro febril\npela manhã (38,9°C) e apatia. Foi administrado\nantitérmico com melhora da temperatura. Durante o\ndia, voltou a ter febre e apresentou alguns vômitos e cefaleia. No momento da consulta, se\nencontra febril, prostrado e com falas desconexas. O restante do exame, sem particularidades,\ntendo sido aventada a hipótese de encefalite. Em relação ao caso clínico descrito e aos\nconhecimentos médicos relacionados, julgue o item a seguir. Se a neuroimagem revelar um\ncomprometimento do lobo temporal, a principal hipótese diagnóstica é encefalite por\ncitomegalovírus (CMV).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-305303","number":"305303","sourceNumber":"305303","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação à arterite temporal (ou arterite de células gigantes), é correto afirmar que","options":{"A":"o uso de anti-inflamatórios não esteroidais (AINE) está indicado.","B":"o uso de glicocorticoides em altas doses pode aumentar o risco de perda visual permanente.","C":"quase nunca ocorre antes dos 50 anos de idade.","D":"é mais comum na população afrodescendente.","E":"o tratamento é diferente nos casos em que a biópsia é inconclusiva."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-305316","number":"305316","sourceNumber":"305316","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 12 anos queixa-se de cefaleia recorrente, moderada, com intervalos\nvariáveis, de dias, semanas ou meses. A dor é\nbilateral e pulsátil e, por vezes, acompanhada de\nirritabilidade, anorexia e náusea. Antes do quadro de dor, vê \"bolinhas coloridas\" e sente\nformigamento na língua. Sobre o diagnóstico mais provável, assinale a alternativa CORRETA.","options":{"A":"O paciente está na faixa etária de menor incidência em pediatria.","B":"Podem fazer parte dos sintomas que precedem a dor: formigamento em hemicorpo, disfasia e\ndisartria.","C":"O paciente apresenta o tipo de quadro mais comum, que é o de dor precedida por sintomas\nvisuais e sensitivos.","D":"Para o diagnóstico adequado, é necessário investigar com tomografia de crânio e exames\nlaboratoriais.","E":"Casos familiares semelhantes são a exceção."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-261239","number":"261239","sourceNumber":"261239","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 42 anos de idade evolui com convulsões de início recente do tipo\nparciais complexas. Foi realizada uma tomografia\nde crânio com contraste que evidenciou uma\nmassa em lobo parietal direito, com contornos regulares, sugestivo de neoplastia primária. Durante\na internação, foram efetuadas mais três tomografias com contraste para verificar a existência de\noutros sítios de tumor cerebral. Após 72 horas de internação, apresentou piora da diurese com\nureia = 280 mg/dL e creatinina = 1,4 mg/dL. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Epidemiologicamente trata-se de craniofaringioma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-261241","number":"261241","sourceNumber":"261241","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 42 anos de idade evolui com convulsões de início recente do tipo\nparciais complexas. Foi realizada uma tomografia\nde crânio com contraste que evidenciou uma\nmassa em lobo parietal direito, com contornos regulares, sugestivo de neoplastia primária. Durante\na internação, foram efetuadas mais três tomografias com contraste para verificar a existência de\noutros sítios de tumor cerebral. Após 72 horas de internação, apresentou piora da diurese com\nureia = 280 mg/dL e creatinina = 1,4 mg/dL. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. A radioterapia nos tumores malignos do SNC pode ser\nutilizada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-284355","number":"284355","sourceNumber":"284355","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação à prevenção, à epidemiologia e à história natural das doenças, julgue o item\na seguir. O pneumococo pode causar doenças invasivas, como, por exemplo, pneumonia,\nbacteremia e sepse, sendo a segunda maior causa de meningite bacteriana no Brasil, que pode ser\nprevenida por vacina.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-250114","number":"250114","sourceNumber":"250114","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Acerca das patologias na infância, julgue o item a seguir. A síndrome de\n\nWaterhouse-Friderichsen na criança caracteriza-se por septicemia meningocócica, sem meningite,\nque se manifesta por sinais clínicos de choque\ne coagulação intravascular disseminada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-152168","number":"152168","sourceNumber":"152168","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, 39 anos de idade, negra, hipertensa prévia, pré-eclâmpsia\nna última gestação, apresenta crise\nconvulsiva tônico-clônica e é atendida na emergência do\nhospital. Não possui histórico prévio de convulsão. Ao chegar, estava em estado pós-ictal, Glasgow\n9, pressão arterial de 160 x 100 mmHg; FC = 105 bpm; FR = 16 irpm. O médico plantonista do local\nexamina a paciente, que está com pupilas fixas, anisocóricas, hemiparética à direita e\napresentando afasia motora. Solicita uma tomografia de crânio que evidencia hemorragia\nintraparenquimatosa em região frontotemporal esquerda, com hipótese diagnóstica de trombose\nvenosa de seio sagital. A paciente é internada no serviço de neurologia do hospital e sua prescrição\ncontém manitol, fenitoína, dexametasona e anticoagulante. Após dois dias de internação, paciente\nevolui com nova crise convulsiva e Glasgow 7. Com base nesse caso clínico, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. O sinal de delta vazio é um dos\nachados radiológicos esperados na trombose venosa de seio sagital.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-152172","number":"152172","sourceNumber":"152172","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, 39 anos de idade, negra, hipertensa prévia, pré-eclâmpsia\nna última gestação, apresenta crise\nconvulsiva tônico-clônica e é atendida na emergência do\nhospital. Não possui histórico prévio de convulsão. Ao chegar, estava em estado pós-ictal, Glasgow\n9, pressão arterial de 160 x 100 mmHg; FC = 105 bpm; FR = 16 irpm. O médico plantonista do local\nexamina a paciente, que está com pupilas fixas, anisocóricas, hemiparética à direita e\napresentando afasia motora. Solicita uma tomografia de crânio que evidencia hemorragia\nintraparenquimatosa em região frontotemporal esquerda, com hipótese diagnóstica de trombose\nvenosa de seio sagital. A paciente é internada no serviço de neurologia do hospital e sua prescrição\ncontém manitol, fenitoína, dexametasona e anticoagulante. Após dois dias de internação, paciente\nevolui com nova crise convulsiva e Glasgow 7. Com base nesse caso clínico, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. A anticoagulação melhora o\nprognóstico dessa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-152166","number":"152166","sourceNumber":"152166","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, 39 anos de idade, negra, hipertensa prévia, pré-eclâmpsia\nna última gestação, apresenta crise\nconvulsiva tônico-clônica e é atendida na emergência do\nhospital. Não possui histórico prévio de convulsão. Ao chegar, estava em estado pós-ictal, Glasgow\n9, pressão arterial de 160 x 100 mmHg; FC = 105 bpm; FR = 16 irpm. O médico plantonista do local\nexamina a paciente, que está com pupilas fixas, anisocóricas, hemiparética à direita e\napresentando afasia motora. Solicita uma tomografia de crânio que evidencia hemorragia\nintraparenquimatosa em região frontotemporal esquerda, com hipótese diagnóstica de trombose\nvenosa de seio sagital. A paciente é internada no serviço de neurologia do hospital e sua prescrição\ncontém manitol, fenitoína, dexametasona e anticoagulante. Após dois dias de internação, paciente\nevolui com nova crise convulsiva e Glasgow 7. Com base nesse caso clínico, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. Diparesia facial periférica,\ndisfagia, disartria e disfonia são esperadas se ocorrer acomentimento da musculatura bulbar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-135052","number":"135052","sourceNumber":"135052","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Julgue o próximo item, relativo a acidente vascular cerebral. Todo deficit neurológico\nagudo deve ser visto pelo médico como um\npossível acidente vascular isquêmico:","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-105547","number":"105547","sourceNumber":"105547","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em diversos ramos da medicina é necessário que se saiba manejar a dor, uma vez que\nela faz parte da grande maioria dos inúmeros quadros clínicos com que o médico se depara,\nindependentemente de sua especialidade. Para isso, é adequado que se diferencie a dor\nclassificada como neuropática daquela dita nociceptiva. Considerando essas informações, assinale\na alternativa que apresenta uma característica da dor neuropática:","options":{"A":"Secundária a dano tissular.","B":"Referida como \"em pressão\".","C":"Geralmente tem irradiação proximal.","D":"Descrita como lancinante, paroxística ou em formigamento.","E":"Sem associação com sinais autonômicos."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-108134","number":"108134","sourceNumber":"108134","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de sessenta e cinco anos de idade foi internado em uma unidade de\nemergência em virtude da apresentação súbita de desvio da comissura labial para a esquerda,\nparesia do membro superior direito e afasia. Após duas horas de internação do paciente, uma\nequipe da neurologia identificou o desaparecimento dos sintomas, entretanto foram encontradas\nmanchas hipocrômicas localizadas difusamente no tronco e nas extremidades, que apresentavam\nbaixa sensibilidade térmica. Com referência ao caso clínico acima apresentado, julgue o seguinte\nitem. O desvio da comissura labial para a esquerda associado à paresia do membro superior direito\né um indicador do diagnóstico de paralisia facial central.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-64720","number":"64720","sourceNumber":"64720","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma mulher, 42 anos de idade, com história prévia de febre reumática, com importante\nestenose da válvula mitral e fibrilação\natrial, foi admitida no setor de Cardiologia para realização de\nvalvotomia mitral por balão. Após a realização deste procedimento, a paciente começou a\napresentar alteração da consciência, vertigem e amaurose, bilateralmente. Neste caso, se for\naventada a possibilidade de um acidente vascular encefálico, assinale a alternativa que apresenta a\nprovável artéria acometida:","options":{"A":"Artéria cerebral média.","B":"Artéria cerebral anterior.","C":"Artéria cerebral posterior.","D":"Porção distal da artéria basilar.","E":"Ramos perfurantes da artéria cerebral média."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-27574","number":"27574","sourceNumber":"27574","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A demência tem se tornado na atualidade alvo de preocupação de diversos\npesquisadores, não só por sua prevalência,\nmas principalmente pela observação do crescente\nenvelhecimento populacional. Qual assertiva reúne dados corretos que merecem a consideração do\nclínico na abordagem à demência?","options":{"A":"As principais esferas da atividade mental comprometidas no portador de demência são a\nlinguagem, a habilidade visuoespacial, a emoção, a cognição, o sono, o humor e a memória.","B":"Testes de rastreamento, como o miniexame do estado mental, podem ser utilizados para\ndeterminação de um valor cognitivo numérico\nindependente da escolaridade e histórico cultural dos\nindivíduos avaliados.","C":"A maioria dos casos de disfunção cerebral induzida por medicamentos manisfesta-se como\ndelírio; já em idosos frágeis, o uso\ninapropriado pode causar demência. Os fármacos comunente\nassociados a estas questões são os benzodiazepínicos, antidepressivos tricíclicos, antipsicóticos,\nantitussígenos, digitálicos e anticolinérgicos.","D":"A incidência da doença de Alzheimer está inversamente relacionada ao aumento da idade e os\npadrões de transmissão em famílias.","E":"A demência vascular pode resultar de infartos únicos estrategicamente localizados, infartos\nmúltiplos, doença de pequenos vasos com infartos subcorticais e atrofia frontotemporal."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-8590","number":"8590","sourceNumber":"8590","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem de 72 anos de idade acompanhado de sua esposa procura assistência médica\ncom queixa de ?perda de memória?. Refere que\nguarda as chaves do carro e não se recorda\ndepois do local, tem dificuldade de aprender novas tarefas, como usar o celular que ganhou do filho\ne que, às vezes, durante conversa não consegue lembrar-se do nome de pessoas sobre a quais\ngostaria de tecer um comentário. A esposa não tem observado dificuldades no dia a dia do paciente\ne refere que ele continua desempenhando suas tarefas como antes. Quanto ao caso clínico é\ncorreto afirmar que: (MEEM = Miniexame do Estado Mental)","options":{"A":"trata-se de um caso de demência em sua fase precoce.","B":"o MEEM é fundamental para o diagnóstico de demência nessa situação.","C":"a ausência de perda funcional torna improvável o diagnóstico de demência.","D":"é necessária a realização de um exame de imagem para definição diagnóstica.","E":"definitivamente não se trata de um caso de demência."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-343420","number":"343420","sourceNumber":"343420","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente com meningite meningocócica deixa de transmitir a doença, em geral:","options":{"A":"Após o quinto dia de tratamento com antibióticos.","B":"Após o período de incubação.","C":"Após 24 horas do início da antibioticoterapia.","D":"Após cessarem todos os sintomas."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-273316","number":"273316","sourceNumber":"273316","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Lactente de 9 meses de idade, apresentando febre e irritabilidade há 24 horas, recusa\nalimentar e vômitos, evolui com convulsão tônico-clônica generalizada, com duração de cerca de 1\nminuto. A mãe refere que algumas vacinas estão atrasadas, mas não se encontra com o cartão\nvacinal. Ao exame físico: irritabilidade alternada com sonolência, ausência de sinais neurológicos\nlocalizatórios, fontanela anterior normotensa. T = 39°C, FC = 130 bpm, FR = 36 mrpm, PA = 80 x\n40 mmHg. Restante do exame físico sem alterações. Colhido líquor: 15.000 leucócitos/mm³ (80%\npolimorfonucleares), glicorraquia = 10 mg/100 ml, proteinorraquia = 180 mg/100 ml. O diagnóstico\nmais provável e o tratamento mais adequado são respectivamente:","options":{"A":"meningite bacteriana; Dexametasona e Ceftriaxone IV.","B":"meningoencefalite viral; antitérmico e Aciclovir IV.","C":"meningite bacteriana; Dexametasona e Penicilina Cristalina IV.","D":"convulsão febril; antitérmico e Fenobarbital IV."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-274598","number":"274598","sourceNumber":"274598","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Os medicamentos adjuvantes são representados por fármacos inicialmente\nempregados para outras finalidades que não o\ntratamento da dor, contudo, buscam melhorar o\ndesempenho afetivo-motivacional, o rendimento do tratamento analgésico, o sono e o apetite dos\nindivíduos enfermos. A alternativa que apresenta os fármacos que são benéficos no tratamento da\ndor, mormente se crônica, neuropática ou nociceptiva, e para a profilaxia da enxaqueca, é:","options":{"A":"Ansiolíticos.","B":"Anestésicos locais.","C":"Corticosteroides.","D":"Antidepressivos."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-268897","number":"268897","sourceNumber":"268897","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 20 anos de idade, com evolução aguda de cefaleia, febre e\ndesorientação, compareceu ao pronto atendimento.\nFoi realizada punção lombar, que demonstrou\nliquor com hipercelularidade à custa de neutrófilos, hiperproteinorraquia, hipoglicorraquia e\nbacterioscopia com diplococos Gram-positivos. Observaram-se PA = 100 mmHg x 70 mmHg, FR =\n100 bpm, FC = 20 irpm e SatO2 = 98%. O tratamento empírico antimicrobiano mais adequado e a\nprincipal suspeita de agente etiológico são:","options":{"A":"Ceftriaxone e Neisseria meningitidis.","B":"Ampicilina e Listeria monocytogenes.","C":"Ceftriaxone mais vancomicina e Streptococcus pneumoniae.","D":"Fluconazol e Cryptococcus neoformans.","E":"Cefazolina e Staphylococcus aureus."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-266463","number":"266463","sourceNumber":"266463","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um menino de dezoito meses de idade foi levado pela mãe à emergência de um\nhospital porque havia dois dias apresentava\nfebre alta, associada a vômitos e irritabilidade. O\nesquema vacinal era desconhecido. No exame físico, o médico assistente observou temperatura de\n39 °C, irritabilidade, petéquias disseminadas pelo corpo, predominantemente em extremidades.\n\nForam ainda observados sinais de irritação meníngea. Foi feita uma punção lombar, a qual\napresentou os seguintes resultados: aspecto: turvo: células: 1.000/mm³, com predomínio de\npolimorfonucleares; glicose: 20 mg/dL; proteínas: 150 mg/d; esfregaço Gram: diplococos\n\ngram-negativo. Com base no caso clínico precedente, julgue o próximo item. O diagnóstico clínico é\nde meningite bacteriana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-266464","number":"266464","sourceNumber":"266464","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um menino de dezoito meses de idade foi levado pela mãe à emergência de um\nhospital porque havia dois dias apresentava\nfebre alta, associada a vômitos e irritabilidade. O\nesquema vacinal era desconhecido. No exame físico, o médico assistente observou temperatura de\n39 °C, irritabilidade, petéquias disseminadas pelo corpo, predominantemente em extremidades.\n\nForam ainda observados sinais de irritação meníngea. Foi feita uma punção lombar, a qual\napresentou os seguintes resultados: aspecto: turvo: células: 1.000/mm³, com predomínio de\npolimorfonucleares; glicose: 20 mg/dL; proteínas: 150 mg/d; esfregaço Gram: diplococos\ngram-negativo. Com base no caso clínico precedente, julgue o próximo item. O tratamento\nespecífico inicial deve ser realizado com ceftriaxona na dose de 100 mg/kg/dia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-266465","number":"266465","sourceNumber":"266465","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um menino de dezoito meses de idade foi levado pela mãe à emergência de um\nhospital porque havia dois dias apresentava\nfebre alta, associada a vômitos e irritabilidade. O\nesquema vacinal era desconhecido. No exame físico, o médico assistente observou temperatura de\n39 °C, irritabilidade, petéquias disseminadas pelo corpo, predominantemente em extremidades.\n\nForam ainda observados sinais de irritação meníngea. Foi feita uma punção lombar, a qual\napresentou os seguintes resultados: aspecto: turvo: células: 1.000/mm³, com predomínio de\npolimorfonucleares; glicose: 20 mg/dL; proteínas: 150 mg/d; esfregaço Gram: diplococos\n\ngram-negativo. Com base no caso clínico precedente, julgue o próximo item. O agente etiológico\nmais provável é o Haemophilus influenzae B.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-263411","number":"263411","sourceNumber":"263411","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma mãe leva seu filho de 5 anos de idade para atendimento, na Unidade Básica de\nSaúde, relatando febre persistente há 24\nhoras, diminuição do apetite, náuseas e vômitos. A\ncriança amanheceu febril, com cefaleia e sede. A mãe relata que a criança frequentou uma festa de\naniversário há cerca de 5 dias. Ela tem vacinação em dia. No exame físico, os resultados de sua\navaliação foram os seguintes: pouco reativa; FC = 130 bpm; FR = 30 irpm; temperatura axilar =\n38,8 °C; Sat. O? = 96 %; mucosas desidratadas 3+/4+; petéquias puntiformes em membros\ninferiores, tórax e abdome. Ele possui dor à flexão da coluna cervical. Nesse caso, qual é a conduta\nmédica adequada?","options":{"A":"Suspeitar de infecção bacteriana e iniciar antibioticoterapia, dado o quadro de infecção de foco\ne\nde etiologia desconhecidos. Liberar a criança\npara casa com hidratação oral, antitérmico,\nantiemético, antibiótico, com retorno em 72 horas para reavaliação clínica.","B":"Solicitar hemograma para diferenciar etiologia viral ou bacteriana. Descartar meningite por\nHaemophilus do grupo B, pois a vacinação está atualizada. Liberar a criança para casa com\nhidratação oral, sintomáticos e retorno em 24 horas com resultado de exame.","C":"Acionar o Serviço de Atendimento Móvel de Urgência (SAMU) com encaminhamento à\nemergência, instituir hidratação venosa e isolamento, pois trata-se de um caso suspeito de\nCOVID-19 com provável infecção bacteriana secundária. Notificar o caso e isolar contactantes.","D":"Acionar o Serviço de Atendimento Móvel de Urgência (SAMU) com encaminhamento à\nemergência, com hidratação venosa,\nisolamento, antibioticoterapia e sintomáticos por tratar-se de\ncaso suspeito de meningite meningocócica. Notificar o caso e instituir tratamento profilático aos\ncomunicantes."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-244480","number":"244480","sourceNumber":"244480","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma criança de 2 anos de idade apresenta história de febre alta, falta de apetite e\nirritabilidade há dois dias. A mãe informou que a vacinação está completa e que, pela manhã,\nsurgiram petéquias no corpo do paciente. Ao exame físico, apresentava rigidez de nuca. A\nbacterioscopia do líquor mostrou a presença de meningococos. Considerando o período de\ntransmissão da infecção e o fato de o paciente ter um irmão de 4 anos de idade, assinale a\nalternativa que corresponde melhor conduta para a proteção dos contactantes em casa.","options":{"A":"Vacinação de todos os contactantes com vacina conjugada meningocócica C diante do surto.","B":"Quimioprofilaxia com rifampicina, por dois dias, para todos os contactantes intradomiciliares, o\nquanto antes.","C":"Vacinação apenas do irmão de 4 anos de idade (vacina: meningocócica do grupo C).","D":"Quimioprofilaxia com rifampicina apenas para o irmão de 4 anos de idade.","E":"Quimioprofilaxia com ciprofloxacino, quando o paciente tiver alta hospitalar."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-203136","number":"203136","sourceNumber":"203136","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 70 anos de idade com neoplasia de cólon em tratamento oncológico\nquimioterápico apresenta febre, cefaleia de forte intensidade holocraniana e alteração do nível\nmental com evolução há três dias. Apresenta, ao exame físico, sinais de irritação meníngea. A\ntomografia de crânio está normal. É realizada punção lombar que identifica sinais de meningite\nbacteriana com presença de bacilos Gram-positivos. Com relação a esse caso clínico, é correto\nafirmar que o germe e a terapêutica antimicrobiana apropriada são, respectivamente:","options":{"A":"S.epidermidis e vancomicina.","B":"Clostridium difficile e metronidazol.","C":"S.bovis e penicilina benzatina.","D":"E.coli e gentamicina.","E":"Listeria monocytogenes e ampicilina."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-206168","number":"206168","sourceNumber":"206168","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Os tumores cerebrais primários são um conjunto de neoplasias malignas originárias de\ncélulas de sustentação do tecido nervoso. A gradação dos tumores é baseada em aspectos\nhistopatológicos. Podemos considerar INADEQUADO que:","options":{"A":"A ressecção cirúrgica é o tratamento recomendado na maioria dos casos de tumor cerebral, com\nobjetivo de remover amplamente a neoplasia com a máxima preservação das funções neurológicas.","B":"Eventualmente, a localização do tumor em área eloquente permite apenas citorredução ou\nbiópsia da lesão.","C":"São tumores raros, correspondendo a 2% dos todos os cânceres conhecidos, com baixa\nmortalidade em adultos ? status pouco modificado pelo emprego das modalidades erapêuticas\ndisponíveis.","D":"O diagnóstico definitivo é firmado pelo estudo histopatológico de espécime tumoral obtido por\nbiópsia estereotática ou a céu aberto, sendo essencial para o planejamento terapêutico."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-206153","number":"206153","sourceNumber":"206153","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Assinale a alternativa CORRETA em relação às meningites bacterianas e virais:","options":{"A":"Na meningite viral sempre teremos sinais de irritação meníngea.","B":"A meningite bacteriana sempre causará febre acima de 39 ?C.","C":"A meningite viral não causa vômitos, e, portanto nunca necessita de internação hospitalar.","D":"Independente da etiologia, viral ou bacteriana, o antibiótico sempre será ceftriaxone."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-175122","number":"175122","sourceNumber":"175122","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com relação aos tumores do Sistema Nervoso Central, assinale a alternativa\nINCORRETA:","options":{"A":"Os sítios primários de metástase cerebral mais comuns são: pulmão, mama, melanoma e cólon.","B":"Astrocitomas correspondem a 50% dos tumores encefálicos primários.","C":"Fludrocortisona é indicado na maioria dos casos para redução do edema peritumoral.","D":"Anticonvulsivantes devem ser utilizados se o tumor é localizado próximo a área sensitivo-motora."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-154481","number":"154481","sourceNumber":"154481","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, 35 anos de idade, queixa-se de apresentar dor em face\nesquerda, em região maxilar e mandibular.\nRelata que a dor é de forte intensidade, ocorre em\nparoxismos, com início e término súbitos, havendo relação por vezes com a escovação dos dentes\nou mastigação. Procurou avaliação odontológica, porém não foram constatadas alterações\ndentárias ou bucais. Refere que, por vezes, chega a apresentar mais de 10 crises por dia, afetando\nseu humor e sua capacidade laboral. Qual o tratamento mais adequado para o agravo em questão?","options":{"A":"Sumatriptano.","B":"Nebulização com oxigênio a 100%.","C":"Carbamazepina.","D":"Prednisona.","E":"Ergotamínicos."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-168445","number":"168445","sourceNumber":"168445","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um menino com 5 anos e 11 meses de idade faz seguimento de rotina em Unidade\nBásica de Saúde desde o nascimento, sem\nantecedentes morbidos relevantes. Em sua última\nconsulta, há um ano, sua estatura era de 110 cm; na consulta atual está medindo 111 cm. Há 4\nmeses, passou a apresentar cefaleia holocraniana diária, de intensidade moderada a forte e\ndificuldade visual. A avaliação oftalmolóogica revelou hemianopsia bitemporal. A principal hipótese\ndiagnósticada para esse caso é","options":{"A":"cordoma.","B":"schwannoma.","C":"craniofaringeoma.","D":"tumor de plexo coroide."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-111328","number":"111328","sourceNumber":"111328","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Assinale a alternativa que apresenta achados que correspondem a um escore 9 na\nEscala de Coma de Glasgow:","options":{"A":"Abertura ocular ? à dor; melhor resposta verbal ?\npalavras inapropriadas; e melhor resposta motora ?\nretirada à dor.","B":"Abertura ocular ? à dor; melhor resposta verbal ?\npalavras inapropriadas; e melhor resposta motora ?\nextensão hipertônica à dor.","C":"Abertura ocular ? espontânea; melhor resposta verbal ? confuso; e melhor resposta motora\n\n? retirada à dor.","D":"Abertura ocular ? ao comando verbal; melhor\n\nresposta verbal ? sons incompreensíveis; e melhor resposta motora ? flexão hipertônica à dor.","E":"Abertura ocular ? nenhuma; melhor resposta verbal ? confuso; e melhor resposta motora\n\n? localiza a dor."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-111342","number":"111342","sourceNumber":"111342","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Assinale a alternativa que apresenta característica do quadro de delirium (confusão\nmental aguda) no idoso:","options":{"A":"Demosntração de distúrbio da consciência com redução do alerta em relação ao ambiente.","B":"Preservação da memória de fixação.","C":"Baixo comprometimento da linguagem e da cognição.","D":"Desenvolvimento gradual do quadro ao longo de meses ou anos.","E":"Presença de sintomas como agressividade e alimentação compulsiva."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-97830","number":"97830","sourceNumber":"97830","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um homem com 68 anos de idade é admitido em um Serviço de Emergência com febre\nalta, calafrios, cefaleia intensa, náuseas e\nvômitos, iniciados há 48 horas. A acompanhante do\npaciente informou que ele apresentou quadro de prostração e dor de garganta há cinco dias, porém\nnão procurou atendimento médico. Ao exame físico, apresentava-se em regular estado geral,\nletárgico e com raras lesões petequiais em tornozelos. O exame neurológico revelou sinais de\nirritação meníngea - rigidez de nuca, sinais de Kernig e Brudzinski. Foram solicitados exames\ncomplementares: 1) sangue - hemoglobina = 12,3 g/dl (Valor de referência = 13,5 - 17,5 g/dl);\nleucócitos = 17,500/mm³ (Valor de referência = 4,500 - 11,000/mm³), à custa de neutrofilia, com\ndesvio à esquerda; plaquetas = 127,000/mm³ (Valor de referência = 150.000-350.000/mm³);\nvelocidade de hemossedimentação = 76 mm/h (Valor de referência = 0-17 mm/h); 2) liquor - turvo,\nde aspecto purulento, com aumento do número de leucócitos e predomínio de neutrófilos\npolimorfonucleares; glicose e cloretos diminuídos, proteínas aumentadas; pesquisa direta para\nfungos negativa, bacterioscopia evidenciando a presença de diplococos Gram-negativos e cultura\nem andamento. Com base no quadro apresentado, qual o antibiótico de primeira escolha a ser\nadministrado?","options":{"A":"Ampicilina.","B":"Cloranfenicol.","C":"Ceftriaxona.","D":"Penicilina cristalina."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-97798","number":"97798","sourceNumber":"97798","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um homem com 38 anos de idade vem à consulta no ambulatório de clínica médica\nencaminhado da unidade básica de saúde por apresentar episódios recorrentes de cefaleia. As\ncrises iniciaram-se há dois anos, com cefaleia unilateral esquerda, de forte intensidade,\nacompanhada de lacrimejamento, rinorreia e ptose palpebral do mesmo lado da dor, durando de 20\na 30 minutos. O paciente relata que as crises ocorrem diariamente por cerca de duas semanas,\ncessando completamente e reiniciando, aproximadamente, seis meses depois. Os últimos\nepisódios ocorreram há quatro meses. O paciente refere uso de analgésicos comuns e naproxeno\ndurante as crises, relatando alívio apenas parcial, e nega a ocorrência de aura ou presença de\nfatores desencadeantes. A hipótese diagnóstica e a conduta a ser adotada para esse paciente são:","options":{"A":"Enxaqueca sem aura, sendo indicado iniciar profilaxia com amitriptilina.","B":"Arterite de células gigantes, necessitando de avaliação pelo reumatologista.","C":"Cefaleia tensional, devendo ser prescrito relaxante muscular como ciclobenzaprina.","D":"Cefaleia em salvas, devendo o paciente ser encaminhado para avaliação do neurologista."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-64439","number":"64439","sourceNumber":"64439","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente feminina, 65 anos, hipertensa, diabética e obesa, iniciou há mais ou menos 1\nhora quadro súbito de hemiparesia completa à direita. Realizou tomografia computadorizada de\ncrânio em intervalo de 60 minutos que evidenciou: (VER IMAGEM). Paciente após o exame\nmantém o quadro neurológico. O próximo passo será:","options":{"A":"Alta com acompanhamento ambulatorial com neurologista","B":"Se não houver contraindicações deve-se realizar terapia trombolítica o quanto antes","C":"Internação por 24 horas para acompanhamento","D":"Realização de punção liquórica","E":"Expansão volêmica agressiva"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-14/64439.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-75466","number":"75466","sourceNumber":"75466","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Lactente de nove meses, do sexo masculino, é admitido no pronto-socorro com história\nde irritabilidade, febre e choro persistente. Ao\nexame físico, apresenta-se pálido, discreta hiperemia\nde orofaringe, discreta limitação à flexão do pescoço e fontanela abaulada. O hemograma realizado\nno atendimento mostra discreta leucocitose (11.000 leucócitos/mm³) sem desvio à esquerda.\n\nPunção lombar mostrou liquor hipertenso e turvo, com 1.250 células, com 95% de neutrófilos;\nglicorraquia = 15 mg/dl; dosagem de proteínas no liquor = 345 mg/dl; presença de diplococos\nGram-negativos. Qual a hipótese diagnóstica mais provável?","options":{"A":"Meningite viral.","B":"Meningite bacteriana pneumocócica.","C":"Meningite bacteriana meningocócica.","D":"Meningite por Mycobacterium tuberculosis.","E":"Meningite sem agente etiológico determinado."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-75529","number":"75529","sourceNumber":"75529","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Lactente com 8 meses de idade, previamente hígido, foi admitido no pronto-socorro\ncom história de febre não aferida, recusa\nalimentar, irritabilidade e vômitos há dois dias. A mãe\ninformou que a criança não foi vacinada adequadamente. Ao exame físico, foi observado choro\nintenso e fontanela abaulada, sem outros sinais. Foi realizada punção lombar que mostrou liquor\n(LCR) com aspecto turvo; citometria de 2.300 céls/mm³, com 86% de neutrófilos; glicorraquia = 8\nmg% (abaixo de 2/3 da glicemia sanguínea); dosagem de proteína no liquor = 123 mg%. A\nbacterioscopia revelou a presença de bacilo Gram-negativo. Considerando o quadro clínico, a faixa\netária e os achados no LCR, o agente etiológico provável é:","options":{"A":"Escherichia coli.","B":"Neisseria meningitidis.","C":"Haemophilus influenzae.","D":"Streptococcus pneumoniae.","E":"Mycobacterium tuberculosis."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-137537","number":"137537","sourceNumber":"137537","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um lactente com 6 meses de idade, previamente hígido, em aleitamento materno, é\natendido em um Pronto Socorro Infantil com história de febre persistente há dois dias (temperatura\naxilar de até 38,9°C), acompanhada de irritabilidade e 2 a 3 episódios de vômitos por dia. Foi\nlevado\n\npreviamente a um serviço de saúde e a mãe foi orientada a oferecer soro de reidratação oral (SRO)\ne a retornar, caso não houvesse melhora\nou piorasse. A mãe informa que a irritabilidade da criança\naumentou nas últimas 12 horas, prejudicando a amamentação e a ingestão de líquidos. Nega tosse\ne diarreia. As vacinas estavam atualizadas. Ao examinar o lactente, o médico observou: bom\nestado geral e nutricional e irritabilidade ao manuseio. Realizada punção lombar, o\n\nresultado do exame do líquor foi: líquido límpido, com 300 células/mm com predomínio de\nlinfomononucleares, glicorraquia normal, proteínas levemente aumentadas. Com base no quadro\nclínico e nos resultados da análise do líquor, a associação diagnóstico-terapêutica correta é","options":{"A":"meningite bacteriana; tratamento hospitalar com antibioticoterapia, com necessidade de\nisolamento em UTI.","B":"meningite bacteriana; tratamento hospitalar com\nantibioticoterapia, sem necessidade de isolamento.","C":"meningite viral; tratamento hospitalar sem\nantibioticoterapia, sem necessidade de isolamento.","D":"meningite viral; tratamento hospitalar sem\nantibioticoterapia, com necessidade de isolamento.","E":"meningite tuberculosa; tratamento hospitalar com\nantibioticoterapia e com necessidade de isolamento."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-137580","number":"137580","sourceNumber":"137580","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma criança de 3 anos de idade foi atendida em Unidade de Pronto Atendimento com\nfebre de 39°C, irritabilidade, vômitos, sonolência e extremidades frias. Mesmo sem sinais de\nirritação\n\nmeníngea ou sepse, existe a suspeita de meningite. Para confirmá-la, o médico realizou punção\nlombar e solicitou a análise do líquido\ncéfalo-raquidiano (LCR). Que achado do LCR é indicativo de\nmeningite viral?","options":{"A":"Aspecto turvo.","B":"Glicose baixa.","C":"Proteína alta.","D":"Número baixo de células","E":"Número elevado de linfócitos."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-137611","number":"137611","sourceNumber":"137611","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma criança de 8 anos de idade é trazida por sua mãe ao Ambulatório de\nPediatria com queixa de cefaleia periódica\nhá 3 anos, com duração de até 24 horas/episódio e\ncom média de 15 episódios ao ano. Até hoje, faz o tratamento em casa com analgésicos e\nnunca procurou atendimento médico. Como as crises continuam, acarretando alterações no\ncomportamento e ausências escolares, a mãe resolveu trazer seu filho ao médico. A dor\napresenta as seguintes características semiológicas: é localizada, às vezes unilateral, pulsátil,\nalgumas vezes intensa e se agrava com atividade física rotineira. Normalmente, as crises vêm\nacompanhadas de fono e fotofobia. A mãe refere que o humor de seu filho muda\ncompletamente durante os períodos álgicos. Durante a crise, não há sintomas sensoriais,\nvisuais e nem disfasia. Há antecedentes familiares de cefaleia. Diante do relato clínico,\nconclui-se que o escolar apresenta","options":{"A":"cefaleia crônica tipo migrânea sem aura.","B":"cefaleia crônica progressiva por provável Tumor do SNC.","C":"cefaleia crônica por provável trombose vascular cerebral.","D":"cefaleia crônica em surtos por provável hipertensão arterial.","E":"cefaleia crônica recorrente por provável distúrbio psiquiátrico."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-30993","number":"30993","sourceNumber":"30993","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com relação à doença de Alzheimer, julgue o item a seguir. As alterações de linguagem\n(comprometimento da memória semântica), com a simplificação dos discursos e redução da\ndiversidade de palavras utilizadas, fazem parte do quadro clínico dessa doença.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-30996","number":"30996","sourceNumber":"30996","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com relação à doença de Alzheimer, julgue o item a seguir. A ressonância magnética\nnuclear contribui para o diagnóstico dessa doença, por descartar outras possíveis causas que\nexplicariam os sintomas apresentados pelos pacientes, como a presença de um hematoma\nsubdural crônico.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-19214","number":"19214","sourceNumber":"19214","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A Doença de Alzheimer, distúrbio neurovegetativo mais comum na população com mais\nde 60 anos de idade, atinge cerca de 5 milhões de pessoas nos Estados Unidos da América, e\nestima-se que, nos próximos 40 anos, mais de 16 milhões de pessoas serão diagnosticadas como\nportadoras dessa doença. Acerca das características dos distúrbios neurovegetativos, julgue o item\nseguinte. A memória está sempre preservada em pessoas saudáveis. Alterações ocorrem apenas\nem portadores de patologias que afetam o sistema nervoso central.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-19215","number":"19215","sourceNumber":"19215","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A Doença de Alzheimer, distúrbio neurovegetativo mais comum na população com mais\nde 60 anos de idade, atinge cerca de 5 milhões de pessoas nos Estados Unidos da América, e\nestima-se que, nos próximos 40 anos, mais de 16 milhões de pessoas serão diagnosticadas como\nportadoras dessa doença. Acerca das características dos distúrbios neurovegetativos, julgue o item\nseguinte. Distúrbios neurovegetativos, que causam queda da capacidade cognitiva, tendem a\naumentar com o aumento da idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-19226","number":"19226","sourceNumber":"19226","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Considere que uma paciente, com 60 anos de idade, tenha apresentado quadro de\nperda súbita da consciência precedida por\nacesso de tosse, tendo recobrado a consciência cerca\nde 1 minuto após a adoção de medidas de urgência. Considere ainda que, no exame físico, não\ntenha sido verificada nenhuma alteração, mas a revisão de seu histórico clínico revelou que era\nportadora de asma persistente grave. Nessa situação, a etiologia mais provável é distúrbio\nmetabólico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-19227","number":"19227","sourceNumber":"19227","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Considere que uma paciente, com 60 anos de idade, tenha apresentado quadro de\nperda súbita da consciência precedida por\nacesso de tosse, tendo recobrado a consciência cerca\nde 1 minuto após a adoção de medidas de urgência. Considere ainda que, no exame físico, não\ntenha sido verificada nenhuma alteração, mas a revisão de seu histórico clínico revelou que era\nportadora de asma persistente grave. Nessa situação, a etiologia mais provável é síncope de tosse.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-354103","number":"354103","sourceNumber":"354103","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um lactente é levado ao Pronto Atendimento com suspeita de meningite\nmeningocócica. Assinale a alternativa correta, de\nacordo com o Guia de Vigilância em Saúde do\nMinistério da Saúde:","options":{"A":"Não se deve realizar o exame da fontanela bregmática devido ao risco de acidente.","B":"Verificar a rigidez de nuca pelo fato de estar sempre presente ao exame clínico.","C":"É comum apresentar febre, irritabilidade, gemência e inapetência.","D":"A pesquisa de sinais meníngeos é mais simples pela facilidade de manuseio.","E":"Todas as alternativas estão corretas."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-359221","number":"359221","sourceNumber":"359221","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na sua enfermaria interna uma paciente de 78 anos com relato do filho de ter\napresentado \"redução da interação\" em uma\nevolução de 4 dias, iniciando com aumento de\ndependência para atividades de autocuidado e evoluindo nas primeiras 48 horas com rebaixamento\nde sensório, se mantendo dormindo por mais de 24 horas, quando foi levada ao hospital. Na sua\navaliação inicial, a paciente apresenta temperatura de 38,3°C, rigidez de nuca, flacidez muscular e\nsem hiperreflexia tendinosa profunda. Em relação ao caso, assinale a alternativa CORRETA.","options":{"A":"Uma tomografia de crânio no momento só seria necessária caso houvesse relato de TCE prévio.","B":"A presença de febre é um dado que ajuda a descartar sangramento de SNC, já que não\nocorreria nesses casos.","C":"A cobertura empírica de pacientes acima de 50 anos deve incluir Listeria monocytogenes.","D":"Esta paciente deve realizar punção lombar na urgência como primeira conduta."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-320420","number":"320420","sourceNumber":"320420","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A quimioprofilaxia da doença meningocócica, embora não assegure efeito protetor\nabsoluto e prolongado, tem sido adotada como\numa medida eficaz na prevenção de casos\nsecundários. Marque como verdadeiro (V) ou falso (F) os medicamentos utilizados na\nquimioprofilaxia da doença meningocócica. ( ) Rifampicina. ( ) Ceftriaxona. ( ) Ciprofloxacino.\n(\n\n) Pirainamida. ( ) Isonizida. Marque a alternativa com a sequência correta, de cima para baixo:","options":{"A":"V ? V ? F ? F ? F.","B":"V ? V ? V ? F ? F.","C":"V ? V ? V ? V ? V.","D":"V ? F ? F ? V ? V","E":"F ? F ? F ? F ? F."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-337626","number":"337626","sourceNumber":"337626","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente sexo masculino, 32 anos, procurou atendimento no pronto atendimento\nreferindo que iniciou há cerca de uma semana\ncom uma dor de cabeça importante, unilateral,\nintermitente e predominantemente à noite. Relata ainda que apresenta corrimento nasal e ocular\nassociados. Sem comorbidades nem uso de medicações, informa que não apresentou melhora com\ndipirona. Assinale a alternativa que apresenta CORRETAMENTE a principal hipótese diagnóstica e\nconduta.","options":{"A":"Cefaleia por abuso de analgésicos e iniciar naproxeno.","B":"Migrânea como áurea e iniciar triptanos.","C":"Hemorragia subaracnoidea e pedir TC de crânio.","D":"Cefaleia em salvas e oxigenoterapia."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-320436","number":"320436","sourceNumber":"320436","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Adolescente, sexo feminino, 8 anos, é levado à emergência por cefaleia intensa,\nvômitos em jato há dois dias e febre (40°C)\nque não cede com antitérmicos. Exame físico: febril,\nsinais de irritação meníngea, escala de Glasgow de 15, Punção lombar: pleocitose, com 600\ncélulas/mm3, 19.000 hemácias/ mm3, com predomínio de linfo mononucleares; proteína: 45mg/dL;\nglicorraquia: 65mg/ dL (glicemia: 89mg/dL). Esse quadro clinico sugere:","options":{"A":"Trauma de punção.","B":"Meningite bacteriana.","C":"Meningite viral.","D":"Hemorragia subaracnoide.","E":"Liquor normal para idade."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-336280","number":"336280","sourceNumber":"336280","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança de 7 anos chega ao pronto socorro com relato de cefáleia e febre iniciados há 1\ndia. Hoje iniciaram episódios de vômitos associada a prostração. Ao exame: regular estado geral,\nhipocorado, algo desidratado, acianótico, TAX: 39,2°C, nível de consciência rebaixado, rigidez de\nnuca, PA: 144x94 mmHg. Qual a conduta mais adequada neste caso?","options":{"A":"Iniciar tratamento com cefalosporina de terceira geração e em seguida, realizar punção lombar.","B":"Iniciar tratamento com cefalosporina de terceira geração, realizar tomografia de crânio e depois,\nse possível, punção lombar.","C":"Realizar punção lombar e iniciar tratamento com cefalosporina de terceira geração.","D":"Realizar punção lombar, colher hemograma e hemocultura e, caso haja alteração, iniciar\ntratamento com cefalosporina de terceira geração."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-291918","number":"291918","sourceNumber":"291918","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma menina de 7 anos é avaliada no pronto atendimento com queixa de cefaleia que,\nsegundo a mãe, teve início há três meses, com intensidade progressiva. A dor atinge toda a cabeça\ne piora ao acordar. Ao exame clínico, notou-se alteração do equilíbrio e da coordenação motora.\n\nNesse caso, é CORRETO afirmar que o exame indicado como complementar ao diagnóstico, é:","options":{"A":"A radiografia do crânio.","B":"O eletroencefalograma.","C":"O eletroneuromiografia.","D":"A ressonância magnética de crânio."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-291624","number":"291624","sourceNumber":"291624","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Adolescente, sexo feminino, 12 anos, é levado à emergência por cefaleia intensa,\nvômitos em jato há três dias e febre (39?C) que\nnão cede com antitérmicos. Exame físico:\ndesidratado, febril, sinais de irritação meníngea, escala de Glasgow de 15. Punção lombar: liquor\nturvo, coloração xantocromia, com 600 células/mm3, com predomínio de neutrofilos; proteína:\n150mg/dL; glicorraquia: 30mg/ dL (glicemia: 90mg/dL). Esse quadro clínico sugere:","options":{"A":"Trauma de punção.","B":"Meningite viral.","C":"Hemorragia subaracnoide.","D":"Meningite bacteriana.","E":"Gastroenterite Bacteriana."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-260685","number":"260685","sourceNumber":"260685","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança, sexo feminino, 9 anos, é levado ao pronto socorro, por cefaleia intensa,\nvômitos em jato há três dias e febre (38,8°C).\nExame físico: hipocorado, febril, sinais de irritação\nmeníngea. Realizado Punção lombar: pleocitose, com 540 células/mm3, 19.000 hemácias/ mm3,\ncom predomínio de linfomononucleares; proteína: 45mg/dL; glicorraquia: 66mg/ dL (glicemia:\n90mg/dL). Esse quadro clínicosugere:","options":{"A":"Meningite viral.","B":"Trauma de punção.","C":"Meningite bacteriana.","D":"Hemorragia subaracnoide.","E":"Empiema subdural"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-234410","number":"234410","sourceNumber":"234410","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma mulher de 26 anos se queixa de crises de cefaleia unilateral, pulsátil, muito\nintensa, que dura um dia inteiro e\nacompanha-se de náuseas. Não apresenta melhora com o uso\nde dipirona, paracetamol e ibuprofeno. As crises ocorrem 2 vezes por semana e comprometem a\nfuncionalidade da paciente. Não possui doenças atuais ou histórico de doenças prévias e não faz\nuso diário de medicamentos. Ao exame físico, apresenta-se alerta e orientada. Os dados vitais são\nPA: 150 X 88mmHg, FC: 86bpm, FR: 16ipm e SpO? 98%. O restante do exame físico não\napresenta anormalidades. Considerando o quadro clínico descrito, assinale alternativa que\napresenta a conduta MAIS ADEQUADA para o tratamento das crises e para a prevenção das\ncefaleias, respectivamente:","options":{"A":"Di-hidroergotamina; hidroclorotiazida.","B":"Naratriptano; metoprolol.","C":"Prednisona; topiramato.","D":"Tramadol; venlafaxina."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-232111","number":"232111","sourceNumber":"232111","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na possibilidade de um caso de doença meningocócica, a conduta a ser adotada é\nnotificar a doença...","options":{"A":"em até 7 dias, para registro no sistema.","B":"após resolução do problema, para evitar falsa notificação.","C":"até 24 horas, a partir da confirmação diagnóstica.","D":"até 24 horas, a partir da suspeita.","E":"em caso do problema ocorrer em creche, devido ao risco de disseminação."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-234424","number":"234424","sourceNumber":"234424","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 6 anos com drepanocitose, evoluiu com meningite bacteriana, confirmada\npelo liquor. Assinale a alternativa que apresenta\nCORRETAMENTE o agente mais provável.","options":{"A":"Chlamydia trachomatis.","B":"Staphylococcus aureus.","C":"Pseudomonas aeruginosa.","D":"Streptococcus pneumoniae."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-199635","number":"199635","sourceNumber":"199635","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 58 anos de idade foi admitido no pronto-socorro por cefaleia supraorbitária\ndireita, de fortíssima intensidade,\nintermitente (2 a 4 eventos ao dia), com duração aproximada de 1\nhora, há 4 dias. Nos últimos 5 anos, o paciente apresentou cerca de 8 crises com características\nsemelhantes às da atual, com duração aproximada de 1 mês. Ao exame foram constatadas as\nseguintes alterações: edema palpebral, hiperemia conjuntival, miose e lacrimejamento restritos ao\nolho direito. Qual das condutas emergenciais abaixo é a mais apropriada para o caso?","options":{"A":"Abortamento da crise com dexametasona endovenosa (dose única) e alta para investigação\nambulatorial.","B":"Abortamento da crise com inalação de oxigênio e alta para investigação ambulatorial.","C":"Abortamento da crise com anti-inflamatório endovenoso, tomografia e angiotomografia do crânio\ne internação para investigação.","D":"Dipirona endovenosa, tomografia do crânio com e sem contraste e punção lombar se tomografia\nnormal."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-199507","number":"199507","sourceNumber":"199507","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A cefaleia é a terceira forma de dor mais comum entre crianças e adolescentes. Sobre\nessa doença, assinale a alternativa INCORRETA:","options":{"A":"Na maioria dos pacientes com cefaleias crônicas recorrentes, a anamnese e o exame físico são\nsuficientes para o estabelecimento do diagnóstico da forma de cefaleia, sem necessidade de\nexames complementares.","B":"O sumatriptano é uma droga muito utilizada na profilaxia da migrânea.","C":"A migrânea com e sem aura, assim como a cefaleia tensional, são exemplos de cefaleias na\ninfância e na adolescência.","D":"A migrânea pode ter como complicação a crise epiléptica."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-196776","number":"196776","sourceNumber":"196776","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 23 anos, com episódios recorrentes de cefaleia desde os 17 anos de idade.\nAtualmente, tem tido crises fortes mais de 6 dias por mês, ao ponto de atrapalhar suas atividades\ndiárias. A dor é bilateral, pulsátil, com fotofobia, fonofobia e geralmente dura mais de 4 horas,\nchegando a durar, às vezes, mais de 24 horas. Assinale a alternativa mais adequada.","options":{"A":"Topiramato nas crises e propranolol para profilaxia.","B":"Sumatriptana nas crises e topiramato para profilaxia.","C":"Amitriptilina para profilaxia e opioide nas crises.","D":"Anti-inflamatório não esteroidal nas crises."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-126904","number":"126904","sourceNumber":"126904","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação ao AVC isquêmico analise as afirmativas abaixo: I. A tomografia\ncomputadorizada de crânio é o exame de imagem\nescolhido inicialmente na suspeita de AVCi. II. O\nAAS deve ser utilizado em até 48 horas nos pacientes com AVCi não submetidos a terapia\ntrombolítica. III. A associação do clopidogrel com AAS reduz a incidência de novo AVCi sem\naumentar os riscos de sangramento. IV. O controle adequado da glicemia, temperatura e pressão\narterial são importantes para preservar a ?área de penumbra?. Está(ão) CORRETA(S) a(s)\nafirmativa(s).","options":{"A":"I apenas.","B":"I e II apenas.","C":"I, II, III e IV.","D":"I, II e IV apenas."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-106394","number":"106394","sourceNumber":"106394","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A terapêutica da dissecção aguda de artéria carótida interna deve ser conduzida por:","options":{"A":"intervenção cirúrgica de urgência.","B":"anticoagulação.","C":"antiagregação isoladamente.","D":"colocação de stent.","E":"intervenção cirúrgica após estabilização do quadro."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-100995","number":"100995","sourceNumber":"100995","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em um paciente com acidente vascular isquêmico está indicado:","options":{"A":"Manter pressão arterial sistólica abaixo de 120 mmHg, preferencialmente com vasodilatadores\nendovenosos.","B":"Manter níveis glicêmicos normais, corrigindo a hiperglicemia com insulina.","C":"Uso de trombolíticos em até 6 horas após início dos sintomas.","D":"Em caso de necessidade de sedação, uso de barbitúricos devido ao efeito neuroprotetor.","E":"Indução de hipotermia."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-101008","number":"101008","sourceNumber":"101008","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A Síndrome de Wernicke-Korsakoff é caracterizada pelos seguintes achados, exceto:","options":{"A":"Confusão mental, disartria, ptose palpebral.","B":"Confusão mental, nistagmo, tremores.","C":"Amnésia retrógrada, diplopia, alucinações.","D":"Ataxia, amnésia anterógrada, confabulações.","E":"Amnésia anterógrada, amnésia retrógrada, nistagmo."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-88914","number":"88914","sourceNumber":"88914","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre convulsão febril (CF) são verdadeiras (V) ou falsas (F) as afirmativas abaixo: ( )\nA história familiar constitui fator de risco tanto para as recorrências das CF quanto para o\ndesenvolvimento de epilepsia. ( )Para a maioria dos pacientes o tratamento profilático é\ndispensável. ( ) Não há consenso sobre a associação entre alterações eletroencefalográficas e\nrisco de epilepsia. ( ) As CF podem preceder síndromes epilépticas. ( ) A idade da 1ª crise se\nrelaciona a risco de epilepsia. Assinale a alternativa correta:","options":{"A":"V F V F V.","B":"V V V F F.","C":"F V F V F.","D":"F V V F V.","E":"V V V V F."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-88887","number":"88887","sourceNumber":"88887","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 87 anos, admitida hemiplégica, torporosa, afásica, com quadro iniciado há\ncerca de 2 horas. ECG mostra Fibrilação atrial. A melhor conduta é:","options":{"A":"Anticoagular, imediatamente, com Heparina e Marevan, caso CT de crânio descarte\nsangramento cerebral.","B":"Intubação orotraqueal, CT de crânio, e anticoagulação dentro das primeiras duas semanas após\nAVC caso não haja sangramento cerebral.","C":"Heparina em bolus, e não usar Marevan.","D":"Intubação orotraqueal, e anticoagulação plena imediatamente.","E":"Paciente muito idosa. Contraindicada anticoagulação. Manter tratamento conservador."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-43959","number":"43959","sourceNumber":"43959","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 78 anos procurou atendimento ambulatorial por lentidão de movimento\ne quedas frequentes nos últimos 07 meses. Ao\nexame neurológico, apresentou disartrofonia,\nbradicinesia e hipertonia plástica simétricas, teste da retropulsão francamente positivo e\nhipometria\ndas sacadas verticais. Dentre as doenças abaixo listadas, qual a que melhor explica as alterações\nsemiológicas deste caso?","options":{"A":"Atrofia de múltiplos sistemas.","B":"Hidrocefalia de pressão normal.","C":"Degeneração corticobasal gangliônica.","D":"Paralisia supranuclear progressiva.","E":"Parkinsonismo vascular."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-43966","number":"43966","sourceNumber":"43966","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Ao exame neurológico de uma paciente de 45 anos com história de fraqueza muscular\ndos membros inferiores há 5 meses, constataram-se\nas seguintes alterações: paraparesia crural\nsimétrica, reflexos miotáticos profundos exaltados nos quatro membros, reflexo cutâneo-plantar em\nextensão bilateralmente, marcha parético-atáxica, apalestesia e anartrestesia nos membros\ninferiores. Considerando-se as opções terapêuticas abaixo, qual a mais apropriada para o caso?","options":{"A":"Pulsoterapia com metilprednisolona.","B":"Descompressão cirúrgica.","C":"Vitamina B12 parenteral.","D":"Imunoglobulinoterapia.","E":"Praziquantel e prednisona."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-23138","number":"23138","sourceNumber":"23138","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente com emergência hipertensiva e acidente vascular cerebral. Assinale a\nresposta incorreta.","options":{"A":"A redução da pressão arterial em pacientes com Acidente Vascular Cerebral (AVCI) pode\naumentar a área isquêmica.","B":"Os bloqueadores de canais de cálcio são as drogas de escolha no tratamento da hipertensão\narterial na fase aguda de AVCI.","C":"A hipotensão arterial constitui um fator importante de lesão secundária no AVCI.","D":"Infarto cerebral extenso em território carotídeo com pontuação na escala de NIHSS (National\nInstitute of Health Strok Scale) acima de 22 é contraindicação para trombólise no AVCI.","E":"Nos infartos cerebrais hemisféricos, a depressão respiratória ocorre mais frequentemente após\n48-72 horas."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-9432","number":"9432","sourceNumber":"9432","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na síndrome extrapiramidal tóxica podem ser observados todos abaixo, EXCETO:","options":{"A":"Opistótono.","B":"Crise oculógira.","C":"Hipotonia.","D":"Tremor.","E":"Torcicolo."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-353845","number":"353845","sourceNumber":"353845","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com relação às características dos diferentes tipos de cefaleias, é CORRETO afirmar:","options":{"A":"A cefaleia em salvas é uma dor bilateral, geralmente sentida na região occipital, com duração\nmédia de 5 horas.","B":"A cefaleia em salvas é uma dor intensa, unilateral e orbitária, que pode durar de 30 minutos a 2\nhoras e ocorrer 1 ou 2 vezes ao dia.","C":"A migrânea sem aura é uma dor bilateral, de baixa intensidade e contínua, frequentemente\nassociada à anorexia e desidratação.","D":"A migrânea sem aura é uma dor geralmente bilateral, de curta duração, e frequentemente não\nacompanhada de sintomas como náuseas ou\nfotofobia."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-363979","number":"363979","sourceNumber":"363979","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 35 anos, do sexo feminino, procura o serviço médico relatando cerca de\nquatro episódios semanais de cefaleia pulsátil,\nde forte intensidade que duram até um dia\npredominando do lado direito da cabeça, melhorando com repouso em ambiente escuro e\nsilencioso, às vezes necessitando do uso de dipirona. As crises de dor são acompanhadas de\nnáuseas, já tendo ocorrido vômitos. Conta que esses episódios se iniciaram na adolescência\ndurante o período menstrual, mas há dois meses se tornaram muito frequentes após o início de\ndieta para controle de peso. Relata ter asma desde a infância, com uso de salbutamol inalatório só\nquando tem falta de ar. No exame físico, a paciente apresenta altura de 1,6 m, peso de 92 kg e\nsibilos ocasionais na ausculta pulmonar e extrassistoles na ausculta cardíaca. No restante, os\nexames físicos e neurológicos não apresentavam outras alterações. Um eletrocardiograma\nrealizado apresentou um aumento no intervalo QT e a radiografia de tórax foi normal. Nesse caso,\nalém das medidas para tratamento da dor durante os episódios de cefaleia, essa paciente\nnecessita de tratamento profilático com","options":{"A":"Propranolol 20 mg VO de 12 em 12 horas.","B":"Topiramato 25 mg VO de 12 em 12 horas.","C":"Amitriptilina 50 mg VO à noite.","D":"Clorpromazina 25 mg VO à noite."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-362688","number":"362688","sourceNumber":"362688","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sabe-se que o pneumoencéfalo é comum no pós-operatório de tumores cerebrais na\ninfância. Considerando a ocorrência de pneumoencéfalo, qual a primeira linha de tratamento?","options":{"A":"Trepanação e sucção do ar.","B":"Não se trata o pneumoencéfalo, pois reduz-se sozinho.","C":"A administração de oxigênio em altas concentrações.","D":"Medidas posturais, como decúbito a 45 graus."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-354835","number":"354835","sourceNumber":"354835","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente D.A.O., masculino, 28 anos de idade, solteiro, engenheiro civil, em tratamento\npara transtorno de ansiedade com venlafaxina 150\nmg 1 cps. Nega alergia a medicamentos, nega\netilismo, nega tabagismo e nega consumo de outras drogas, pratica natação 3 x por semana (50\nminutos por sessão). S1. Paciente refere que há 5 anos tem apresentado crises de cefaleias,\nsempre foi frequente, estima que nos últimos 3 meses tem passado mais de 15 dias por mês com\ncefaleia. A cefaleia é bilateral, em aperto, forte intensidade, atingindo o pico em poucas horas e\ncom piora na atividade física rotineira como caminhar e subir escadas. Paciente refere que como\nsintoma associado sempre apresenta náuseas e fonofobia, porém nega fotofobia. Nega: calafrios,\nfebre, mialgia, perda de peso, claudicação mandibular, sintomas neurológicos focais ou sistêmicos\n(nega inclusive sintomas como disfasia e positivos/negativos na visão/sensibilidade), agravação\npostural, precipitar por exercício/postura/tosse/relação sexual. O1. Sem papiledema, sem déficits\nneurológicos e algum grau de tensão muscular na cervical (sem configuração de ponto de gatilho).\nO complemento do registro do \"A\" no modelo SOAP, de acordo com a Terceira Edição da\nClassificação de Cefaleia do Comitê da Sociedade Internacional das Cefaleias (ICHD-3), é:","options":{"A":"A1: cefaleia tensional crônica diária sem sinal de alarme.","B":"A1: cefaleia tensional crônica diária com sinal de alarme.","C":"A1: enxaqueca crônica sem aura sem sinal de alarme.","D":"A1: enxaqueca crônica sem aura com sinal de alarme."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-331964","number":"331964","sourceNumber":"331964","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem, 30 anos, procura serviço de emergência com cefaleia, febre e vômitos há um\ndia. Antecedentes pessoais: diabetes tipo 1 desde os sete anos. Exame físico: regular estado geral,\neupneico; T 38,2°C; PA 130x80 mmHg; FC 90 bpm. Exame segmentar normal, rigidez de nuca\npresente. Exames laboratoriais: hemoglobina 13 g/dL; leucocitos 15.600/mm³ (12% bastões, 82%\nsegmentados). Liquor: leucocitos: 1.454/mm³ (88% neutrófi- los), proteína 140 mg/dL; glicose\n34mg/dL. Bacterioscopia: presença de diplococos gram positivos. A conduta é:","options":{"A":"Iniciar ceftriaxone imediatamente, dexametasona em até 12 horas do início do antibiótico.","B":"Iniciar ceftriaxone e dexametasona imediatamente.","C":"Iniciar ceftazidime e vancomicina, dexametasona em até 12 horas do início do antibiótico.","D":"Iniciar vancomicina imediatamente, dexametasona em até 4 horas do início do antibiótico."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-339768","number":"339768","sourceNumber":"339768","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 18 anos internado para tratamento de meningococcemia estava em\nuso de ceftriaxone há 3 dias, quando\nevoluiu com rebaixamento do nível de consciência que exigiu\nintubação orotraqueal. A médica que realizou o procedimento estava na 20a semana de gestação\ne, muito assustada, consultou a comissão de controle de infecção do hospital. Assinale a alternativa\nCORRETA sobre as medidas profiláticas que devem ser indicadas para essa médica.","options":{"A":"Antibioticoprofilaxia deve ser iniciada o mais rápido possível, de preferência nas primeiras 24\nhoras após a exposição.","B":"Não há indicação para uso de antibiótico profilático nesse caso.","C":"O esquema profilático de escolha, por ser aquele com maior respaldo na literatura, é rifampicina\nem 4 doses de 600mg de 12/12 horas.","D":"O esquema profilático mais seguro nesse caso, já que a médica está gestante, é dose única de\nceftriaxona 250mg por via intramuscular.","E":"Azitromicina em dose única de 500mg seria melhor indicada para o caso, devido à comodidade\nde posologia."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-337405","number":"337405","sourceNumber":"337405","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Das alternativas apresentadas abaixo, qual a incorreta sobre a investigação laboratorial\ndo paciente com encefalite?","options":{"A":"As amostras de outros sítios podem auxiliar na busca pela identificação do patógeno, como, por\nexemplo, a biopsia de lesão de pele associada.","B":"Recomenda-se que o líquor seja enviado para a pesquisa de herpes vírus por PCR.","C":"Os exames gerais, como hemograma, função renal e hepática, geralmente, trazem resultados\ninespecíficos, mas devem ser realizados para complementar a avaliação.","D":"A punção lombar deve ser sempre realizada, a não ser que contraindicada. O seu resultado\nauxilia na investigação porque sempre está\nalterado."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-330083","number":"330083","sourceNumber":"330083","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Considerando a potencial transmissão da doença, em geral, um paciente com\nmeningite meningocócica deixa de transmitir a doença:","options":{"A":"Após cessarem todos os sintomas.","B":"Após o quinto dia de tratamento com antibióticos.","C":"Após o período de incubação.","D":"Após 24 horas do início da antibioticoterapia."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-337414","number":"337414","sourceNumber":"337414","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A respeito da encefalite aguda pediátrica, assinale a alternativa correta.","options":{"A":"Não acomete crianças saudáveis.","B":"Imunodeficiências são a causa principal de acometimento.","C":"As formas mais severas da síndrome não costumam ser fatais.","D":"É mais frequente em crianças com menos de um ano de idade."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-342621","number":"342621","sourceNumber":"342621","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 55 anos, com cefaléia hemicraniana esquerda, de moderada intensidade\nassociada a desconforto à mastigação,\napresenta dor muscular na cintura pélvica e escapular. Qual\no tratamento mais indicado:","options":{"A":"prednisona","B":"ibuprofeno","C":"amitriptilina","D":"sumatriptano"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-346439","number":"346439","sourceNumber":"346439","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança de 06 meses, com diagnóstico de HIV, chega ao pronto socorro com história de\nfebre de 38°C e vômitos há 08 horas. Exame físico: hipoativa, com petéquias difusas e rigidez de\nnuca. Não se observa diurese em fralda desde o início do quadro. Além de controle de temperatura,\nqual a conduta mais adequada?","options":{"A":"Antibioticoterapia após coleta de líquor;","B":"Antibioticoterapia imediatamente;","C":"Antibioticoterapia se persistência do quadro clínico por pelo menos 24 horas;","D":"Antibioticoterapia se piora do quadro clínico nas próximas 24 horas."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-342651","number":"342651","sourceNumber":"342651","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma escolar de 7 anos é trazida à Emergência com episódios de vômitos e dificuIdade\nde ficar em pé. Tem história de cefaleia na\nregião occipital em aperto, há 2 meses, de forte\nintensidade e com aumento de frequência. Os episódios duram cerca de 6 horas, ocorrendo\nfrequentemente na madrugada, sem alívio com analgésicos. Ao exame físico, observam-se marcha\natáxica e com dismetria, além de paralisia do 6º par bilateralmente. Nega febre. A hipótese\ndiagnóstica mais provável é:","options":{"A":"enxaqueca basilar","B":"nfecção aguda","C":"tensão","D":"processo expansivo"},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-342677","number":"342677","sourceNumber":"342677","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um estudante de 16 anos dá entrada em serviço de pronto atendimento, acompanhado\nda namorada, com quadro clínico sugestivo de\nmeningite. Não foi realizado nenhum procedimento\ninvasivo no pronto atendimento. Trinta minutos após a entrada, o paciente foi transferido para um\nhospital de referência, onde foram coletados materiais biológicos para exames laboratoriais,\nincluindo liquor. Foi iniciado tratamento com ceftriaxona. O exame de liquor foi compatível com\nmeningite bacteriana, e a reação de látex no soro foi positiva para Neisseria meningitidis. Sobre a\nquimioprofilaxia da infecção pela N. meningitidis, assinale a alternativa correta:","options":{"A":"deverá ser iniciada nos contatos somente após a cultura do liquor comprovar o crescimento da\n\nN. meningitidis","B":"deverá ser realizada nos familiares que residem com o paciente, na namorada e nos colegas de\nturma que mantinham contato próximo, e na equipe do pronto atendimento","C":"o medicamento indicativo pelo Ministério da Saúde para a quimioprofilaxia dos contatos de\ncasos confirmados ou suspeitos é a rifampicina","D":"também está indicada para o próprio paciente para erradicação da bactéria de sua orofaringe,\nevitando assim o estado de portador"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-315791","number":"315791","sourceNumber":"315791","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Assinale a alternativa correta sobre os sintomas presentes na aura da migrânea.","options":{"A":"Os sintomas presentam natureza neurológica.","B":"A náusea, os vômitos, a fotofobia e a fonofobia podem ocorrer em conjunto ou isoladamente.","C":"As anormalidades transitórias dos campos visuais são frequentes.","D":"Os sintomas sempre precedem a cefaleia."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-294275","number":"294275","sourceNumber":"294275","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um homem de 48 anos que normalmente não tem dores de cabeça comparece ao\nconsultório. Ele tem uma história de melanoma, que foi tratada com sucesso. A dor de cabeça dele\ntem piorado no último mês e tem se mantido constante. A dor é profunda, em torno do lado\nesquerdo das regiões temporal e frontal esquerda. Ele admite ter febre baixa intermitente e leve\nperda de peso. Ele está preocupado porque sua mãe tinha \"algum tipo de tumor cerebral\". Qual dos\nsintomas é considerado um \"red flag\" na avaliação dessa dor de cabeça?","options":{"A":"Localização da dor.","B":"História familiar de tumor cerebral.","C":"Febre.","D":"Idade."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-295364","number":"295364","sourceNumber":"295364","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma paciente de 13 anos foi levada ao pronto-socorro com rebaixamento do nível de\nconsciência. A mãe relata que, no dia anterior, percebeu a filha mais lenta ao se deitar. Acordou\ncom o barulho dela se \"debatendo\" de madrugada por cerca de cinco minutos, após os quais ela\nficou muito sonolenta. Foi admitida sonolenta, com resposta inespecífica motora ao estímulo\ndoloroso, falando palavras desconexas e abrindo os olhos ao ouvir seu nome. O exame neurológico\nficou prejudicado pela sonolência, mas apresentava discreta rigidez de nuca, sem outras alterações\nrelevantes. Foi realizada uma tomografia computadorizada de crânio que veio sem alterações. O\nliquor foi colhido e estava límpido, com 10 células, 100% linfócitos, proteína e glicose normais.\n\nOptou-se por realizar uma ressonância magnética cerebral que apresentou discreto hiper-sinal em\nT2 e FLAIR nas regiões temporais. A\nprincipal hipótese diagnóstica para o caso é:","options":{"A":"Esclerose múltipla.","B":"Meningite bacteriana aguda.","C":"Acidente vascular encefálico isquêmico.","D":"Encefalite herpética."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-317951","number":"317951","sourceNumber":"317951","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 32 anos é trazida ao pronto-socorro agitada, queixando de cefaleia intensa,\nmuito gemente, com relato de vômitos há uma hora. A família conta que ela tem enxaqueca há\nmais de dez anos, com crises fortes a cada dois meses. A paciente diz que está é a pior dor que já\nsentiu, que piora quando deita e quando vomita. Seu exame neurológico está normal, exceto por\ndiscreta resistência a mobilização cervical. Além do uso de analgésico para alívio da dor no PS, o\nmédico deve:","options":{"A":"solicitar exame de imagem, como tomografia de crânio de urgência.","B":"observar a paciente por duas horas no PS com uso de clorpromazina e dexametasona.","C":"dar alta com profilaxia diária com amitriptilina à noite.","D":"dar alta hospitalar mantendo uso domiciliar do analgésico e antiemético."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-300944","number":"300944","sourceNumber":"300944","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Das alternativas apresentadas abaixo assinale a alternativa CORRETA sobre a\ninvestigação complementar do paciente com encefalite:","options":{"A":"A tomografia computadorizada de crânio pode ser realizada com o mesmo benefício da\nressonância magnética.","B":"As sorologias coletadas no sangue para determinados patógenos não podem contribuir para o\ndiagnóstico etiológico da encefalite.","C":"O líquor é, geralmente, o material mais importante na avaliação etiológica de um quadro de\nencefalite.","D":"A imagem do SNC deve ser realizada após 48 horas de história. Antes disso, não apresenta\nvalor diagnóstico."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-300946","number":"300946","sourceNumber":"300946","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Das alternativas apresentadas abaixo todas são queixas que podem auxiliar no\ndiagnóstico de tumor do SNC, exceto:","options":{"A":"Limitações de movimentos oculares.","B":"Tosse ao deitar.","C":"Convulsões.","D":"Perda de habilidades previamente adquiridas."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-300950","number":"300950","sourceNumber":"300950","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Das alternativas apresentadas abaixo assinale aquela que NÃO representa uma\ncomplicação da punção lombar após a coleta do liquor:","options":{"A":"Pneumotórax.","B":"Hematoma espinhal.","C":"Herniação cerebral.","D":"Cefaleia pós punção."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-294302","number":"294302","sourceNumber":"294302","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A quimioprofilaxia com rifampicina, embora não assegure um efeito protetor absoluto e\nprolongado, é indicada para os contatos próximos de pacientes com diagnóstico de meningite por:","options":{"A":"Haemophilus influenzae tipo B e Mycobacterium tuberculosis.","B":"Mycobacterium tuberculosis e Streptococcus pneumoniae.","C":"Neisseria meningitidis e Haemophilus influenzae tipo B.","D":"Streptococcus pneumoniae e Neisseria meningitidis."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-308283","number":"308283","sourceNumber":"308283","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A cefaleia é um sintoma clínico que, por vezes, se torna um desafio diagnóstico. A\nanálise dos dados, forma de manifestação,\ncaracterísticas dos pacientes são elementos que\ninfluenciam a avaliação clínica pré teste. Neste contexto, um dos exames de escolha para avaliação\ndas manifestações secundárias é o liquor, onde o diagnóstico de meningite é uma das hipóteses\ndiferenciais. Considerando a temática acima, responda as 02 questões que se seguem. Sobre as\nmeningites bacterianas agudas é verdadeiro afirmar que:","options":{"A":"É uma emergência médica.","B":"O alvo é iniciar antibioticoterapia em até 24 horas da chegada do paciente no pronto\natendimento.","C":"Dexametasona é contraindicada como adjuvante no tratamento.","D":"Nenhuma alternativa está correta."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-311962","number":"311962","sourceNumber":"311962","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação às cefaleias, é considerado um critério diagnóstico para migrânea pela\nSociedade Internacional de Cefaleias:","options":{"A":"Cefaleia em aperto ou opressão.","B":"Cefaleia de intensidade leve a moderada.","C":"Cefaleia de localização unilateral.","D":"Não ser agravado por atividade física de rotina (andar ou subir escadas)."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-308284","number":"308284","sourceNumber":"308284","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A cefaleia é um sintoma clínico que, por vezes, se torna um desafio diagnóstico. A\nanálise dos dados, forma de manifestação,\ncaracterísticas dos pacientes são elementos que\ninfluenciam a avaliação clínica pré teste. Neste contexto, um dos exames de escolha para avaliação\ndas manifestações secundárias é o liquor, onde o diagnóstico de meningite é uma das hipóteses\ndiferenciais. Considerando a temática acima, responda as 02 questões que se seguem. Nas\nmeningites agudas virais espera se que o liquor apresente:","options":{"A":"Pleiocitose linfocítica.","B":"Proteínas levemente elevadas.","C":"Concentração de glicose normal ou discretamente alterada.","D":"Todas alternativas estão corretas."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-308302","number":"308302","sourceNumber":"308302","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Meningite bacteriana é uma inflamação aguda das leptomeninges e do espaço\nsubaracnóide que ocorre por disseminação\nhematogênica, contiguidade ou trauma local. A\nquimioprofilaxia com rifampicina é indicada para os contatos íntimos de pacientes com diagnóstico\nde meningite por:","options":{"A":"Neisseria meningitidis e Streptococcus pneumoniae.","B":"Haemophilus influenzae tipo B e Neisseria meningitidis.","C":"Mycobacterium tuberculosis e Streptococcus pneumoniae.","D":"Haemophilus influenzae tipo B e Mycobacterium tuberculosis."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-285062","number":"285062","sourceNumber":"285062","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 35 anos, procura pronto atendimento com dor em hemicrânio direito, pulsátil, de\nforte intensidade, acompanhada de náuseas/vômitos, foto e fonofobia há 6 horas. Refere episódios\nprévios de cefaleia semelhantes ao atual. Nega uso de medicações contraceptivas. O exame\nneurológico é normal. Trata-se de:","options":{"A":"Cefaleia tensional. Tomografia de crânio é mandatória.","B":"Enxaqueca. Tomografia de crânio é mandatória.","C":"Enxaqueca. Não há necessidade de exame de imagem.","D":"De cefaleia tensional. Não há necessidade de exame de imagem.","E":"Cefaleia secundária. Tomografia de crânio é mandatória."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-273136","number":"273136","sourceNumber":"273136","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"O anticonvulsivante é uma classe de fármacos utilizada para a prevenção e tratamento\ndas crises convulsivas e epilépticas, bem como\nno tratamento dos transtornos de humor. Como um\nfármaco da classe dos anticonvulsivantes, encontra-se aquele que exerce atividade gabaérgica e\nproporciona alívio da dor em cerca de 25% dos doentes com neuralgia do trigêmeo resistente à\nCarbamazepina, o qual é chamado:","options":{"A":"Oxcarbazepina.","B":"Gabapentina.","C":"Clonazepam.","D":"Pregabalina."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-273144","number":"273144","sourceNumber":"273144","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Considerando a causa da meningite, é CORRETO afirmar:","options":{"A":"A meningite meningocócica é causada pela bactéria Neisseria meningitidis ou Neisseria\nintracellularis.","B":"O meningococo é uma bactéria do tipo diplococo que causa a doença tanto no ser humano\nquanto em animais.","C":"O meningococo é um vírus que não sobrevive muito na atmosfera.","D":"A meningite é uma doença de causa desconhecida."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-273150","number":"273150","sourceNumber":"273150","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A meningite tanto pode ser causada por vírus como por bactéria, sendo esta a mais\ncomum. A meningite é uma inflamação das membranas que recobrem e protegem o:","options":{"A":"Sistema linfático.","B":"Sistema nervoso.","C":"Sistema muscular.","D":"Sistema cardiovascular."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-281997","number":"281997","sourceNumber":"281997","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Interprete os resultados da análise do LCR a seguir, de um jovem com suspeita de\nmeningite: Aspecto: turvo; proteínas: 200 mg/dl; glicorraquia: 20 mg/dl; leucócitos 510/mm³ (80%\nseg e 10% linf); bacterioscopia: diplococos gram-positivos. O possível diagnóstico é:","options":{"A":"Meningite bacteriana provavelmente meningocócica.","B":"Meningite bacteriana provavelmente pneumocócica.","C":"Meningite bacteriana provavelmente por Haemophilus influenza.","D":"Meningite tuberculosa."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-257757","number":"257757","sourceNumber":"257757","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A.M.S., masculino, de 38 anos, saudável até então, vem apresentando febre baixa e\ncefaleia há três semanas e apresenta, há 12 horas, náuseas e vômitos em jato. Teste rápido de\nHIV negativo. Ao ser avaliado na UPA, apresentava confusão mental, rigidez de nuca e sinal de\nBrudzinski presente. O liquor foi retirado, apresentava-se turvo e, ao exame, apresentou os\nseguintes parâmetros: celularidade: 680 cel/mm³/88% linfomononucleares; proteína: 165 mg% (N =\n15?50) e glicose: 25 mg% (N = 45?100). Bacterioscopia e culturas em andamento. Nesse caso, a\npartir dos dados clínicos epidemiológicos, o diagnóstico mais provável é meningite:","options":{"A":"Estafilocócica.","B":"Meningocócica.","C":"Tuberculosa.","D":"Viral."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-274814","number":"274814","sourceNumber":"274814","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A cefaleia é um dos motivos de consulta mais prevalentes na atenção primária à saúde.\nSobre as cefaleias, marque a alternativa\ncorreta.","options":{"A":"Os critérios diagnósticos de migrânea sem aura incluem: localização unilateral, caráter pulsátil,\nintensidade moderada ou forte e o não agravamento por atividade física rotineira.","B":"A ergotamina deve ser utilizada no tratamento na migrânea com incapacidade leve à moderada,\nsendo a medicação que apresenta maior\nevidência de efetividade.","C":"São características encontradas na cefaleia atribuída à arterite temporal: início da cefaleia\napós\nos 30 anos de idade, maior incidência em\nhomens do que em mulheres, Velocidade de\nHemossedimentação (VHS) elevada e melhora da dor pela inalação de oxigênio a 100%.","D":"A cefaleia tensional é o tipo mais comum de cefaleia primária, podendo apresentar dolorimento\npericraniano, que aumenta com a intensidade da cefaleia."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-258235","number":"258235","sourceNumber":"258235","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de dois anos, que frequenta uma creche, foi diagnosticado com meningite\nbacteriana. No liquor, foi isolado o Streptoccus pneumoniae, sendo que a sorotipagem identificou o\nsorotipo 19A. Em relação à profilaxia antimicrobiana dos contactantes de sua sala, qual deve ser a\nconduta?","options":{"A":"Prescrever Rifampicina oral por dois dias.","B":"Prescrever Ceftriaxone intramuscular em dose única.","C":"Não prescrever a profilaxia.","D":"Prescrever Azitromicina oral em dose única."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-274833","number":"274833","sourceNumber":"274833","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Adolescente, sexo masculino, 13 anos, é levado à emergência por cefaleia intensa,\nvômitos em jato há dois dias e febre (38,5ºC)\nque não cede com antitérmicos. Exame físico:\ndesidratado, febril, sinais de irritação meningea, escala de Glasgow de 15. Punção lombar:\npleocitose, com 570 células/mm3, 20.000 hemácias/mm3, com predomínio de linfomononucleares;\nproteína: 45mg/dL; glicorraquia: 66 mg/ dL (glicemia: 90 mg/dL). Esse quadro clínico sugere:","options":{"A":"Trauma de punção.","B":"Meningite viral.","C":"Meningite bacteriana.","D":"Hemorragia subaracnoide."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-246520","number":"246520","sourceNumber":"246520","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente feminino, 27 anos, com história de cefaleia há 1 ano, com 4 a 5 episódios por\nsemana, sendo a maioria dos episódios caracterizados por cefaleia hemicraniana e pulsátil,\nnáuseas, necessita se trancar em quarto escuro e silencioso, pois o barulho e a luz intensificam as\ncrises de dor, assim como piora com o esforço físico. Nos antecedentes pessoais, paciente\napresenta história de chiado no peito quando resfriada ou quando corre. Considerando-se o quadro\nclínico, qual o principal diagnóstico e a profilaxia melhor indicada para o quadro?","options":{"A":"Migrânea crônica; propanolol.","B":"Hemicrânia paroxística; indometacina.","C":"Migrânea episódica; amitriptilina.","D":"Migranea crônica; amitriptilina.","E":"Migrânea espisóica; topiramato."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-248901","number":"248901","sourceNumber":"248901","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um paciente de 34 anos, apresentando cefaleia recorrente, foi diagnosticado com\ncefaleias em salvas ou \"cluster headache\". Quais são os sinais e sintomas mais prováveis para\nesse diagnóstico?","options":{"A":"cefaleia geralmente de moderada ou forte intensidade, pulsátil, unilateral com náuseas e/ou\nfotofobia, persistindo por 4 a 72 horas","B":"cefaleia geralmente de leve ou moderada intensidade, sensação difusa e dolorosa ou em\ncompressão em torno da cabeça, dor no couro cabeludo, persistindo por 30 minutos a 7 dias","C":"cefaleia geralmente intensa, excruciante com congestão ocular, obstrução nasal, sudorese da\nfronte e face ipsilateral, durante 15 a 180 minutos","D":"ataques recorrentes de dor lancinante e súbita descrita como um choque doloroso intenso e\nincapacitante. A dor pode ser desencadeada por falar, escovar os dentes, mastigar ou tocar\nlevemente no rosto"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-254213","number":"254213","sourceNumber":"254213","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual característica abaixo condiz com o diagnóstico de arterite temporal?","options":{"A":"Mulher 70 anos.","B":"Vasculite não granulomatosa.","C":"VHS normal e consumo de complemento.","D":"Contraindicação ao uso de AAS."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-248908","number":"248908","sourceNumber":"248908","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Para contactantes domiciliares adultos de pacientes com meningite bacteriana aguda\nde etiologia meningocócica, há, em até 24 horas\ndo diagnóstico do caso-índice, indicação para\nprofilaxia com o uso da seguinte droga:","options":{"A":"pirazinamida","B":"sulfametoxazol-trimetoprima","C":"ciprofloxacino","D":"amoxicilina"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-247413","number":"247413","sourceNumber":"247413","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 25 anos, sexo masculino, procura o pronto-socorro pela quarta vez na\nmesma semana, com história de duas a quatro\ncrises diárias de cefaleia unilateral, sempre à\nesquerda, de intensidade muito forte, com lacrimejamento ipsilateral, congestão nasal e rinorreia.\nRelata episódios prévios no último ano. Para abortar a dor aguda e tratar profilaticamente a melhor\nconduta é, respectivamente:","options":{"A":"oxigênio inalatório e sumatriptano.","B":"sumatriptano e verapamil.","C":"oxigênio inalatório e verapamil.","D":"oxigênio inalatório e ergotamina."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-234336","number":"234336","sourceNumber":"234336","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Alguns sinais e sintomas são considerados alerta para cefaleias secundárias e indicam\na necessidade de investigação por exames (red\nflags) como, por exemplo, episódios recorrentes\nde:","options":{"A":"Cefaleia unilateral, pulsátil, de forte intensidade, com duração de seis horas, com náuseas, foto\ne fonofobia, de início aos 60 anos.","B":"Cefaleia bifrontal, em aperto, de moderada intensidade, com fonofobia e pontos de gatilho à\npalpação cervical, em paciente de 30 anos.","C":"Cefaleia grave, unilateral, orbitária, com hiperemia conjuntival, lacrimejamento e rinorreia\nipsilaterais, por 10 minutos, oito vezes ao dia.","D":"Cefaleia precedida de fosfenos, de forte intensidade, com vômitos, foto e fonofobia, que piora\nquando o paciente caminha."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-229523","number":"229523","sourceNumber":"229523","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Alguns quadros que caracterizam dor abdominal de origem extra abdominal também\nfazem parte do diagnóstico diferencial e devem sempre ser descartados. São exemplos desses\nquadros todos os abaixo, EXCETO:","options":{"A":"Cetoacidose diabética.","B":"Doenças reumáticas.","C":"Enxaqueca.","D":"Pneumonia."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-246570","number":"246570","sourceNumber":"246570","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre cefaleia em Pediatria, julgue os itens que se seguem. I. As enxaquecas (ou\nmigrâneas) são condições recorrentes,\nrelatadas por mais de 10% de crianças/adolescentes até os\n15 anos de idade. II. Dentre as causas de cefaleia secundária em crianças, as mais comuns são as\npós-traumáticas e decorrentes de sinusite. III. As cefaleias do tipo tensional são queixas comuns\nentre os adolescentes e costumam afetar negativamente as atividades diárias mais intensamente\nque os demais tipos de cefaleia. Pode-se afirmar que:","options":{"A":"todos os itens estão certos.","B":"nenhum item está certo.","C":"apenas o item I está certo.","D":"apenas os itens I e III estão certos.","E":"apenas os itens I e II estão certos."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-246571","number":"246571","sourceNumber":"246571","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A respeito dos distúrbios de movimento em pediatria, assinale a alternativa correta.","options":{"A":"A ataxia cerebelar aguda ocorre como resposta autoimune a infecções virais, notadamente\nvaricela, coxsackie ou ecovírus. Predomina entre\nas crianças de 1 a 3 anos e se apresenta\ninicialmente com vômitos, febre e rigidez nucal, na grande maioria das vezes.","B":"Tumores do lobo frontal podem causar ataxia devido à destruição das fibras fronto-cerebelares\nou pelo aumento de pressão intracraniana.","C":"Entre as doenças degenerativas do sistema nervoso central que cursam com ataxia, a\nataxia-telangiectasia é a mais comum, uma condição de prognóstico reservado, de herança\nautossômica dominante.","D":"Dentre as coreias adquiridas na infância, a mais comum é a Coreia de Sydenham, manifesta\nalgumas semanas ou meses após a infecção\nestreptocócica. O pico de incidência se dá entre os 8\ne 9 anos de idade, com predominância de 2:1 no sexo masculino: sexo feminino.","E":"O chamado \"\"tremor essencial\"\" é o mais comum dos tremores entre adultos. Dentre esses,\nmenos de 10% relatam sintomas de tal natureza na infância."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-246575","number":"246575","sourceNumber":"246575","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A meningite eosinofílica é definida como a pleiocitose eosinofílica do líquor (mais de 10\neosinófilos/mm³ de líquor) e a causa mais comum, em todo o mundo, é a infecção do sistema\nnervoso central (SNC) por helmintos. Sobre tal patologia, assinale a alternativa correta.","options":{"A":"Embora qualquer helminto possa causar meningite eosinofílica, a causa mais comum é a\ninvasão do SNC por cisticercos da \"\"tênia do porco\"\".","B":"O tratamento consiste em administrar altas doses de anti-helmínticos, de forma que ultrapassem\na barreira hematencefálica, na tentativa de\nconter a proliferação e o desenvolvimento dos vermes.","C":"O prognóstico é reservado e a doença costuma ser fatal ou deixar sequelas graves na maioria\ndos pacientes, uma vez que o grau de suspeição é\nbaixo para que seja feito diagnóstico precoce.","D":"As manifestações clínicas da doença costumam surgir de 1 a 3 semanas após a exposição aos\nvermes, o que compreende o tempo de migração dos helmintos do trato gastrointestinal ao SNC.","E":"Os esteroides podem ser usados no tratamento da meningite eosinofilica como moduladores da\nresposta inflamatória do SNC, mas não contribuem para controle sintomático na maioria dos casos."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-249556","number":"249556","sourceNumber":"249556","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A meningite basal exsudativa por tuberculose é a apresentação clínica mais comum e é\nmais frequente em crianças abaixo dos seis anos de idade da TB meningoencefálica. Somente não\npodemos aceitar que:","options":{"A":"TB meningoencefálica ? É responsável por 3% dos casos de TB em pacientes não infectados\npelo HIV e por até 10% em PVHIV.","B":"Clinicamente, pode ser subaguda ou crônica (sinais e sintomas com duração superior a quatro\nsemanas).","C":"Na forma subaguda, cursa com cefaleia holocraniana, irritabilidade, alterações de\ncomportamento, sonolência e anorexia não podendo a\nela ser atribuídos vômitos e dor abdominal\nassociados à febre e fotofobia.","D":"Na forma subaguda, cursa com rigidez de nuca por tempo superior a duas semanas."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-218217","number":"218217","sourceNumber":"218217","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Nas meningites bacterianas agudas, o tratamento baseia-se no diagnóstico precoce,\nexame do LCR e uso correto de antibióticos,\nassim sendo, é considerado padrão-ouro para o\ntratamento desta infecção?","options":{"A":"Ampicilina.","B":"Cloranfenicol.","C":"Ceftriaxona.","D":"Rifampicina."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-217013","number":"217013","sourceNumber":"217013","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 46 anos, sexo masculino, praticante de judô, com quadro de cefaleia\nholocraniana súbita intensa; sem vômitos ou\nfebre, admitido com 3 horas de evolução do quadro.\nAo exame, hipertenso e presença de miose e ptose à esquerda, sem rigidez de nuca ou alterações\nvisuais. Tomografia de crânio normal na chegada. Qual é o diagnóstico mais provável?","options":{"A":"Hemorragia subaracnoidea.","B":"Dissecção de carótida.","C":"Coarctação de aorta.","D":"Trombose de seio venoso.","E":"Meningite bacteriana."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-201941","number":"201941","sourceNumber":"201941","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"É recomendado o tratamento com aciclovir na encefalite causada pelo seguinte vírus:","options":{"A":"rubéola","B":"sarampo","C":"caxumba","D":"hepatite B","E":"herpes-simples"},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-210579","number":"210579","sourceNumber":"210579","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Considere: paciente de 53 anos atendida no ambulatório com queixa de cefaleia\nfrontotemporal à esquerda há cerca de um\nmês, sem vômitos, com alívio após uso de AINE, além\nde astenia e rigidez articular. Ela nega morbidades prévias. Acerca da conduta adequada na\ninvestigação da cefaleia, assinale a alternativa correta.","options":{"A":"Exame de imagem e líquor normais excluem causas secundárias.","B":"VHS elevado confirma o diagnóstico de arterite temporal.","C":"A biópsia da artéria temporal é muito sensível para o diagnóstico.","D":"O atraso no tratamento pode acarretar perda visual e isquemia cerebral.","E":"Na confirmação de arterite temporal, recomenda-se corticoide em baixas doses."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-215437","number":"215437","sourceNumber":"215437","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual é o método diagnóstico indicado para a confirmação de encefalite pelo vírus\nherpes simples?","options":{"A":"EEG.","B":"Ressonância nuclear magnética.","C":"PCR.","D":"Pesquisa de anticorpo contra VHS1 e VHS2 no liquor."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-215449","number":"215449","sourceNumber":"215449","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Assinale a alternativa que apresenta a conduta CORRETA frente a um paciente com\nquadro sugestivo de encefalite herpética.","options":{"A":"Deve-se suspender a terapêutica antiviral específica.","B":"A possibilidade de um agente bacteriano não pode ser imediatamente descartada.","C":"O exame liquórico sempre apresenta alterações quimiocitológicas significativas.","D":"A escolha do antibiótico deve ser baseada na epidemiologia local, independentemente de dados\nda história, como viagens recentes, por\nexemplo."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-215444","number":"215444","sourceNumber":"215444","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Considerando o diagnóstico de meningoencefalites, assinale a alternativa INCORRETA.","options":{"A":"O acompanhamento da criança com meningoencefalite inclui a avaliação auditiva e do\nneurodesenvolvimento.","B":"Recomenda-se o uso de aciclovir em pacientes acometidos por meningoencefalite herpética.","C":"Recomenda-se o uso de ganciclovir nos casos de meningoencefalite por citomegalovírus.","D":"A administração de aciclovir deve ser de 20mg/Kg a cada 8 horas, por 30 dias, para pacientes\nmaiores de 12 anos."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-214985","number":"214985","sourceNumber":"214985","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A etiologia da meningite bacteriana aguda dependerá da idade, do estado imunológico\ne da epidemiologia. Os principais agentes na\nfaixa etária >3 meses são:","options":{"A":"bastonetes Gram negativos","B":"N. meningitidis","C":"Enterococcus sp","D":"L. monocytogenes"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-217047","number":"217047","sourceNumber":"217047","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"As infecções do Sistema Nervoso Central (SNC) apresentam manifestações clínicas\nsemelhantes, inicialmente inespecíficas, independentemente da etiologia. Acerca dessas infecções,\njulgue os itens a seguir. I. As infecções virais do SNC são mais comuns, seguidas pelas infecções\nbacterianas, fúngicas e, por último, parasitárias. II. Nos neonatos, as meningites bacterianas são\nnormalmente causadas por micro-organismos dos traços gastrintestinal ou geniturinário maternos,\ncomo os estreptococos do grupo B e Escherichia coli. III. Em crianças com mais de 28 dias de vida,\npatógenos como N. meningitidis, S. pneumoniae e H. influenzae tipo B já se tornam, nessa ordem,\na principal causa de meningite bacteriana. Pode-se afirmar que:","options":{"A":"Todos os itens estão certos.","B":"Todos os itens estão errados.","C":"Apenas o item I está certo.","D":"Apenas os itens I e III estão certos.","E":"Apenas os itens I e II estão certos."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-201659","number":"201659","sourceNumber":"201659","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"As meningites bacterianas são caracterizadas por um processo inflamatório das\nmeninges, membranas que envolvem o cérebro e a medula espinhal, causadas por uma grande\nvariedade de bactérias. O tratamento precoce e adequado dos casos reduz significativamente a\nletalidade da doença, sendo importante para o prognóstico satisfatório. Quanto às meningites\nbacterianas, deve-se considerar o seguinte:","options":{"A":"A Neisseria meningitidis, conhecida como meningococo, pode ser precocemente identificada na\nbacterioscopia ao Gram do líquido cefalorraquidiano como diplococos Gram-positivos.","B":"O tratamento preconizado para lactentes até dois meses é a monoterapia com ampicilina\n100-300 mg/kg/dia, dividida em duas a quatro vezes, por sete dias.","C":"A incidência de Streptococcus pneumoniae não suscetíveis à penicilina em amostras de\nmeningites atinge mais de 30% em nosso meio. O tratamento preconizado em adultos é a\nceftriaxona.","D":"O esquema empírico preferencial, em crianças maiores de dois meses, é a associação de\nampicilina e cloranfenicol."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-201673","number":"201673","sourceNumber":"201673","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Leia o caso clínico a seguir. Uma menina de cinco meses, com quadro de febre há 23\nhoras, acompanhada de vômitos (quatro episódios) e chorando muito; sem outros sintomas.\n\nAntecedentes: a mãe refere que a criança manifestou vários quadros gripais e tem alergia a\ndipirona. Não trouxe o cartão de vacinação. A\nmãe informa ainda que algumas vacinas estão\natrasadas porque a criança teve febre alta após vacinar-se, então o pai foi contra as vacinas. O\nexame físico é bastante dificultado pelo choro persistente. Foram observadas desidratação leve e\ntemperatura axilar de 39,6°C. Ao final da consulta, a criança apresentou convulsão que cessou\nrapidamente, antes que houvesse tempo para aplicar o anticonvulsivante. A conduta imediata será:","options":{"A":"Abaixar a febre, preferencialmente com dipirona via endovenosa, realizar hemograma, EAS,\nurocultura e deixar em observação.","B":"Prescrever paracetamol, hidratação venosa e realizar punção lombrar.","C":"Prescrever antitérmico, anticonvulsivante e soro de manutenção; deixar em observação, mínimo\nde 24 horas. Solicitar o cartão de\nvacinação.","D":"Realizar hemograma, EAS, urocultura, hemocultura e radiografia de tórax. Após normalização da\ntemperatura, prescrever soro oral e manter em observação até os resultados dos exames."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-187697","number":"187697","sourceNumber":"187697","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Nas meningites bacterianas agudas mais prevalentes em nosso meio a droga padrão\nouro para o tratamento é:","options":{"A":"Cefalosporina de primeira geração.","B":"Penicilinas.","C":"Cloranfenicol.","D":"Ceftriaxone."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-178771","number":"178771","sourceNumber":"178771","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, 66 anos, hipertensa em tratamento regular com losartana,\nsem outras comorbidades. Informa que há 3\nsemanas iniciou quadro de lombalgia, após esforço,\nsem irradiação para membros inferiores. Informa ainda que as dores estão se agravando,\nprincipalmente à noite, e que \"subiram\" até os ombros. Informa perda funcional dos ombros e\nquadril e, há 1 semana, tem apresentado rigidez matinal do quadril com duração de 1 hora. Não\napresenta qualquer outro sintoma sistêmico. Solicitados exames laboratoriais e de imagem com os\nseguintes resultados: Tomografia computadorizada de coluna lombar - discopatia degenerativa sem\ncompressão radicular; Tomografia computadorizada dos ombros - osteoartrose; Laboratorais -\nanemia (HB: 10,1) normocítica normocrômica, VHS aumentado (106 mm/h), PCR aumentada, FAN\nnegativo, fator reumatoide negativo, sorologias virais negativas. Qual o diagnóstico mais provável\npara essa paciente?","options":{"A":"Doença neoplásica.","B":"Arterite de células gigantes.","C":"Artrite reumatoide.","D":"Polimialgia reumática.","E":"Fibromialgia."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-186445","number":"186445","sourceNumber":"186445","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação à arterite de células gigantes. marque a alternativa FALSA:","options":{"A":"Um achado característico é o aumento importante do VHS.","B":"É mais comum em homens, entre 20 e 40 anos.","C":"É comum o aumento da fosfatase alcalina.","D":"É comum o achado de cefaleia e claudicação da mandíbula."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-174441","number":"174441","sourceNumber":"174441","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Segundo o ISDA, deve-se colher o líquor, na suspeita de meningite, antes de realizar\nexame de imagem:","options":{"A":"quando há doença prévia do sistema nervoso central","B":"quando há déficit neurológico focal","C":"quando o Glasgow do paciente é 14","D":"quando há imunossupressão"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-174462","number":"174462","sourceNumber":"174462","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação ao líquor na Meningite, é correto afirmar que a","options":{"A":"bacteriana clássica tem aumento de leucócitos com predomínio de neutrófilos, redução de\nglicose e proteínas normais.","B":"tuberculosa tem aumento de leucócitos com predomínio de linfócitos, redução da glicose e\naumento das proteínas.","C":"viral tem aumento de leucócitos com predomínio de linfócitos, redução intensa da glicose e\nproteínas normais a reduzidas.","D":"tuberculosa tem aumento de leucócitos com predomínio de neutrófilos, redução da glicose e\naumento das proteínas."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-174474","number":"174474","sourceNumber":"174474","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A Meningite deve ser tratada de maneira diferente em cada faixa etária e em cada\nclínica apresentada pelo paciente, pois existem\nagentes etiológicos mais frequentes e distintos para\ncada situação. Quanto ao tratamento da meningite, é correto afirmar que em","options":{"A":"recém-nascidos é feito apenas com cefotaxima.","B":"crianças de 3 meses a 5 anos é feito com ceftriaxone + oxacilina.","C":"crianças de 1 mês de vida a crianças menores de 3 meses é feito com ceftriaxone + ampicilina.","D":"pacientes com HIV é feito com cloranfenicol + ceftriaxone."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-174467","number":"174467","sourceNumber":"174467","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre a Encefalite, assinale a alternativa correta:","options":{"A":"O líquor normal exclui o diagnóstico de encefalite.","B":"Deve-se sempre interromper o aciclovir em crianças com coleta de líquor feita em menos de 6\nhoras do início dos sintomas e que tenha PCR para herpes negativo.","C":"Em casos com PCR no líquor para herpes negativo e que haja suspeita clínica para encefalite\nherpética, deve-se recoletar novo líquor em 48 horas sem suspensão do aciclovir.","D":"O tratamento para encefalite por sarampo é feito com ganciclovir."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-178792","number":"178792","sourceNumber":"178792","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma criança de 24 meses, que apresenta há 30 dias quadro de vômitos ao acordar\npela manhã, acorda à noite reclamando que a\ncabeça está doendo. Parou de deambular e há 3\ndias está sonolenta. Qual é o método diagnóstico mais adequado para definição etiológica?","options":{"A":"Punção lombar.","B":"Endoscopia digestiva alta.","C":"Phmetria.","D":"Tomografia de crânio.","E":"Polissonografia."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-182438","number":"182438","sourceNumber":"182438","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A etiologia da meningite bacteriana aguda dependerá da idade, do estado imunológico\ne da epidemiologia. Os principais agentes na\nfaixa etária >3 meses são:","options":{"A":"bastonetes Gram negativos","B":"N. meningitidis","C":"Enterococcus sp","D":"L. monocytogenes"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-182514","number":"182514","sourceNumber":"182514","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Duas crianças estão internadas, num hospital, com meningite: a criança A com\nmeningite meningocócica, e a criança B, com meningite pneumocócica. Qual é a conduta de\nimediato com relação aos contactantes íntimos das crianças?","options":{"A":"rifampicina para contactantes dos 2 casos","B":"rifampicina para contactantes do caso A apenas","C":"rifampicina para contactantes do caso B apenas","D":"vacina meningocócica C conjugada para crianças do caso A apenas"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-157314","number":"157314","sourceNumber":"157314","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"O tratamento para enxaqueca é dividido em duas vertentes, profilático e abortivo (crise).\nQual é a droga de escolha para o\ntratamento profilático de enxaqueca?","options":{"A":"Sumatriptano.","B":"Propranolol.","C":"Topiramato.","D":"Ibuprofeno.","E":"Valproato de sódio."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-157005","number":"157005","sourceNumber":"157005","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 55 anos, com cefaleia hemicraniana esquerda, de moderada intensidade\nassociada a desconforto à mastigação,\napresenta dor muscular na cintura pélvica e escapular. Qual\no tratamento mais indicado?","options":{"A":"Prednisona.","B":"Ibuprofeno.","C":"Amitriptilina.","D":"Sumatriptano."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-156463","number":"156463","sourceNumber":"156463","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre a CEFALÉIA podemos afirmar que:","options":{"A":"Tem baixa prevalência na prática diária","B":"Na cefaléia secundária o sintoma em si é a doença como por exemplo a enxaqueca.","C":"O bloqueio anestésico não é empregado","D":"As cefaléias primárias não tem comprovação laboratorial ou por exames de imagem"},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-158490","number":"158490","sourceNumber":"158490","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Lactente de 15 meses, masculino, apresenta febre alta, irritabilidade e recusa alimentar\nhá 3 dias. Hoje surgiram petéquias no corpo.\nAo exame: sinais de irritação meníngea. O exame do\nLCR mostrou-se compatível com meningite. A bacterioscopia revelou coco bacilo Gram-negativo. A\ncriança havia recebido uma dose da vacina tetravalente aos 6 meses. Considerando a presença de\num irmão de 4 anos com história de vacinação incompleta e o período de transmissibilidade da\ninfecção, a conduta indicada para a proteção dos contactantes domiciliares é:","options":{"A":"Quimioprofilaxia com rifampicina para todos durante 4 dias.","B":"Vacinação com tetravalente apenas para a criança de 4 anos.","C":"Observação rigorosa de todos os contactantes, sem quimioprofilaxia.","D":"Quimioprofilaxia com rifampicina apenas para a criança de 4 anos."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-150204","number":"150204","sourceNumber":"150204","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A encefalopatia espongiforme humana transmissível (EET), ou doença por prion,\napresenta sintomas neurológicos e psiquiátricos\ne uma evolução fatal progressiva. Essa doença\ntem a seguinte característica:","options":{"A":"A doença de Creutzfeldt-Jakob esporádica é responsável, epidemiologicamente, por mais de\n99% de todos os casos em humanos, enquanto\nas formas familiar e iatrogênica são praticamente\ninexistentes.","B":"A existência de portadores saudáveis do gene E200K é impossível, já que toda pessoa que\npossui este gene manifestará, em alguma época da vida, a doença.","C":"O electroencefalograma mostra, desde o início do curso da doença, atividade periódica - os\ncomplexos de ondas agudas, que persistem até a fase terminal da doença.","D":"Os cérebros dos pacientes, embora pareçam grosseiramente normais, no exame pós-morte,\nmostram degeneração espongiforme e glicose\nastrocitária."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-157329","number":"157329","sourceNumber":"157329","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"No caso de um paciente de 5 anos com diagnóstico de meningite bacteriana aguda,\ncujo agente etiológico visualizado pelo método\nde Gram foi um diplococo Gram-negativo, qual a\nquimioprofilaxia indicada para os contatos íntimos acima de 10 anos?","options":{"A":"Rifampicina 600 mg via oral, 1 vez ao dia durante 4 dias.","B":"Ciprofloxacino 500 mg via oral, de 12 em 12 horas durante 2 dias.","C":"Rifampicina 600 mg via oral, de 12 em 12 horas durante 2 dias.","D":"Ciprofloxacino 500 mg via oral, 1 vez ao dia durante 4 dias.","E":"Rifampicina 600 mg via oral, de 12 em 12 horas durante 2 dias, e Ciprofloxacino 500 mg via oral,\n1 vez ao dia durante 4 dias."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-156991","number":"156991","sourceNumber":"156991","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma menina de 4 anos iniciou febre alta e vômito há 3 dias realizou punção lombar\ndevido à suspensão de meningite bacteriana.\nO exame do liquor revelou 1.500 células (80%\npolimorfonucleares/20% mononucleares), proteína = 500, glicose = 10 mg/dl e bacterioscopia com\ndiplococo Gram positivo. Com baseado no caso, assinale a assertiva CORRETA quanto à etiologia\ne à indicação de profilaxia secundária para os contactantes.","options":{"A":"Streptococcus pneumoniae e não realizar profilaxia.","B":"Neisseria meningitidis e realizar profilaxia com rifampicina.","C":"Staphylococcus aureus e não realizar profilaxia.","D":"Haemophilus influenzae e realizar profilaxia com rifampicina."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-156409","number":"156409","sourceNumber":"156409","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Nas intervenções agudas medicamentosas na enxaqueca infantil a medicação com\nnível A de evidência é?","options":{"A":"Di-hidroergotamina nasal.","B":"Clonidina.","C":"Propranolol.","D":"Sumatriptan nasal."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-157022","number":"157022","sourceNumber":"157022","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um estudante de 16 anos dá entrada em serviço de pronto atendimento, acompanhado\nda namorada, com quadro clínico sugestivo de\nmeningite. Não foi realizado nenhum procedimento\ninvasivo no pronto atendimento. Trinta minutos após a entrada, o paciente foi transferido para um\nhospital de referência, onde foram coletados materiais biológicos para exames laboratoriais,\nincluindo liquor. Foi iniciado tratamento com ceftriaxona. O exame de liquor foi compatível com\nmeningite bacteriana, e a reação de látex no soro foi positiva para Neisseria meningitidis. Sobre a\nquimioprofilaxia da infecção pela N. meningitidis, assinale a alternativa correta","options":{"A":"Deverá ser iniciada nos contatos somente após a cultura do liquor comprovar o crescimento da\n\nN. meningitidis.","B":"Deverá ser realizada nos familiares que residem com o paciente, na namorada e nos colegas de\nturma que mantinham contato próximo, e na equipe do pronto atendimento.","C":"O medicamento indicativo pelo Ministério da Saúde para a quimioprofilaxia dos contatos de\ncasos confirmados ou suspeitos é a rifampicina.","D":"Também está indicada para o próprio paciente para erradicação da bactéria de sua orofaringe,\nevitando assim o estado de portador."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-157389","number":"157389","sourceNumber":"157389","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação ao corticoide na meningite meningocócica, assinale a alternativa\nCORRETA:","options":{"A":"Mostra redução da mortalidade.","B":"Deve ser administrado ao mesmo tempo que o antibiótico.","C":"Aumenta os paraefeitos.","D":"Reduz a chance de surdez."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-127363","number":"127363","sourceNumber":"127363","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Durante exacerbações de Bronquite Crônica, os pacientes ficam sujeitos a longas\ninternações e, eventualmente, complicações do tratamento. Qual das interações abaixo listadas\ncausa lesão de placa neural?","options":{"A":"Corticoide com aminoglicosídeos.","B":"Aminoglicosídeos com cefalosporinas.","C":"Diuréticos de alça com aminoglicosídeos.","D":"Beta-agonistas com corticoides."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-129826","number":"129826","sourceNumber":"129826","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na doença de Parkinson, manifestações clínicas não relacionadas ao sistema motor\nsão comuns. Uma dessas manifestações é:","options":{"A":"Alucinação olfativa.","B":"Fibromialgia.","C":"Apneia do sono.","D":"Hipertensão arterial pulmonar."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-127670","number":"127670","sourceNumber":"127670","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo masculino, de 31 anos, procura o ambulatório queixando-se de\ncefaleia de moderada intensidade,\nfrontotemporal bilateral, que não o atrapalha nas suas atividades\nhabituais, nem piora com esforços. A dor vem ocorrendo quase diariamente, no final da tarde, há\nquatro meses, e só melhora quando ele chega em casa, toma um banho e descansa. Não tem\nusado analgésicos há cerca de dois meses, pois achou que eles estavam piorando as crises.\n\nRelata que já teve dor semelhante há muitos anos, mas era muito rara. Diz que tem a sensação de\nque sua cabeça está sendo ?espremida?.\nConta que o barulho tem incomodado bastante durante o\nperíodo de dor. Nega alterações gastrointestinais ou neurológicas associadas. Seus exames geral\ne neurológico foram normais e não havia dor à palpação craniana. Com base nos dados relatados e\nnos critérios internacionais de classificação das cefaleias, o diagnóstico de cefaleia tipo tensão\ne o\ntratamento medicamentoso são, respectivamente:","options":{"A":"Cefaleia tipo tensão provável e derivados do ergot.","B":"Cefaleia tipo tensão episódica pouco frequente e triptanos.","C":"Cefaleia tipo tensão episódica frequente e sertralina.","D":"Cefaleia tipo tensão crônica e amitriptilina."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-129839","number":"129839","sourceNumber":"129839","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A tríade de Cushing, geralmente associada a quadros de descompensação da\nhipertensão intracraniana, caracteriza-se por:","options":{"A":"Anisocoria, náuseas e vômitos.","B":"Papiledema, cefaleia e vômito.","C":"Hipotensão postural, cefaleia e taquicardia.","D":"Bradicardia, hipertensão arterial e alteração do ritmo respiratório."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-129853","number":"129853","sourceNumber":"129853","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na doença de Parkinson, qual é a principal deficiência neuroquímica e em que via\nanatômica ela se encontra?","options":{"A":"Dopamina ? via mesolímbica.","B":"Carbidopa ? via nigroestriatal.","C":"Levodopa ? via nigrolenticular.","D":"Dopamina ? via nigroestriatal."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-136627","number":"136627","sourceNumber":"136627","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente com quadro de perda motora do lado direito do corpo, com dificuldade de fala\ne desvio de rima labial. Início do quadro há duas horas. Seu exame físico demonstra estar\nhipocorado e com sangue nas roupas íntimas. Solicitado tomografia de crânio que estava normal.\nQual dos fatores abaixo NÃO apresenta relevância para decidir o valor pressórico tolerado nesse\ncaso, de vez que sua PA era de 190x120 mm Hg?","options":{"A":"Início do quadro clínico.","B":"Presença de sangramento ativo.","C":"Dificuldade de fala.","D":"Tomografia sem sangramentos."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-136634","number":"136634","sourceNumber":"136634","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente previamente hipertenso procura hospital ajudado por familiares, com histórico\nde perda motora ocorrida há duas horas,\nperdendo movimentos no lado esquerdo do corpo. Em\nrelação a esse caso, NÃO podemos considerar adequado:","options":{"A":"Tolerar hipertensão até 180x110 mmHg de imediato.","B":"Realizar tomografia a fim de excluir sangramento.","C":"Avaliar hipertensão após tomografia e decisão de oferecer trombólise.","D":"Oferecer possibilidade de trombólise, caso possível."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-137044","number":"137044","sourceNumber":"137044","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 72 anos de idade apresentando incontinência urinária, alteração de marcha\ne déficit cognitivo. Nesse caso, o paciente\ndeverá ser investigado quanto a:","options":{"A":"Demência de corpúsculos de Lewi.","B":"Hidrocefalia com pressão normal.","C":"Demência de Pick.","D":"Atrofia de múltiplos sistemas."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-127348","number":"127348","sourceNumber":"127348","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente deu entrada no hospital com disartria, dislalia e perda motora do lado direito\ndo corpo. Sua pressão sistólica está em 200 mm\nHg e sua diastólica em 130 mm Hg. Podemos,\nentão, afirmar que:","options":{"A":"Caso não ocorram co-morbidades, podemos tolerar esses níveis tensionais.","B":"Nesse nível de PA, não podemos indicar trombólise.","C":"Somente será proposto redução pressórica, caso ocorra patologia associada.","D":"Tolerar esse aumento da pressão por 72, beneficia a evolução da área de penumbra."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-136636","number":"136636","sourceNumber":"136636","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente masculino, 62 anos de idade, iniciou subitamente, nesta manhã, quadro de\nperda motora em lado direito do corpo. Faz 2\nhoras que iniciou o quadro neurológico. Ao ser\nrealizado sua tomografia, não são constatadas lesões visíveis. Apresenta histórico de hipertensão\nem uso de propranolol irregular. Exame físico demonstra PA 190 x 120 mmHg e perda motora em\nlado direito. Das alternativas apresentadas, qual delas NÃO irá influenciar na decisão do valor\ntolerado de PA?","options":{"A":"Complicações relacionadas à hipertensão.","B":"Tempo de início dos sintomas.","C":"Quadro neurológico.","D":"Histórico prévio de hipertensão."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-127318","number":"127318","sourceNumber":"127318","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual das alternativas contém os achados clínicos sugestivos de liberação piramidal?","options":{"A":"Distonia e hiporreflexia.","B":"Clônus e hiper-reflexia.","C":"Fasciculações e lesão do VI par craniano.","D":"Reflexo cutâneo-plantar em flexão e distonia."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-111362","number":"111362","sourceNumber":"111362","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Critério de exclusão para Terapia Trombolítica em pacientes com Acidente Vascular\nCerebral:","options":{"A":"Gravidez.","B":"Plaquetas abaixo de 100.000/mm3.","C":"Crise convulsiva durante a instalação do AVC.","D":"IAM recente.","E":"Todas as alternativas são critérios de exclusão."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-103739","number":"103739","sourceNumber":"103739","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente masculino de 65 anos de idade, previamente hipertenso e diabético, dá\nentrada no setor de emergência com queixa de\ndisartria e dificuldade de movimentação de membro\nsuperior direito de início há 8 horas. Marque a CORRETA.","options":{"A":"Paciente, se indicado, pode se beneficiar de trombólise nesse momento.","B":"Como, clinicamente, o comportamento é o de AVC Isquêmico, podemos abordar o paciente\nassim.","C":"Níveis pressóricos elevados devem ser tolerados, se possível, nos primeiros dias de evolução do\nquadro.","D":"Podemos imediatamente utilizar AAS para tratamento."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-101156","number":"101156","sourceNumber":"101156","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na fase inicial da doença de Parkinson:","options":{"A":"Os anticolinérgicos têm efeito neuroprotetor, devendo ser usados precocemente.","B":"A terapia dopaminérgica deve ser feita com o uso de levodopaterapia em doses elevadas.","C":"O uso de amantadina leva a edema periférico em membros inferiores e maior propensão a\nalucinações.","D":"A selegilina é fundamental na melhora dos sintomas."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-109383","number":"109383","sourceNumber":"109383","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"É um achado relevante para o diagnóstico da doença de Alzheimer:","options":{"A":"alteração progressiva do comportamento, com ausência de outras manifestações.","B":"afasia progressiva, sem outras manifestações cognitivas.","C":"alteração de dois ou mais domínios cognitivos de forma progressiva.","D":"afasia progressiva inicial associada a um domínio cognitivo."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-103652","number":"103652","sourceNumber":"103652","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente previamente hipertenso e diabético evolui com confusão mental, disartria,\nalém de perda motora em todo o dimídio\nesquerdo. Não é realizado protocolo de trombólise pelo\nfato de o caso ter vindo transferido de outro hospital menor, já com 12 horas de evolução.\n\nRealizado tomografia de crânio não são encontradas lesões. Boa ventilação, porém, a pressão\narterial se encontra elevada com valores de\n170 x 100 mmHg. Assim, NÃO podemos tomar qual\ndas atitudes abaixo a fim de preservar área de penumbra?","options":{"A":"Normalizar pressão arterial.","B":"Tolerar níveis pressóricos mais elevados.","C":"Caso ocorra complicação da crise hipertensiva, devemos reduzir a pressão.","D":"Tolerar níveis pressóricos até acima de 180 x 110."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-103657","number":"103657","sourceNumber":"103657","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente hipertenso crônico, com elevação dos valores de ureia e creatinina fora\ndiabetes mal controlado, evolui com\nrebaixamento do nível de consciência e dificuldade respiratória.\nSua pressão arterial está extremamente elevada com PA 230 x 130 mmHg. Seus exames\ndemonstram glicemia de 120, valores de ureia e creatinina ainda não indicam\nhemodiálise.Tomografia demonstra intenso edema cerebral. Qual das alternativas abaixo MELHOR\nexplica o caso?","options":{"A":"Provável distúrbio metabólico, com acidose lática.","B":"Vasodilatação por pressão, hiperemia cerebral e encefalopatia.","C":"Hemorragia cerebral.","D":"Provável AVC isquêmico."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-110205","number":"110205","sourceNumber":"110205","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em um plantão no SAMU ocorre uma chamada para atender uma mulher de 67 anos\ncom quadro súbito de perda de força em\ndimídio esquerdo há 1 hora. Antecedentes de hipertensão\narterial, diabetes mellitus, e um episódio de AIT há 4 meses. Ao exame físico, apresenta ausculta\ncardíaca e pulmonar normais e hemiparesia à esquerda de predomínio braquiocefálico. A pressão\narterial é 166/92 mmHg, frequência cardíaca = 102 bpm, SaO2 = 96%. Até o transporte para\nhospital de referência, o manejo da pressão arterial deve ser:","options":{"A":"Captopril 25mg sublingual.","B":"Nitroprussiato endovenoso em bomba de infusão contínua.","C":"Atenolol 25mg por via oral.","D":"Apenas observação clínica."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-101209","number":"101209","sourceNumber":"101209","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente admitido com síndrome de hipertensão craniana e quadro febril agudo.\nSubmetido à coleta de liquor e iniciada terapia com ceftriaxona. O exame de liquor demonstrou\nmeningite meningocócica. Neste caso, recomenda-se a seguinte conduta:","options":{"A":"Precauções com gotículas durante o curso do tratamento antimicrobiano.","B":"Quimioprofilaxia dos contatos íntimos e do paciente, mesmo após ter recebido a terapia\nantimicrobiana específica.","C":"Vacinação de bloqueio, caso se constate um surto da doença.","D":"Manutenção da antibioticoterapia por, no mínimo, 14 dias."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-110251","number":"110251","sourceNumber":"110251","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 82 anos, portadora de doença de Alzheimer diagnosticada há 6 anos, em\nestágio avançado, é trazida pelos familiares ao pronto atendimento devido a apatia, inapetência e\nsonolência excessiva há quatro dias. Não há febre. Está em uso regular de suas medicações,\nadministradas pela cuidadora, sem mudanças recentes. O exame fisíco é semelhante aos registros\nprévios. Nesse caso, a conduta mais adequada é:","options":{"A":"internação hospitalar para investigação do quadro.","B":"tranquilizar os familiares informando que esta é a evolução natural da doença.","C":"introduzir risperidona em baixas doses.","D":"introduzir inibidor da receptação da serotonina."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-110223","number":"110223","sourceNumber":"110223","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, 56 anos, compareceu ao ambulatório com queixa de crises\nvertiginosas, hipoacusia e zumbido unilateral flutuante. As crises apareciam de 6 em 6 meses,\nporém agora com frequência maior. A paciente relata que as crises pioram após ingerir grande\nquantidade de sal (por exemplo, churrasco). Diante desse caso clínico, qual o diagnóstico e a\nmelhor conduta?","options":{"A":"Labirintite - tratamento clínico com flunarizina.","B":"Vertigem posicional paroxística benigna - reabilitação vestibular e beta-histina.","C":"Ménière - tratamento clínico com beta-histina.","D":"infecção de Vias aéreas superiores - prescrição de antigripal."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-110260","number":"110260","sourceNumber":"110260","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Estenose do canal lombar é um estreitamento do canal espinhal e/ou dos forames\nintervertebrais. Nesta condição, a relação\ncontinente/conteúdo torna-se pequena e,\nconsequentemente, os elementos intrarraquianos acham-se apertados produzindo sintomas de\nirritação ou déficits medulares. A radiculopatia é causada pela estenose do recesso lateral ou do\nforame, enquanto que a claudicação neurogênica é o resultado do estreitamento do canal vertebral.\nA síndrome do recesso lateral é provocada, na maioria dos casos, devido a:","options":{"A":"Espondilolistese.","B":"Protusão discal posterolateral.","C":"Hipertrofia facetária.","D":"Hipertrofia do ligamento amarelo."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-110264","number":"110264","sourceNumber":"110264","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Estenose do canal lombar é um estreitamento do canal espinhal e/ou dos forames\nintervertebrais. Nesta condição, a relação\ncontinente/conteúdo torna-se pequena e,\nconsequentemente, os elementos intrarraquianos acham-se apertados produzindo sintomas de\nirritação ou déficits medulares. A radiculopatia é causada pela estenose do recesso lateral ou do\nforame, enquanto que a claudicação neurogênica é o resultado do estreitamento do canal vertebral.\nA estenose do canal lombar ocorre com maior frequência no nível:","options":{"A":"L4-L5","B":"L3-L4","C":"L5-S1","D":"L2-L3"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-83808","number":"83808","sourceNumber":"83808","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Faz parte da síndrome de neurônio motor superior:","options":{"A":"presença dos reflexos profundos.","B":"espasticidade que consiste em um distúrbio motor e sensitivo caracterizado pelo aumento do\ntônus muscular, dependente da velocidade e associado à exacerbação do reflexo miotático.","C":"espasticidade, que consiste em um distúrbio motor caracterizado pelo aumento do tônus\nmuscular, dependente da velocidade e associado à exacerbação do reflexo miotático.","D":"hipertrofia muscular associado a aumento do tônus muscular.","E":"NDA."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-86337","number":"86337","sourceNumber":"86337","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Quadro neurológico de apresentação súbita, com cefaleia e diplopia por lesão do 3º\npar craniano e hemiplegia contralateral é\nrepresentativo de comprometimento do Sistema Nervoso\nao nível de:","options":{"A":"Lesão na cápsula interna.","B":"Lesão no mesencéfalo.","C":"Lesão no tálamo.","D":"Lesão na ponte."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-89973","number":"89973","sourceNumber":"89973","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Critérios de inclusão para Terapia Trombolítica em pacientes com Acidente Vascular\nCerebral, exceto:","options":{"A":"AVCI em qualquer território vascular cerebral.","B":"Idade superior a 18 anos.","C":"Possibilidade de se estabelecer com precisão o momento do início dos sintomas.","D":"Possibilidade de se iniciar a infusão do rt-PA em, no máximo, 2 horas do início dos sintomas.","E":"TC de crânio sem evidência de hemorragia."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-89986","number":"89986","sourceNumber":"89986","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"É indicação de terapia com anticoagulantes, exceto:","options":{"A":"Isquemia cerebral por cardiopatia emboligênica com alto risco de reembolização.","B":"Estados de hipercoagulabilidade.","C":"Dissecção arterial sintomática de artérias pré-cerebrais.","D":"Evento de acidente isquêmico transitório.","E":"Trombose venosa cerebral."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-84634","number":"84634","sourceNumber":"84634","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"De acordo com a propedêutica neurológica, a disfunção da linguagem é localizada:","options":{"A":"Hemisfério Esquerdo frontal/temporal.","B":"Hemisfério Direito parietal/occipital.","C":"Bi-Hemisférico hipocampo/fórnix.","D":"Ponte/Medula.","E":"Hemisfério Cerebelar Ipsolateral."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-78100","number":"78100","sourceNumber":"78100","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"O diagnóstico de Alzheimer","options":{"A":"é exclusivamente clínico; dispensa-se a investigação diagnóstica complementar.","B":"fundamenta-se no exame de neuroimagem para determinar a síndrome neuropsicológica\n(cognitiva) dominante.","C":"é confirmado pela biópsia cerebral, que é um procedimento de rotina.","D":"é um diagnóstico clínico de exclusão, sendo necessário o afastamento de causas de demência\nsecundária."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-84371","number":"84371","sourceNumber":"84371","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A deficiência da vitamina E ocasiona:","options":{"A":"Pelagra.","B":"Ataxia cerebelar.","C":"Hipogeusia.","D":"Intolerância à lactose.","E":"Glossite."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-85350","number":"85350","sourceNumber":"85350","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo masculino, com 40 anos, previamente hígido, sem história de\ndoenças pregressas, dá entrada no pronto-socorro\ncom quadro súbito de perda de força e\nsensibilidade no hemicorpo D, dificuldade de falar (disartria), e tontura. Início há seis horas.\nSolicitada TC (Tomografia Computadorizada), que não mostrou alterações. Hemograma: normal;\nTP, KTTP, glicemia, sódio, potássio, creatinina: normais. Feita avaliação dos critérios de exclusão\npara trombólise: sem contraindicação à trombólise. O que fazer?","options":{"A":"Pelo Manual de Rotinas para Atenção ao AVC, é possível trombólise em paciente jovem com\nmais de seis horas do início dos sintomas.","B":"TC sem alterações descartada AVE de qualquer espécie.","C":"Deve-se realizar tratamento de suporte, sem trombólise e, em seguida à estabilização do\nquadro, iniciar investigação das causas do AVE como vasculites e trombofilias.","D":"Em pacientes jovens com AVE, aterosclerose está descartado como fator etiológico."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-85375","number":"85375","sourceNumber":"85375","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A demência do idoso é um quadro que vem aumentando progressivamente. A\nprevalência varia de 1,6% na faixa de 65 a 69\nanos, até 38,9% em pacientes com idade acima de\n84 anos. Existem vários tipos de demência e, para o seu diagnóstico, um elevado índice de\nsuspeita é necessário. \"Segundo os Projetos e Diretrizes - Demência do Idoso: Diagnóstico na\nAtenção Primária à Saúde\", qual alternativa é CORRETA a respeito dos métodos de rastreamento\ndo déficit cognitivo ou demência?","options":{"A":"De acordo com o CCD (Centro Canadense de Demência), em atenção primária à saúde, exames\ncomo a tomografia, devem ser solicitados\nrotineiramente na pesquisa das demências.","B":"O Miniexame do Estado Mental (MEEM) é adequado para a detecção de demência e sua\nacurácia depende da idade e do nível educacional do paciente.","C":"Para os indivíduos com suspeita de síndrome demencial, a combinação de uma escala funcional\nque avalia atividades da vida diária e um teste\ncognitivo não aumenta a acurácia para o diagnóstico\ndessa doença em uma população como a nossa, ou seja, heterogênea do ponto de vista social e\ncultural.","D":"No Brasil, não se justifica avaliação laboratorial mais ampla de causas potencialmente\nreversíveis de demência."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-84447","number":"84447","sourceNumber":"84447","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A hidrocefalia de pressão normal, associada à síndrome demencial, se manifesta em\nqual faixa etária e com quais sintomas:","options":{"A":"Crianças, com macrocrânia progressiva.","B":"Idosos, com ataxia de marcha, incontinência urinária e síndrome demencial.","C":"Crianças, com ataxia de marcha, incontinência urinária e síndrome demencial.","D":"Idosos, com hipertensão intracraniana.","E":"Idosos, com síndrome de Cushing."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-84398","number":"84398","sourceNumber":"84398","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A tríade de Cushing, que denota hipertensão intracraniana, é caracterizada por:","options":{"A":"Hipotensão arterial, bradicardia, respiração de Cheyne-Stokes.","B":"Extrassístoles, hipertensão arterial, hipoventilação.","C":"Hipertensão arterial, bradicardia, irregularidade respiratória.","D":"Taquicardia, hipertensão arterial, hipoventilação.","E":"Taquicardia, hipertensão arterial, irregularidade respiratória."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-78160","number":"78160","sourceNumber":"78160","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma mulher de 65 anos, após crise convulsiva tônico-clônica, é atendida em uma\nunidade de emergência. O médico a examina,\ndiscute o caso com o colega neurologista e decide\nsolicitar uma tomografia computadorizada do crânio. O exame mostra uma lesão tumoral expansiva\nfrontal esquerda, contendo áreas de hemorragia medindo 45 mm, envolvida por acentuado edema,\ndesviando as estruturas da linha mediana para o lado oposto. As duas principais possibilidades\ndiagnósticas, nesse caso, seriam:","options":{"A":"Astrocitoma e oligodendroglioma.","B":"Glioblastoma e metástase.","C":"Ganglioglioma e xantoastrocitoma.","D":"Ependimoma e astroblastoma."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-84434","number":"84434","sourceNumber":"84434","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com relação ao acidente vascular cerebral hemorrágico e suas repercussões na\nlaringe, podemos afirmar:","options":{"A":"A hipotonia dos grupos musculares ocorre frequentemente e, portanto, a fala volta aos poucos.","B":"Ao deglutir, o paciente tem espasmos da hipofaringe e fonação tensa com hemiparalisia\nlaríngea. Apesar destes achados, o refluxo é\nincomum.","C":"Durante a deglutição, a elevação da laringe ocorre assimetricamente, e, portanto, há um\ndistanciamento do plano da coluna, o que acarreta uma abertura inapropriada do esfíncter\nesofagiano. Nestes pacientes, o refluxo é comum.","D":"As alterações são semelhantes àquelas encontradas nos pacientes com acidente vascular\nisquêmico.","E":"O acidente vascular cerebral não tem relação com sintomas laríngeos."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-61727","number":"61727","sourceNumber":"61727","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A síndrome de secção medular transversa unilateral (Brown-Séquard) é rara na sua\napresentação completa. Superado o choque medular inicial, na sua apresentação clínica, não pode\nfigurar a:","options":{"A":"Paralisia espástica ipsolateral com hiperreflexia e reflexos anormais no pé, abaixo do nível da\nlesão.","B":"Abolição da sensibilidade térmica e dolorosa ipsolateral, abaixo do nível da lesão.","C":"Abolição da sensibilidade postural e vibratória ipsolateral, abaixo do nível da lesão.","D":"Preservação da sensibilidade tátil simples.","E":"Paralisia flácida do miótomo, acima do nível da lesão."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-69222","number":"69222","sourceNumber":"69222","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"O exame neurológico da síndrome de hemissecção medular apresenta os seguintes\nsinais:","options":{"A":"déficit motor ipsilateral, abaixo do nível da lesão com apalestesia associada.","B":"déficit motor contralateral, abaixo do nível da lesão e hipoesteria termoalgésica ipsilateral.","C":"déficit motor bilateral, abaixo do nível da lesão e hipoestesia termoalgésica bilateral.","D":"défict motor ipsilateral, abaixo do nível da lesão e hipoestesia termoalgésica ipsilateral.","E":"déficit motor ipsilateral, abaixo do nível da lesão e apalestesia contralateral."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-61276","number":"61276","sourceNumber":"61276","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com respeito à afasia, assinale a alternativa correta:","options":{"A":"na afasia de Wernicke, os pacientes têm severo prejuízo na compreensão da linguagem oral,\nmas não da escrita. Não costumam perceber suas dificuldades de comunicação.","B":"na afasia de Broca, depressão é comum, porque os pacientes têm a compreensão preservada e\nficam frustrados por perceberem suas dificuldades de expressão.","C":"na afasia anômica, os pacientes têm leve dificuldade de repetição de palavras, com grande\ndificuldade de compreensão.","D":"as afasias ocorrem por lesões nos hemisférios dominantes. Em quase todos os casos são\nlesões no hemisfério esquerdo para os indivíduos destros e lesões no hemisfério direito para\nindivíduos canhotos.","E":"afasias secundárias a acidentes vasculares cerebrais são, em geral, definitivas com mínima\nmelhora posterior."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-61279","number":"61279","sourceNumber":"61279","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com respeito à demência vascular, indique a alternativa incorreta:","options":{"A":"a maior parte dos casos de doença vascular que causa comprometimento cognitivo é devida à\naterosclerose.","B":"infartos envolvendo arteríolas cerebrais, como infartos lacunares no tálamo, gânglios da base e\nsubstância branca subcortical podem levar a distúrbio cognitivo importante.","C":"a presença simultânea de Doença de Alzheimer é rara na demência vascular.","D":"início de perturbação cognitiva até 3 meses após um acidente vascular cerebral é sugestivo de\ndemência vascular.","E":"a demência vascular pode estacionar, sem piora do quadro, com o decorrer do tempo."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-64603","number":"64603","sourceNumber":"64603","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Que região do Sistema Nervoso Central, que envolvida em algum processo patológico\nlesional, NÃO acarreta nenhum déficit motor?","options":{"A":"Córtex do giro pré-central.","B":"Cápsula Interna.","C":"Pedúnculo cerebral.","D":"Lobo Temporal.","E":"Regiões antero-laterais da medula espinhal."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-61809","number":"61809","sourceNumber":"61809","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"As causas mais comuns de hemorragia subaracnoidea são:","options":{"A":"Ruptura de aneurisma, hipertensão arterial, malformação arteriovenosa cerebral","B":"Malformação arteriovenosa cerebral, tumores, doenças do colágeno","C":"Arterites, tumores, embolias","D":"Neoplasias, arterites, aneurismas","E":"Infecções, traumas, encefalites"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-61796","number":"61796","sourceNumber":"61796","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre as demências é CORRETO afirmar:","options":{"A":"Podem abrir como estado confusional agudo associado a rebaixamento do nível de consciência.","B":"A demência vascular é a principal causa de demência no nosso meio.","C":"É essencial para o diagnóstico clínico das demências que o déficit cognitivo seja importante o\nbastante para interferir nas atividades de vida diária.","D":"Na demência de Alzheimer ocorrem alucinações visuais bem formadas já no primeiro ano de\ninstalação do quadro.","E":"Na demência de Alzheimer, o principal neurotransmissor envolvido é a dopamina, com marcada\nredução de sua síntese."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-61828","number":"61828","sourceNumber":"61828","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com relação às medidas terapêuticas gerais no atendimento de pacientes com\nisquemia encefálica, podemos afirmar que:","options":{"A":"O manitol deve ser utilizado de rotina para prevenção do edema encefálico para minimizar ou\nprevenir agravos do quadro clínico.","B":"Oxigenoterapia deve ser sempre ofertada para preservar ao máximo os neurônios ainda viáveis\nda chamada zona de penumbra isquêmica.","C":"Cabeceira elevada é a medida mais eficaz na prevenção de hipertensão intracraniana por\nedema secundário às isquemias encefálicas.","D":"Para prevenção de broncoaspiraçâo pulmonar, o paciente com nível de consciência rebaixado\ndeve ser mantido em dieta zero.","E":"Corticoterapia deve ser instituída nas isquemias encefálicas precocemente no intuito de se\nprevenir edema encefálico."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-53617","number":"53617","sourceNumber":"53617","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem, 70 anos, hipertenso, diabético, apresentou quadro súbito de hemiparesia D\ncom predomínio braquial, sem déficits sensitivos\nou alterações da palavra. A hipótese diagnóstica\né:","options":{"A":"embolia de artéria cerebral posterior.","B":"trombose de artéria cerebral anterior.","C":"infarto lacunar.","D":"infarto do braço posterior da cápsula interna.","E":"hematoma de tegmento mesencefálico."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-51021","number":"51021","sourceNumber":"51021","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A senhora Tânia, 61 anos, refere tontura intermitente que interfere em suas atividades\ndiárias. O exame físico revela reflexo\ncorneano direito reduzido e hipoacusia à direita. Qual o\ndiagnóstico mais provável?","options":{"A":"Infarto pontino.","B":"Vertigem postural paroxística benigna.","C":"Síndrome bulbar lateral.","D":"Doença de Menière.","E":"Tumor do ângulo pontinocerebelar."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-48998","number":"48998","sourceNumber":"48998","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 30 anos procura assistência ambulatorial neurológica, com queixa de crises\nde cefaléia, que evoluem desde a adolescência.\nAs crises são caracterizadas por uma fase inicial\nde manchas cintilantes em um campo visual, durando vários minutos, seguido de parestesias, tipo\ndormência, que acometem face e membro superior, também durando vários minutos, seguido de\ndificuldade para expressar a linguagem falada, caracterizando uma afasia de expressão, também\nde curta duração (vários minutos). Logo após esses sintomas apresenta uma cefaléia intensa,\nnormalmente hemicraniana, pulsátil, intensa, acompanhada de náuseas, foto e fonofobia, que dura\nvárias horas e até dois dias. Baseado na história descrita, responda os locais envolvidos na gênese\ndos sintomas neurológicos descritos (cintilações, parestesias e afasia):","options":{"A":"Lobo occipital, lobo parietal e lobo frontal.","B":"Lobo temporal, lobo frontal e lobo parietal.","C":"Lobo frontal, lobo occipital e lobo parietal.","D":"Lobo parietal, ínsula e lobo temporal.","E":"Ínsula, lobo temporal e lobo occipital."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-48810","number":"48810","sourceNumber":"48810","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Jovem, com AVC hemorrágico temporal D, não cirúrgico, adequadamente sedado, sob\nventilação controlada e estável hemodinamicamente. PIC (Pressão Intracraniana) de 15 mmHg,\nSvjO2 cai para 50% e a SaO2 permanece em 97%. Concomitantemente apresentou hipertensão e\nbradicardia. Qual a EXPLICAÇÃO FISIOLÓGICA para este aumento da PIC e queda na SvjO2?","options":{"A":"Hiperemia cerebral.","B":"Redução no consumo cerebral em O2.","C":"Edema cerebral e/ou ressangramento com efeito da massa.","D":"Aumento da pressão de perfusão cerebral secundária à Hipertensão.","E":"Queda no débito cardíaco secundária à ventilação mecânica."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-35615","number":"35615","sourceNumber":"35615","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 40 anos com história de cefaleia súbita intensa há 1 dia sem melhora com\nanalgésico, acompanhada de queda de pálpebra direita. Ao exame físico estava em bom estado\ngeral, afebril com PA= 140x90 mmHg. Ao exame neurológico encontrava-se orientado no tempo e\nespaço, sem déficits motores com reflexos normais bilateralmente. Havia rigidez de nuca e paralisia\nmotora ocular do terceiro nervo à direita com ptose de pálpebra direita e anisocoria com pupila\ndireita maior que a esquerda com reflexo fotomotor presente à esquerda e ausente à direita. Qual é\na hipótese diagnóstica e a topografia da lesão?","options":{"A":"Neuropatia aguda no nervo oculomotor.","B":"Trombose do seio cavernoso.","C":"Hemorragia mesencefálica.","D":"Hemorragia meníngea por aneurisma de artéria basilar.","E":"Hemorragia meníngea por aneurisma de artéria comunicante posterior."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-35835","number":"35835","sourceNumber":"35835","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Dos medicamentos abaixo qual não leva à Síndrome de Parkinsoniana?","options":{"A":"Antiadesivo plaquetário.","B":"Metildopa.","C":"Neurolépticas.","D":"Flunarizina.","E":"Amiodarona."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-35837","number":"35837","sourceNumber":"35837","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em um paciente com história de cefaleia súbita, seguida de perda de consciência, que\ncursou com ptose palpebral à direita, pode apresentar um aneurisma na emergência de qual vaso\ncerebral?","options":{"A":"Artéria cerebral anterior direita.","B":"Artéria basilar.","C":"Artéria pericalosa esquerda.","D":"Artéria comunicante posterior direita.","E":"Artéria cerebelar superior."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-35840","number":"35840","sourceNumber":"35840","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Dos exames abaixo, qual o mais sensível na detecção precoce do AVC isquêmico?","options":{"A":"Doppler craniano.","B":"TC de crânio.","C":"RNM crânio por difusão.","D":"Angiografia cerebral.","E":"Rx de crânio."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-35841","number":"35841","sourceNumber":"35841","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Constitui o principal marcador anatomo-patológico na doença de Parkinson:","options":{"A":"Neurofilamentos.","B":"Degeneração nigroestriatal.","C":"Corpúsculos com inclusão citoplasmáticos.","D":"Placas amiloidóticas.","E":"Vacuolização citoplasmática."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-34021","number":"34021","sourceNumber":"34021","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo feminino, 72 anos, há dois anos vêm apresentando esquecimento\npara fatos cotidianos (esquece de dar recados\ne já esqueceu por duas vezes panelas no fogo). Há\numa semana, saiu sozinha para comprar pão e se perdeu, levando duas horas para retornar a\ncasa. Nega doenças prévias. Após o ocorrido, seus familiares a levaram à consulta. Exames clínico\ngeral e neurológico normais. Qual é o diagnóstico clínico, nesse caso?","options":{"A":"Doença de Alzheimer.","B":"Crise parcial do lobo temporal.","C":"Crise de ausência.","D":"Amnésia global transitória."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-26955","number":"26955","sourceNumber":"26955","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Alcoólatra é admitido após queda da própria altura, em estado de coma profundo e com\nexame neurológico relevando hiperpneia\nneurogênica, pupilas mediodilatadas e não fotorreagentes,\ndiminuição do reflexo oculocefálico e esboçando postura de descelebração à direita. O local\nprovável da lesão é:","options":{"A":"ponte","B":"diencéfalo","C":"mesencéfalo","D":"bulbo","E":"centro semioval"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-23036","number":"23036","sourceNumber":"23036","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Leia o caso clínico a seguir. Uma paciente de 25 anos, do sexo feminino, com\ndiagnóstico prévio de migrânia com aura,\napresentou piora das crises e se automedicou com\nsumatriptano em uso contínuo por 10 dias e, apesar da melhora da dor, a paciente evoluiu com\nparestesia seguida de hemiparesia esquerda de predomínio braquiofacial, hiper-reflexia, Hoffmann\ne Babinski à esquerda, sem alterações sensitivas ou da consciência e com coordenação\npreservada, sem rigidez de nuca e demais pares cranianos normais. Essa paciente é obesa e\ndislipidêmica, sem outras comorbidades. Com base nesses dados clínicos, o diagnóstico\ntopográfico neurológico e a hipótese diagnóstica principal são, respectivamente:","options":{"A":"Território de artéria cerebral média direita e doença vascular encefálica isquêmica.","B":"Território de artéria comunicante anterior e hemorragia subaracnoidea.","C":"Território de artéria cerebral anterior direita e doença vascular encefálica hemorrágica.","D":"Território de artéria cerebral posterior direita e infarto migranoso."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-27190","number":"27190","sourceNumber":"27190","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"O sinal de Babinski é importante meio propedêutico ao exame físico. Qual o método\npara provocá-lo e a que tipo de lesão orgânica\nque o mesmo está relacionado, na população\nadulta?","options":{"A":"Estímulo nociceptivo em dorso do pé com hiperflexão dos dedos - lesão de cone medular.","B":"Estímulo nociceptivo plantar em arco resultando em dorsiflexão do hálux - lesão de via\nextrapiramidal.","C":"Estímulo nociceptivo plantar em arco resultando em flexão plantar do hálux - lesão de via\npiramidal.","D":"Estímulo nociceptivo em hálux com flexão plantar do mesmo - lesão de funículo posterior da\nmedula.","E":"Estímulo nociceptivo plantar em arco resultando em dorsiflexão de hálux - lesão de via\npiramidal."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-10668","number":"10668","sourceNumber":"10668","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Alcoólatra é admitido após queda da própria altura, em estado de coma profundo e com\nexame neurológico revelando: hiperpneia\nneurogênica, pupilas mediodilatadas e não\nfotorreagentes; diminuição do reflexo oculocefálico e esboçando postura de descerebração à\ndireita. O local provável da lesão é:","options":{"A":"ponte.","B":"diencéfalo.","C":"região subcortical.","D":"tálamo.","E":"mesencéfalo."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-8947","number":"8947","sourceNumber":"8947","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 60 anos consulta-se no ambulatório de neurologia com queixas de\nvertigens atípicas há anos, desenvolvendo dificuldade para deambular e tremor nas mãos há\nalguns meses. Faz uso crônico de Flunarizina e Propranol, sem nenhuma melhora clínica. Ao\nexame, observa-se tremor de repouso,marcha a pequenos passos e grande dificuldade nos\nmovimentos alternados de prono-supinação. Qual o diagnóstico mais provável?","options":{"A":"Doença de Parkinson","B":"Tremor Essencial","C":"Parkinsonismo Medicamentoso","D":"Tremor Fisiológico Exacerbado"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-8959","number":"8959","sourceNumber":"8959","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"O sinal de Romberg clássico traduz lesão/disfunção de quais estruturas do Sistema\nNervoso?","options":{"A":"Cerebelo","B":"Cápsula Interna","C":"Funiculo posterior da medula","D":"Raízes ventrais dos nervos espinhais"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-9340","number":"9340","sourceNumber":"9340","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"BSC, de 65 anos, sexo masculino, tem quadro arrastado (seis meses) de alteração da\nforça muscular, que iniciou na perna esquerda, com dificuldades de levantar o pé e, após três\nmeses, a outra perna também estava fraca. Há um mês, os sintomas pioraram, aparecendo\nfraqueza do braço esquerdo e alteração da voz. Ao exame, notam-se atrofia muscular,\nsensibilidade normal, hiperreflexia global a fasciculação. O diagnóstico do quadro descrito é:","options":{"A":"esclerose múltipla","B":"esclerose lateral amiotrófica","C":"esclerose de Shilder","D":"esclerose de Baló"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-11057","number":"11057","sourceNumber":"11057","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente com quadro de cefaleia súbita, intensa, com rigidez nucal e sonolência. O\ndiagnóstico e a propedêutica mais correta é:","options":{"A":"Hemorragia subaracnoidea espontânea/realização de punção lombar","B":"Meningite/realização de punção lombar","C":"Hemorragia subaracnóidea espontânea/realização de tomografia computadorizada de crânio","D":"Ruptura de malformação arteriovenosa cerebral/realização de TC de crânio","E":"Sangramento de tumor cerebral/realização de arteriografia cerebral"},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-11062","number":"11062","sourceNumber":"11062","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual achado clínico mais comum em relação a Síndrome da cauda equina?","options":{"A":"Retenção urinária","B":"Lombociatalgia bilateral","C":"Anestesia em ?sela?","D":"Incontinência urinária","E":"Paraparesia acentuada"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-274014","number":"274014","sourceNumber":"274014","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança de 4 anos é atendida em serviço de urgência, com quadro de febre elevada há\n48 horas, com cefaleia referida no início do\nquadro e adinamia. Evoluiu nas últimas 12 horas com\nsonolência excessiva e crises convulsivas febris frequentes. Durante o exame físico,\n\napresentava-se sonolenta, comatosa, só responsiva a estímulos dolorosos e pouco desidratada,\nsem sinais de irritação meníngea, com pupilas\nisocóricas. Após 5 minutos, apresentou crise\nconvulsiva que cedeu espontaneamente. Foi colocada em O? em máscara de Venturi, feito uma\nexpansão volêmica com soro fisiológico 20 mg/Kg, apresentando em seguida boa diurese e\nglicemia capilar de 120mg%. Foi colhido hemoculturas, hemograma completo e colhido líquor para\nexames. O exame do líquor mostrou os seguintes resultados: citologia - 145 leucócitos/mm³, sendo\n85% de mononucleares e 15% de polimorfonucleares, hemácias: 10 células/mm³, proteínas:\n35mg%, glicose: 89mg%. Hemograma com leucócitos totais de 16.500/mm³ (neutrófilos = 56%,\nlinfócitos= 34%, monócitos = 10%), Hb - 12,3g% e plaquetometria de 270.000/mm³. Aguarda-se a\nbacterioscopia, teste de aglutinação por látex do líquor. O diagnóstico MAIS PROVÁVEL é:","options":{"A":"Meningite viral por coxsakievírus.","B":"Meningite meningocócica.","C":"Meningoencefalite causada por herpesvírus.","D":"Abscesso cerebral estafilocócico."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-274015","number":"274015","sourceNumber":"274015","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Menor de 1 ano de idade, com quadro de tosse e leve dispneia há 40 dias, com febre\nbaixa intermitente, foi atendido algumas vezes em\nUPA, onde foram prescritos 2 esquemas de\nantibióticos orais, sendo o primeiro de amoxicilina oral por 10 dias e o segundo de azitromicina por\n5 dias, com doses normais. Não houve melhora do quadro, mantendo imagem radiológica de\ninfiltrado pulmonar em hemitórax direito. Há 1 semana, vem evoluindo ainda com febre, com\naparecimento de choro frequente e irritabilidade. Foi realizado punção lombar, com alguns\nresultados do exame do líquor, apresentando pleocitose de 450 leucócitos/mm³, sendo 90% de\nlinfócitos e 10% de polimorfonucleares, com proteinorraquia de 160mg% e glicorraquia de 68mg%.\nAguarda-se outros exames do líquor. Baseado nesses dados, a PRINCIPAL hipótese diagnóstica é:","options":{"A":"Meningite bacteriana.","B":"Meningoencefalite herpética.","C":"Meningite criptocócica.","D":"Meningoencefalite tuberculosa."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-250227","number":"250227","sourceNumber":"250227","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 72 anos, sexo feminino, refere episódio de perda súbita da visão em olho\nesquerdo com posterior melhora, porém mantendo escotoma visual, cefaleia hemicraniana\nesquerda contínua, rigidez de predomínio proximal em membros e cervical, perda ponderal e\nepisódios febris. Exame laboratorial mostra VHS maior que 100 mm/h. De acordo com o quadro\nclínico, assinale a alternativa CORRETA:","options":{"A":"A arterite temporal leva ao acometimento exclusivo do sistema nervoso central.","B":"A arterite temporal não aumenta o risco de acidente vascular isquêmico.","C":"A arterite temporal pode levar ao acometimento sistêmico: aneurisma de aorta e artérias\nmesentéricas e derrame pericárdico.","D":"A biópsia de artéria temporal negativa exclui o diagnóstico de arterite temporal."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-216416","number":"216416","sourceNumber":"216416","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre a realização de precaução e isolamento de pacientes, selecione a opção\nCORRETA para a indicação adequada de precaução\nde uma criança de 3 anos com meningite\nmeningocócica.","options":{"A":"Precaução respiratório por gotícula.","B":"Precaução respiratória por gotícula, sendo utilizada como equipamento de proteção individual a\nutilização da máscara N95.","C":"Precaução respiratória por aerossóis, sendo utilizada como equipamento de proteção individual\na utilização da máscara N95.","D":"Precaução respiratória por aerossóis, sendo utilizada como equipamento de proteção individual\na utilização de máscara cirúrgica."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-176216","number":"176216","sourceNumber":"176216","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um bebê de 1 ano e 2 meses de idade foi atendido em pronto-socorro e, segundo a\nmãe, ele estava resfriado havia quatro\ndias, apresentando febre alta, vômitos e letargia. No exame\nfísico, o médico constatou que a criança estava febril, taquicárdica, com rigidez de nuca, petéquias\nesparsas pelo tronco, mas sem sinais meníngeos. O bebê mostrou-se irritado ao manuseio, ficando\nletárgico quando não examinado. O médico realizou punção lombar para a coleta de liquor cuja\nanálise demonstrou leucócitos de 1.200/mm³, com predomínio de polimorfonucleares, proteínas de\n200 mg/dl e glicose de 35 mg/dl. Em face dessas constatações, o médico prescreveu tratamento de\ninício imediato com ceftriaxona (100 mg/kg/dia), de 24/24h. Em relação a esse caso clínico, marque\n\n?V? para Verdadeiro e ?F? para Falso. ( ) A ausência dos sinais meníngeos descarta o diagnóstico\nde meningite para o paciente em questão. ( ) O\ntratamento com ceftriaxona deve ser mantido por\nseis ou sete dias, quando poderá ser suspenso. ( ) A doença que consiste no provável diagnóstico\npara o caso clínico em questão é frequentemente precedida por sintomas do trato respiratório ou\ngastrointestinais. ( ) A doença que consiste no provável diagnóstico para o caso clínico em questão\né mais grave se estiver associada à meningite. Assinale a alternativa CORRETA.","options":{"A":"F, V, V, V.","B":"V, F, V, F.","C":"F, V, F, V.","D":"F, F, V, F.","E":"F, F, V, V."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-176264","number":"176264","sourceNumber":"176264","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente com 3 meses de idade, com quadro de febre, vômitos e abaulamento de\nfontanela foi atendida na urgência e\nrealizada imediatamente a coleta de líquor, com pleocitose de\n\n2.400 leucócitos/mm3, sendo 93% de polimorfonucleares, proteinorraquia de 90mg/dL e\nglicorraquia de 26mg/dL. Fez bacterioscopia,\nque evidenciou frequentes bacilos Gram-negativos. O\ndiagnóstico MAIS PROVÁVEL é:","options":{"A":"Meningite por Mycobacterium tuberculosis.","B":"Meningite por Mycoplasma pneumoniae.","C":"Meningite por Haemophilus influenzae.","D":"Meningite por Streptococcus pneumoniae.","E":"Meningite por Escherichia coli."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-139222","number":"139222","sourceNumber":"139222","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente, 72 anos, previamente hipertenso, diabético e antecedente de cardiopatia, é\nadmitido no pronto atendimento com relato de ter apresentado hemiparesia esquerda. Durante a\navaliação no serviço de urgência não foi observado déficit motor, ritmo cardíaco sinusal, PA: 140/90\nmmHg. E, segundo acompanhantes, houve melhora do déficit motor após tempo aproximado de 02\nhoras. Com relação ao exposto é CORRETO afirmar que:","options":{"A":"Será caracterizado como Ataque Isquêmico Transitório (AIT) a reversão completa do déficit\nmotor associado ao exame de imagem normal, sendo\npreferencialmente esse exame a ressonância\nde crânio, devendo o paciente permanecer internado.","B":"Não existe indicação de propedêutica complementar, devendo o paciente receber alta hospitalar.","C":"Deve-se administrar AAS 300 mg e liberar paciente para o domicílio.","D":"É necessária realização de tomografia de crânio, estando a mesma dentro da normalidade, o\npaciente deverá receber alta hospitalar.","E":"Quadro clínico compatível com AIT, não sendo necessário propedêutica, podendo ser o paciente\nliberado para casa."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-105722","number":"105722","sourceNumber":"105722","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"O uso de anticoagulantes parenterais e/ou orais é recomendado em várias situações da\nprática clínica. Considerando um paciente de 61 anos, com 80 kg e função renal normal, avalie\ncada contexto clínico abaixo, suas respectivas prescrições de anticoagulante e marque a\nassociação MENOS adequada:","options":{"A":"Paciente em fase aguda do AVC isquêmico não cardioembólico e que não fez uso de\ntrombolítico. Enoxaparina 80 mg SC 12/12h.","B":"Paciente em fase aguda do IAM sem elevação do segmento ST. HNF 60 UI/kg EV (ataque)\nseguido por infusão contínua inicial de 12 UI/kg/h EV.","C":"Paciente ambulatorial, portador de fibrilação atrial persistente, não será submetido à\ncardioversão e seu escore CHADS-VASC é igual a 3. Varfarina 5 mg VO 1x/dia (dose inicial).","D":"Paciente no 2° dia pós-operatório de artroplastia de joelho. HNF 5.000 UI SC 8/8h.","E":"Paciente internado com diagnóstico de TVP em MIE confirmado por USG Doppler. HNF 80 UI/kg\nEV (ataque) seguido por infusão contínua\ninicial de 18 UI/kg/h EV."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-105702","number":"105702","sourceNumber":"105702","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na fase inicial da Doença de Parkinson, é INCORRETO afirmar que:","options":{"A":"Os anticolinérgicos têm efeito neuroprotetor, ocasionando melhor qualidade de vida a estes\npacientes, devendo ser usados desde o início.","B":"O quadro clínico que se apresenta na sua forma cinético-rígida torna-se mais propenso a\napresentar quadro demencial com a evolução da doença do que naqueles com quadro com\npredomínio de tremor.","C":"O uso de amantadina tem como efeitos colaterais comuns o edema periférico nos membros\ninferiores e maior propensão a alucinações.","D":"A terapia dopaminérgica, quer seja feita com agonistas dopaminérgicos ou com levodopaterapia,\né o tratamento mais adequado na maioria dos\ncasos.","E":"A amantadina tem sua maior eficácia para tratamento das discinesias relacionadas à levodopa,\nsendo considerada uma medicação antidiscinética."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-105652","number":"105652","sourceNumber":"105652","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"De acordo com os atuais critérios diagnósticos para Esclerose Múltipla (EM), o surto ou\nexacerbação da doença pode ser definido como:","options":{"A":"Evento neurológico agudo com duração de 48 horas confirmado através do exame neurológico\nobjetivo.","B":"Sinal ou sintoma neurológico novo com duração de 2 horas associado com lesão desmielinizante\nvisualizada na imagem por ressonância\nmagnética de crânio.","C":"Sinal ou sintoma neurológico relatado pelo paciente com qualquer duração na presença de\nalteração no exame neurológico.","D":"Sintoma neurológico persistente por mais de 7 dias.","E":"Evento desmielinizante inflamatório agudo objetivamente observado, ou relatado pelo paciente,\ncom duração de pelo menos 24 horas, na ausência\nde febre ou infecção."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-84930","number":"84930","sourceNumber":"84930","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A hipertensão intracraniana é uma síndrome que pode ter diversas etiologias, tais\ncomo: vasculares, infecciosas, neoplásicas,\ntraumáticas, etc. Além do tratamento específico da\ncausa básica, várias condutas, algumas com melhores evidências em determinadas etiologias, são\npreconizadas como tratamento de suporte. Dentre as condutas abaixo, a menos indicada seria:","options":{"A":"Ventilação mecânica com hipercapnia permissiva.","B":"Osmoterapia.","C":"Sedação com midazolam ou propofol e, em casos graves, barbitúricos.","D":"Ventriculostomia.","E":"Hipotermia."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-80926","number":"80926","sourceNumber":"80926","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Com relação ao tremor da doença de Parkinson, é CORRETO afirmar:","options":{"A":"É simétrico e de repouso.","B":"Envolve os quatro membros e é de intenção.","C":"É assimétrico e de repouso.","D":"É simétrico e de intenção.","E":"É assimétrico e de intenção."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-84928","number":"84928","sourceNumber":"84928","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente com 56 anos relata que há 1 mês vem apresentando episódios paroxísticos de\ndor em face à esquerda. Descreve que a dor é de caráter súbito com duração de aproximadamente\n1 minuto, apresenta várias crises durante o dia, acomete a topografia de mandíbula à esquerda\ncom sensação de choque e pontada, de forte intensidade e desencadeada pelo ato de escovar os\ndentes. Diante do caso, qual sua principal hipótese diagnóstica e a melhor terapêutica indicada:","options":{"A":"Neuralgia do trigêmeo, tratamento com carbamazepina.","B":"Hemicrania paroxística, tratamento com indometacina.","C":"Enxaqueca sem aura, tratamento com betabloqueador.","D":"Neuralgia do trigêmeo, tratamento com amitripitilina.","E":"Disfunção temporomandibular, tratamento com anti-inflamatórios."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-47492","number":"47492","sourceNumber":"47492","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma mulher de 78 anos de idade, com uma longa história de doença vascular\napresenta-se após um acidente vascular cerebral\nembólico com dor severa e inflexível do lado\ndireito. Descreve a dor como queimação, como se tivesse sido banhado em ácido. Onde é o local\nmais provável do AVE (Acidente Vascular Encefálico) embólico recente?","options":{"A":"Tálamo.","B":"Hipotálamo.","C":"Ponte.","D":"Lobo temporal.","E":"Lobo frontal."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-35746","number":"35746","sourceNumber":"35746","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um homem de 67 anos é visto na clínica para uma consulta de rotina. Ele se queixa de\ndificuldade na marcha que piorou progressivamente, ao longo de muitos meses. Ele também notou\n\n?tremor? de mãos, com quedas de objetos ocasionalmente. Ele está muito chateado por estes\nproblemas e admite frequentes crises de\nchoro. Apresenta doença do refluxo gastroesofágico e\ndislipidemia. Atualmente, está em uso de inibidor de bomba de prótons e estatina. Seus sinais vitais\nestão dentro dos limites normais. No exame físico, há um tremor perceptível grosseiro das mãos,\npior à esquerda. Sua marcha é lenta e de base ampla. Qual das estruturas cerebrais que se\nseguem é a mais provavelmente afetada nesse paciente?","options":{"A":"Núcleos da rafe caudal.","B":"Hipocampo.","C":"Lócus ceruleus.","D":"Núcleo basal de Meynert.","E":"Substância nigra."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-311526","number":"311526","sourceNumber":"311526","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Adolescente do sexo masculino, 13 anos, é levado à emergência por cefaleia intensa,\nvômitos em jato há dias e febre (38,5ºC)\nque não cede com antitérmicos. Exame físico: desidratado,\nfebril, sinais de irritação meníngea, escala de Glasgow de 15. Punção lombar: pleocitose, com 570\ncélulas/mm3, 20.000 hemácias/ mm3, com predomínio de linfomononucleares; proteína: 45mg/dL;\nglicorraquia: 66mg/ dL (glicemia: 90mg/dL). Esse quadro clínico sugere:","options":{"A":"Meningite viral.","B":"Trauma de punção.","C":"Meningite bacteriana.","D":"Hemorragia subaracnoide.","E":"Doenças autoimunes."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-311528","number":"311528","sourceNumber":"311528","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Escolar do sexo masculino, seis anos, apresenta queixa de cefaléia recorrente há dois\nmeses. Mãe relata que notou leve estrabismo e dificuldade visual há cerca de 30 dias. Foi ao\noftalmologista, que prescreveu óculos. Há 15 dias a mãe observou que seu filho apresentava\nlateralização da cabeça (\"torcicolo\"). A hipótese diagnóstica é:","options":{"A":"Retinoblastoma.","B":"Doença de Coats.","C":"Tumor do sistema nervoso central.","D":"Apenas dor muscular.","E":"Leucemia linfoide aguda com infiltração do SNC."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-263695","number":"263695","sourceNumber":"263695","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na Doença Meningocócica, a quimioprofilaxia, embora não assegure efeito protetor\nabsoluto e prolongado, tem sido adotada como uma medida eficaz na prevenção de casos\nsecundários. Qual antibiótico é indicado para a quimioprofilaxia de contatos próximos de casos\nsuspeitos de meningite por H. influenzae tipo b e doença meningocócica?","options":{"A":"Ceftriaxona.","B":"Rifampicina.","C":"Pirazinamida.","D":"Isoniazida.","E":"Etambutol."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-281468","number":"281468","sourceNumber":"281468","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Escolar, sexo masculino, 6 anos, apresenta queixa de cefaleia recorrente há dois\nmeses. Mãe relata também que notou leve\nestrabismo e dificuldade visual há cerca de 30 dias. Foi\nao oftalmologista, que prescreveu óculos. Há 15 dias a mãe observou que seu filho apresentava\nlateralização da cabeça (\"torcicolo\"). A hipótese diagnóstica é:","options":{"A":"Doença de Coats.","B":"Tumor do sistema nervoso central.","C":"Leucemia linfoide aguda com infiltração do SNC.","D":"Trauma raquimedular.","E":"Nenhuma das questões acima."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-281503","number":"281503","sourceNumber":"281503","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente feminina de 60 anos, portadora de diabetes insulinodependente, interna por\nquadro de febre e sonolência. Realiza exames e inicia quinolona para tratamento de infecção de\ntrato urinário. Horas depois, retorna ao PS em coma. Realiza tomografia de crânio que é normal.\nColetado líquor que tem o seguinte resultado: 15 leucócitos, 10 hemácias, proteína aumentada e\nglicorraquia normal. Bacterioscopia e látex do líquor normais. Qual a hipótese diagnóstica mais\nprovável:","options":{"A":"Meningite.","B":"Infecção de trato urinário","C":"Encefalite.","D":"Delirium pelo uso do antibiótico.","E":"Mieloma múltiplo."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-278981","number":"278981","sourceNumber":"278981","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre a cefaleia migrânea em crianças, assinale a alternativa correta:","options":{"A":"Apresenta distúrbios da fala e movimentos tônico-clônicos.","B":"Apresenta episódios recorrentes de dor de cabeça, de intensidade leve a moderada.","C":"Caracteriza-se por dor localizada, pulsátil, mas que tende a melhorar com a prática de atividade\nfísica.","D":"Apresenta duração dos episódios de dor maior do que em adultos, o que provoca incapacitação\npara atividades diárias.","E":"Pode ser acompanhada por náuseas, vômitos ou sensibilidade à luz e ao som."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-278982","number":"278982","sourceNumber":"278982","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre as encefalites, assinale a alternativa correta:","options":{"A":"Seu principal agente etiológico no Brasil é o Herpes Simples Vírus 1.","B":"Apresentam melhor prognóstico que as meningites.","C":"Quando cursam com sinais meníngeos, a sintomatologia meníngea se sobrepõe à resultante do\nacometimento primário do encéfalo.","D":"São definidas como infecções das membranas que envolvem e protegem o sistema nervoso\ncentral.","E":"Nas encefalites, o exame do líquor sempre está alterado."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-250389","number":"250389","sourceNumber":"250389","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 34 anos, sexo masculino, com história de cefaleia moderada há 4 dias,\nrefratária a analgésicos. Relata ainda episódios de febre, calafrio e vômitos. Ao exame físico\napresenta flexão involuntária do joelho e do quadril quando se faz flexão do pescoço. Sobre esse\npaciente, pode-se afirmar corretamente que:","options":{"A":"O quadro é sugestivo de meningite. O paciente necessita de punção lombar e só pode iniciar a\nantibioticoterapia após a coleta do líquor para evitar o tratamento com cobertura inadequada.","B":"O quadro é sugestivo de hemorragia subaracnoideia aneurismática e o paciente deve realizar\numa angiografia de urgência.","C":"O quadro é sugestivo de meningite e está indicada coleta de liquor. Se não houver\ndisponibilidade em tempo hábil, a\nantibioticoterapia deve ser iniciada com cobertura empírica.","D":"O quadro é sugestivo de hidrocefalia de pressão normal e o paciente deve realizar uma\ntomografia para confirmar a suspeita clínica.","E":"O quadro é sugestivo de hidrocefalia obstrutiva e o paciente deve realizar uma ressonância para\nconfirmar a suspeita clínica."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-203598","number":"203598","sourceNumber":"203598","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A Etiologia mais provável para meningite em crianças de 0 a 2 meses é:","options":{"A":"Pneumococo.","B":"Meningococo.","C":"Haemophilus influenzae.","D":"Staphylococcus aureus.","E":"Streptococcus do grupo B."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-203303","number":"203303","sourceNumber":"203303","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre as Meningites Agudas Bacterianas, selecione a opção correta no que se refere a\nrecomendação adequada à realização de precaução e isolamento de pacientes.","options":{"A":"Está indicada a realização de Precaução Reversa, sendo utilizada como equipamento de\nproteção individual a utilização da máscara N95.","B":"Está indicada a realização de Precaução Respiratória por Gotícula, sendo utilizada como\nequipamento de proteção individual da máscara N95.","C":"Está indicada a realização de Precaução Padrão","D":"Está indicada a realização de Precaução Respiratória por Aerossóis, sendo utilizada como\nequipamento de proteção individual a utilização da máscara N95.","E":"Está indicada a realização de Precaução Respiratória por Gotícula."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-203289","number":"203289","sourceNumber":"203289","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança, 2 anos e 8 meses, deu entrada no hospital infantil, com quadro de febre,\nirritabilidade e vômito há 3 dias. O menor\ntem sinal de Kernig positivo. Evolui com rebaixamento do\nnível de consciência e convulsões. O hemograma evidenciou leucocitose com linfocitose; proteína\nC-reativa = 2,5. Realizado TC de crânio de urgência que evidenciou normalidade. Realizada\npunção liquórica que resultou em um liquor límpido com leucorraquia com predomínio linfocítico e\nteste látex negativo. Tendo em conta a prevalência dos quadros de meningite, selecione o agente\ncausal provável neste caso.","options":{"A":"Meningococo.","B":"Pneumococo.","C":"Enterovírus.","D":"Haemophilus influenzae.","E":"Herpesvírus."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-177513","number":"177513","sourceNumber":"177513","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Selecione a opção CORRETA quanto à medida de precaução que deve ser adotada em\numa criança com meningoencefalite.","options":{"A":"Precaução respiratória por aerossóis.","B":"Precaução respiratória por gotículas.","C":"Precaução respiratória reversa.","D":"Precaução de contato.","E":"Precaução com máscara N95."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-177493","number":"177493","sourceNumber":"177493","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"João Lucas de 2 anos de idade deu entrada na urgência com quadro de febre há 24\nhoras, vômitos (várias vezes), irritabilidade\ne apresentou quadro de crise convulsiva. Qual exame é\nnecessário de imediato para elucidar o caso?","options":{"A":"Punção lombar","B":"Tomografia de crânio","C":"Ressonância magnética","D":"Eletroencefalograma","E":"Parecer para neuropediatria e infectopediatria"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-177510","number":"177510","sourceNumber":"177510","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Maria Vitória tem 2 anos e 8 meses de idade, deu entrada no Serviço de Urgência\nPediátrico, com quadro de febre há 2 dias,\nvômitos e cefaleia. Apresentou quadro de crise\nconvulsiva. Realizado punção lombar que demonstrou leucócitos no líquor de 88 com predomínio\nlinfocítico, teste látex negativo. Tendo em conta a prevalência do quadro de Meningoencefalite,\nselecione o agente etiológico provável neste caso.","options":{"A":"Herpes Simples","B":"Pneumococo","C":"Meningococo C","D":"Meningococo B","E":"Enterovirus"},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-160381","number":"160381","sourceNumber":"160381","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Quando estiver indicada, a quimioprofilaxia da doença meningocócica poderá ser feita\npor via oral e em dose única utilizando-se qual das seguintes substâncias?","options":{"A":"Sulfametoxazol.","B":"Pirazinamida.","C":"Ciprofloxacim.","D":"Cefalexina.","E":"Doxiciclina."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-160435","number":"160435","sourceNumber":"160435","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 40 anos, sabidamente portador de HIV, apresenta-se há três dias com\nfebre alta, confusão mental e queda do estado\ngeral. No exame físico, observa-se desorientação\ntêmporo-espacial, sinais de Kernig e Brudzinski positivos, ausência de déficit motor focal e\npresença de monilíase oral. Das opções a seguir, a conduta mais apropriada é:","options":{"A":"Iniciar fenitoína dose de ataque e manutenção.","B":"Realizar punção liquórica e aguardar resultado para iniciar esquema empírico.","C":"Prescrever fluconazol/pirimetamina.","D":"Prescrever ceftriaxone, vancomicina, fluconazol e sulfa/pirimetamina.","E":"Iniciar dexametasona, ceftriaxone e aciclovir."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-160371","number":"160371","sourceNumber":"160371","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança de 3 anos apresenta queixas de cefaleia, febre, vômitos e palidez. O médico\nsuspeita de rigidez de nuca e realiza punção lombar. No liquor: proteína = 82 mg/dl; glicose = 30\nmg/dl; 550 células, com grande predomínio de neutrófilos (88%). Látex negativo para Haemophilus\ninfluenzae tipo B, Streptococcus pneumoniae e Neisseria meningitidis. Provavelmente, o\ndiagnóstico CORRETO é de:","options":{"A":"Encefalite.","B":"Abscesso cerebral.","C":"Encefalite aguda viral.","D":"Meningoencefalite bacteriana.","E":"Meningoencefalite viral."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-140030","number":"140030","sourceNumber":"140030","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente com cefaleia súbita, de forte intensidade, evoluindo com crise convulsiva,\nsonolência e rigidez de nuca. Qual o diagnóstico sindrômico mais provável e o exame\ncomplementar inicial de escolha?","options":{"A":"Tumor cerebral- ressonância nuclear magnética de crânio.","B":"Malformação artério-venosa - tomografia computadorizada de crânio com contraste.","C":"Aneurisma cerebral- angiografia digital.","D":"Hemorragia subaracnoide- tomografia computadorizada de crânio sem contraste .","E":"Estado de mal epiléptico."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-103919","number":"103919","sourceNumber":"103919","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A presença de hipoestesia focal no exame físico de um paciente automaticamente\nexclui:","options":{"A":"Esclerose múltipla.","B":"Polirradiculopatia desmielinizante inflamatória crônica.","C":"Hanseníase tuberculoide.","D":"Esclerose lateral amiotrófica.","E":"Diabetes mellitus."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-87516","number":"87516","sourceNumber":"87516","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Você está examinando um paciente diabético que abriu subitamente na noite de ontem\num quadro de retenção urinária, incontinência\nfecal, dor \"em queimação\" irradiada para membros\ninferiores e perda de força simétrica em membros inferiores, proximal e distalmente. Ao exame\nfísico, você constata hipoestesia bilateral a partir do nível da cicatriz umbilical. Sua principal\nhipótese é de:","options":{"A":"Mielite transversa aguda;","B":"Síndrome de Guillain-Barré;","C":"Polineuropatia diabética;","D":"Esclerose lateral amiotrófica;","E":"AVC talâmico."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-65594","number":"65594","sourceNumber":"65594","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"No tratamento do AVC, devemos tomar as seguinte medidas, exceto:","options":{"A":"Intervir farmacologicamente, se a PA estiver acima de 160 x 100 mmHg;","B":"Em caso de AVCH, deve-se intervir farmacologicamente somente se a PA estiver acima de 185\nx 105 mmHg ou se o paciente for candidato a\ntrombólise;","C":"A hipertermia e a hiperglicemia agravam o dano isquêmico e devem se evitadas;","D":"A trombólise é reconhecida como o único procedimento específico devidamente comprovado\npara o tratamento da fase aguda do AVC;","E":"Não há recomendação para o uso de heparina de baixo peso molecular com finalidade de\ntratamento do AVC."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-65617","number":"65617","sourceNumber":"65617","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Podemos afirmar sobre a hemorragia subaracnoide espontânea (HSAe), exceto:","options":{"A":"Em 85% dos casos de HSAe a causa é a ruptura de um aneurisma sacular;","B":"A TC de crânio é o primeiro exame diagnóstico diante da suspeita de HSAe, podendo ser\ndetectada em 95% dos doentes no primeiro dia;","C":"Os principais objetivos do tratamento são otimizar a oferta cerebral de oxigênio e prevenir o\nressangramento e o vasoespasmo cerebral;","D":"A principal causa de hiponatremia na HSA é a síndrome perdedora de sal;","E":"O pico de incidência de vasoespasmo é entre o 1º e o 3º dia após o sangramento."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-52160","number":"52160","sourceNumber":"52160","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 71 anos, portadora de hipertensão arterial, dislipidemia mista e diabética deu\nentrada em serviço de emergência médica com quadro de hemiparesia direita proporcionada e\nafasia de expressão de inicio há 180 minutos, pressão arterial 170x100, glicemia capilar 180 mg/dl\ne exames de admissão com leucocitose sem desvio, plaquetas de 99.000, creatinina de 1,4.\n\nAssinale a alternativa correta.","options":{"A":"Existem condições para realizar trobólise intravenosa com rTpa.","B":"Uso de medicação endovenosa para controle da pressão arterial está indicado.","C":"O exame padrão-ouro para diagnóstico do acidente vascular isquêmico. Neste caso é a\ntomografia computadorizada de crânio.","D":"A lesão tem que ser encontrada no lobo frontal esquerdo.","E":"Não existe indicação de realizar teste de glicemia, pois o quadro é sugestivo de acidente\nvascular cerebral."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-362849","number":"362849","sourceNumber":"362849","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Adolescente de 12 anos é levada à emergência por cefaleia intensa, vômitos em jato há\num dia e febre (38,5°C), sem melhora mesmo\ncom o uso de antitérmico. Ao exame físico\n\napresenta-se febril, com rigidez de nuca, sonolência, mucosas secas e hipocoradas. Resultado do\nlíquor por Punção lombar: pleocitose, com 478 células/mm3, 25.000 hemácias/mm3, com\npredomínio de linfomononucleares; proteína: 49mg/dL; glicorraquia: 62 mg dL (glicemia: 88 mg/dL\nno momento da punção). Esse quadro clínico sugere:","options":{"A":"meningite viral.","B":"meningite bacteriana.","C":"trauma de punção.","D":"aneurisma cerebral roto"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-346626","number":"346626","sourceNumber":"346626","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A encefalite herpética costuma acometer, preferencialmente:","options":{"A":"O lobo occipital","B":"O lobo temporal","C":"O verme cerebelar","D":"Os hemisférios cerebelares"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-330846","number":"330846","sourceNumber":"330846","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo masculino, 32 anos, previamente hígido, apresentou quadro de\nmeningite bacteriana. Assinale a alternativa que apresenta corretamente o achado liquórico e o\ntratamento.","options":{"A":"Liquor com grande aumento da celularidade, às custas de polimorfonucleares, aumento das\nproteínas e diminuição da glicose. O antimicrobiano recomendado é a ceftriaxona endovenosa.","B":"Liquor com grande aumento da celularidade, às custas de polimorfonucleares, aumento das\nproteínas e diminuição da glicose. O antimicrobiano recomendado é a piperacilina/tazobactam.","C":"Liquor com grande aumento da celularidade, às custas de linfomononucleares, aumento das\nproteínas e diminuição da glicose. O antimicrobiano recomendado é a ceftriaxona.","D":"Liquor com celularidade normal, proteínas normais e sem diminuição da glicose. O\nantimicrobiano recomendado é a azitromicina."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-327361","number":"327361","sourceNumber":"327361","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma das queixas mais frequentes nas consultas nas UBS é cefaleia, que pode ter\ncomo causas desde condições muito benignas até\npotencialmente ameaçadoras à vida do\npaciente. Na abordagem inicial das cefaleias, é importante saber identificar sinais de alarme que\nsugerem uma causa secundária de maior gravidade. Quais sinais de alarme para cefaleia\nsecundária?","options":{"A":"Rigidez de nuca e fotofobia.","B":"Início após os 50 anos e imunossupressão (HIV ou uso de corticoides).","C":"Exantema e pródromos.","D":"Imunossupressão (HIV ou uso de corticoides) e fotofobia."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-313418","number":"313418","sourceNumber":"313418","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 35 anos, com quadro de pelo menos 3 crises mensais de cefaleia unilateral,\npulsátil, de forte intensidade, com duração\nmaior que 4 horas e associada com náuseas, fonofobia\ne fotofobia. Diante da principal hipótese diagnóstica, qual seria, respectivamente, uma estratégia\npara tratamento abortivo e preventivo de tais crises?","options":{"A":"Pizotifeno e clorpromazina;","B":"Anti-inflamatórios e corticóides;","C":"Ergotamínicos e anticonvulsivantes;","D":"Triptanos e inibidores seletivos da receptação da serotonina."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-267283","number":"267283","sourceNumber":"267283","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem, 76 anos, é trazido ao serviço de urgência pela esposa porque ele tem sido\nincapaz de mover o braço e perna esquerdos desde que acordou, há uma hora. Duas semanas\nantes, tinha tido alta hospitalar após o tratamento de celulite da extremidade inferior direita com\nantibióticos intravenosos. A história médica relevante inclui febre reumática aos 12 anos de idade,\nsubstituição valvular mitral aos 71 anos de idade, diabetes mellitus tipo 2 e hipertensão arterial.\n\nEstá medicado com varfarina, metformina, amiodipina e ranitidina. Os sinais vitais são temperatura\n39,4°C, frequência cardíaca 110/min, frequência\nrespiratória 28/min e pressão arterial 160/100\nmmHg. O doente está desidratado e confuso, mas cooperante. A auscultação do tórax revela\ncrepitações basais bilaterais. O exame cardíaco revela sopro sistólico de grau 4/6, que se ouve\nmelhor ao longo do bordo esquerdo do esterno. O exame físico revela edema dos tornozelos e\nsinais de celulite em resolução na perna direita. O exame neurológico revela desvio do olhar para a\ndireita. Há fraqueza muscular e diminuição dos reflexos osteotendinosos nos membros esquerdos.\nO sinal de Babinski está presente à esquerda. Qual é o diagnóstico mais provável?","options":{"A":"Abcesso cerebral","B":"Enfarte lacunar da cápsula interna","C":"Hematoma subdural","D":"Hemorragia subaracnoidea"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-258911","number":"258911","sourceNumber":"258911","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 51 anos, chega ao pronto atendimento com queixa de cefaleia forte, início\nabrupto, que já dura 10h, dor difusa e\nlatejante, piora com exposição ao sol, nega febre, vômitos,\nalterações visuais ou fraqueza. Nega história prévia de dor tão forte, nega tabagismo, uso ou abuso\nde álcool ou drogas. História familiar sem relevância. Ao exame físico, PA: 136/72; T.Ax: 36.9ºC;\nFC: 88 bpm; FR: 16 irpm e apresenta incômodo ao fletir pescoço. Exame neurológico normal. Qual\no provável diagnóstico e conduta inicial?","options":{"A":"Crise de enxaqueca sem aura; em função do tipo de dor, intensidade, duração e ausência de\nsinais neurológicos focais. Iniciar medicação abortiva de crises de enxaqueca.","B":"Cefaleia secundária; devido à faixa etária, presença de sinal neurológico focal, início súbito,\ndor\nintensa e inexistência de cefaleia prévia são sinais de alerta. Solicitar exame de imagem.","C":"Meningite; por apresentar rigidez de nuca, pela faixa etária, paciente pode não apresentar febre\ne tipo de dor difusa. Punção lombar e\niniciar antibioticoterapia empiricamente.","D":"Cefaleia em salva, pois paciente mulher é mais comum, início abrupto, duração e intensidade da\ndor e presença de fotofobia. Uso de oxigenioterapia nasal ? O? a 100% 6 L/min e analgesia\nvenosa."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-258942","number":"258942","sourceNumber":"258942","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Adolescente, 15 anos, previamente saudável, foi levado pela assistente social à UPA\ncom história de 2 dias de cefaleia forte que\nnão melhora com analgésicos, refere náuseas, tontura,\nfebre e visão turva. Relata viver em situação de rua, já fez uso de bebidas alcoólicas, crack e\nmaconha, nega drogas injetáveis. Não sabe de sua situação vacinal. Exame físico: febril (38,9º C);\nFC: 110 bpm; PA: 120 x 80 mmHg; FR 18 irm; Sat: 98%. Ex. Neurológico: Glasgow 15; sinal de\nKernig positivo; Brudzinski positivo; Lasegue negativo. Exames laboratoriais: Hemograma: GV: 4,08\nmilhões; Hb: 13,2%; Ht: 39%; plaquetas 294.000 mm³ ; GB: 21.800, com diferencial de 89% de\nneutrófilos e 6% de linfócitos; M: 0; E: 0; B:0. Proteína C reativa de 28,74 mg/dL (normal: até 0,5\nmg/dL); Lactato: 3,4 (normal: 0,5-2,0 mmol/L) e hemocultura negativa. Glicemia: 120 mg (normal 65\na 99 mg/dL). Sorologia pra HIV negativa. Foi realizada punção lombar e a análise do líquido\ncefalorraquidiano (LCR) revelou cor turva, com contagem total de leucócitos de 268 mm³ (91%\nneutrófilos e 9% linfócitos), glicose 28 mg/dL (45 a 100 mg/dL) e proteína total 720 mg/dL (15 a 50\nmg/dL). Coloração de Gram: Diplococos Gram negativos. Cultura ainda sem resultado. Tinta da\nchina: negativo. Qual a principal hipótese diagnóstica e o agente causal?","options":{"A":"Encefalite causada por H. influenzae.","B":"Encefalite causada por Escherichia coli.","C":"Meningite causada por S. pneumoniae.","D":"Meningite causada por N. meningitidis."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-247694","number":"247694","sourceNumber":"247694","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança de cinco anos dá entrada no pronto atendimento com queixa de cefaleia há\ndois dias, associada à febre e rigidez de\nnuca, com histórico de rinorreia há cerca de uma semana.\nO pediatra suspeita de meningoencefalite bacteriana e opta por realizar exames laboratoriais,\nincluindo líquor. Diante dos resultados, o pediatra conclui que se trata de uma meningite causada\npor Streptococcus pneumoniae. Com base neste enunciado, marque a afirmativa correta.","options":{"A":"Trata-se de doença de notificação compulsória, devendo ser tratada com internação,\nantibioticoterapia venosa e isolamento protetor.","B":"A doença em questão é de alta transmissibilidade e deve ser instituída quimioprofilaxia para os\ncontactantes mais íntimos imediatamente.","C":"O líquor se apresenta com bacterioscopia positiva às custas de diplococos gram negativos,\ncelularidade aumentada às custas de\npolimorfonucleares, glicose reduzida e hiperproteinorraquia.","D":"O líquor se apresenta com bacterioscopia positiva às custas de diplococos gram positivos, com\ncelularidade aumentada às custas de polimorfonucleares, glicose baixa e hiperproteinorraquia."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-221107","number":"221107","sourceNumber":"221107","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"R.S.A., 26 anos, sexo masculino, solteiro, estudante de direito, natural e procedente de\nCuiabá (MT). Previamente hígido, sem quaisquer comorbidades, bem como ausência de\nantecedente familiar de doença mental. História de cefaleia há 7 dias, de forte intensidade e\nprimeira crise convulsiva do tipo generalizada tônico clônica há 5 dias, evoluindo com quadro de\nconfusão e distúrbio comportamental flutuante. Ontem apresentou nova crise convulsiva, 3 crises\nnas últimas 12 horas. Deu entrada no HUJM com agitação psicomotora e desorganização do\ncomportamento. Resultado de hemograma com linfocitose e TC de Crânio normal, RNM de crânio\ncom contraste: Hipersinal em lobo temporal e córtex da ínsula à esquerda. De acordo com o caso\nclínico, marque V para as afirmativas verdadeiras e F para as falsas. ( ) Hipótese diagnóstica\nprincipal é epilepsia por esclerose mesial de lobo temporal, EEG deve ser solicitado assim como\niniciar uso de fenobarbital regular e encaminhar paciente para o neurologista. ( ) A aplicação de\nPCR para detecção de DNA viral no LCR forneceu o padrão ouro para o diagnóstico de encefalite\npor herpes simplex, sendo a primeira hipótese diagnóstica. ( ) Dengue é a arbovirose mais\nprevalente nas Américas, endêmica em quase todos os países tropicais/subtropicais e deve fazer\nparte da suspeita clínica a arbovirose neuroinvasiva. ( ) Conduta sequencial é submeter paciente à\ncoleta de LCR, RNM de crânio com espectroscopia para definição do diagnóstico de abcesso\ncerebral e iniciar antibioticoterapia de amplo espectro. Assinale a sequência correta.","options":{"A":"F, V, V, F","B":"F, V, F, V","C":"V, F, V, F","D":"V, F, F, V"},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-214599","number":"214599","sourceNumber":"214599","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente jovem, sexo masculino, 28 anos, apresentando há três dias cefaleia\nholocraniana, astenia, mal-estar, febre e\nhiporexia. Há um dia, evoluiu com vômitos e prostração.\nNega outras queixas. Ao exame físico: PA = 100 x 50 mmHg; FC = 120 bpm; FR = 28 irpm; T =\n38,5°C. Regular estado geral, acianótico, anictérico, taquidispneia leve, sonolento, desidratado\n1+/4+, hipocorado 1+/4+. RCR, 2T, BNF, sem sopro. MV levemente diminuído, sem RA. Abdome\nplano, RHA+, timpanismo, indolor e sem visceromegalias. Assinale a alternativa que apresenta a\nprincipal hipótese diagnóstica e a conduta adequada.","options":{"A":"Meningite bacteriana; suporte clínico, corticoterapia, cefepima.","B":"Sepse devido à sinusite aguda; suporte clínico, amoxicilina + clavulanato.","C":"Meningite bacteriana; suporte clínico, corticoterapia, ceftriaxona.","D":"Meningite viral; suporte clínico e corticoterapia."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-208574","number":"208574","sourceNumber":"208574","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma mulher de 64 anos apresenta, há 1 dia, cefaleia, rigidez de nuca e febre. Uma\npunção lombar é realizada, com os seguintes\nresultados no liquor: leucócitos = 7.000, com 90% de\nneutrófilos, proteína = 150mg/dL e glicose = 23mg/dL. O Gram revela diplococos Gram prositivos.\nQual é a antibiótico de escolha neste momento?","options":{"A":"ceftriaxona","B":"ceftriaxona e vancomicina","C":"penicilina G","D":"penicilina G e ceftriaxona","E":"cefalotina"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-214590","number":"214590","sourceNumber":"214590","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente masculino, 38 anos, procura unidade de pronto atendimento por piora\nimportante de cefaleia. Doze dias antes,\nsofreu uma picada de mosquito em face, em região malar\nà esquerda, com eritema local. Apresentou edema periorbital ipsilateral no dia seguinte. Alguns dias\ndepois, iniciou cefaleia frontal e retro-orbital, porém de intensidade progressiva, além de ter\npercebido diplopia há um dia. Apresenta FC = 108 bpm; PA = 120 x 70 mmHg; FR = 22 irpm; TAX\n\n= 38,4°C. Ao exame físico: toxemiado, eritema, edema de face à esquerda e edema periorbital\nbilateral. Palpação da região malar e frontal\nmuito dolorida. Apresenta oftalmoplegia bilateral e\nfundoscopia com papiledema. Qual é a hipótese diagnóstica?","options":{"A":"Acidente vascular encefálico hemorrágico.","B":"Abscesso epidural.","C":"Encefalite viral por arbovírus.","D":"Trombose séptica do seio cavernoso."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-181119","number":"181119","sourceNumber":"181119","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 35 anos, com quadro de pelo menos 3 crises mensais de cefaleia unilateral,\npulsátil, de forte intensidade, com duração\nmaior que 4 horas e associada com náuseas, fonofobia\ne fotofobia. Diante da principal hipótese diagnóstica, qual seria, respectivamente, uma estratégia\npara tratamento abortivo e preventivo de tais crises?","options":{"A":"Pizotifeno e clorpromazina;","B":"Anti-inflamatórios e corticoides;","C":"Ergotamínicos e anticonvulsivantes;","D":"Triptanos e inibidores seletivos da receptação da serotonina."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-181560","number":"181560","sourceNumber":"181560","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Um menino de 13 anos com história de febre e letargia há 1 dia foi trazido ao setor de\nemergência. Verifica-se que sua frequência respiratória é 7 irpm, frequência cardíaca 55 bpm,\ntemperatura 40o C e pressão arterial 60/40mmHg. Seu nível de sensório está rebaixado e ele\napresenta rigidez de nuca e exantema purpúreo no tronco. Qual é o primeiro procedimento a ser\nrealizado de imediato?","options":{"A":"Realizar tomografia de crânio","B":"Antibiótico intravenosos","C":"Punção lombar","D":"Intubação traqueal para ventilação"},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-159425","number":"159425","sourceNumber":"159425","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em idosos enfermos, o fator de risco cujo controle é mais importante para a prevenção\ndo acidente vascular encefálico (AVE) é:","options":{"A":"Tabagismo.","B":"Dislipidemia.","C":"Sedentarismo.","D":"Hipertensão Arterial Sistêmica."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-158071","number":"158071","sourceNumber":"158071","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Escolar de 7 anos é levado ao pronto atendimento com queixa de 24 horas de febre,\nvômitos e cefaleia holocraniana. Ao exame\nfísico, foram constatadas sonolência e rigidez de nuca.\nO liquor apresentou 500 leucócitos com predomínio de polimorfonucleares (90%), glicose de 25\nmg/dl e proteínas de 180 mg/dl. Qual o provável agente etiológico, com seu respectivo tratamento?","options":{"A":"Haemophilus influenzae b; gentamicina.","B":"Staphylococcus aureus; penicilina cristalina.","C":"Neisseria meningitidis; penicilina cristalina.","D":"Mycobacterium tuberculosis; rifampicina, isoniazida e pirazinamida."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-137014","number":"137014","sourceNumber":"137014","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 62 anos trazida pelo SAMU ao PS, apo?s queda da pro?pria altura no caixa\neletrônico há 45 min. Ao exame físico, estava lu?cida, hemiple?gica a? esquerda, ritmo de pulso\nirregular. TC sem contraste demonstra leve indefinição dos nu?cleos da base a? direita, sem outras\nanormalidades. Qual o diagno?stico provável e a conduta a ser primeiramente instituída nesse\ncaso?","options":{"A":"Convulsão sintomática seguida de paralisia de Todd; fazer TC com contraste ou RNM para\ndescartar glioma infiltrativo e administrar hidantal endovenoso.","B":"AVC isquêmico agudo embólico; considerar protocolo para trombólise.","C":"AVC hemorrágico agudo; considerar drenagem cirúrgica.","D":"AVC isquêmico agudo; considerar uso de AAS ou Clopidogrel."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-137013","number":"137013","sourceNumber":"137013","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem de 75 anos, com histo?ria de vertigens recorrentes e zumbidos há mais de 1\nano, passou a apresentar dificuldade em\ndeambular há seis meses. Vem ao consulto?rio com apoio\npara marcha, com face inexpressiva e fala lentificada. Ao exame físico, identificada rigidez\nsimétrica\nnos 4 membros, humor depressivo, porém cognição preservada. Que informação da anamnese\npode ser mais esclarecedora sobre a etiologia desse quadro?","options":{"A":"Medicações utilizadas nos últimos meses.","B":"História de familiares com o mesmo problema.","C":"Fatores de risco para doença vascular aterosclerótica.","D":"Patologias que possam fazer compressão medular."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-108112","number":"108112","sourceNumber":"108112","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Durante a visita na UTI, o intensivista responsável pela rotina da unidade examinou um\npaciente recém-internado em estado grave, intubado em ventilação mecânica devido a quadro\nneurológico de tetraplegia ascendente flácida de início súbito, arreflexia, apresenta picos\nhipertensivos e arritmias cardíacas frequentes ao monitor. Segundo sua esposa, seu marido era\nextremamente saudável, lembra apenas de um quadro febril há cerca de duas semanas, mas sem\noutras características importantes. O plantonista solicitou tomografia de crânio e coluna com\nresultados normais. Qual a possível hipótese diagnóstica?","options":{"A":"Síndrome de Guillain-Barré.","B":"Esclerose múltipla.","C":"AVC isquêmico.","D":"Síndrome de Eaton-Lambert."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-98053","number":"98053","sourceNumber":"98053","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Lactente de cinco meses de idade, sabidamente hígido, é trazido ao Pronto-Socorro\ncom quadro de febre alta (39,5°C), há dois\ndias, sem causa aparente. Durante o trajeto de sua casa\naté o Pronto-Socorro, apresentou convulsão. Ao exame, encontra-se: letárgico com irritabilidade ao\nmanuseio, toxemiado e sem outra alteração. Esse quadro levanta suspeita de qual patologia e que\nexame deve ser solicitado para elucidar o diagnóstico?","options":{"A":"Meningite; Punção liquórica.","B":"Pneumonia; Radiografia de tórax.","C":"Septicemia; Hemograma.","D":"Choque séptico; Gasometria."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-332993","number":"332993","sourceNumber":"332993","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 30 anos, obesa, história prévia de asma brônquica com controle irregular,\nprocura atendimento por quadro de episódios de\ncefaleia, 1 a 2 vezes por semana, de forte\nintensidade, hemicrania direita, latejante, com náuseas e fotofobia associadas, com 12 a 24 horas\nde duração, aliviados com o uso de paracetamol e ibuprofeno associados. As crises têm sido mais\nfrequentes nos últimos meses e que, em algumas situações, a medicação não consegue aliviar\ncompletamente o quadro. Nesse contexto, a medicação indicada como tratamento e ação\npreventiva é:","options":{"A":"Amitriptilina.","B":"Propranolol.","C":"Topiramato.","D":"Paracetamol em uso contínuo."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-286131","number":"286131","sourceNumber":"286131","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"A quimioprofilaxia com rifampicina é indicada para os contatos íntimos de pacientes\ncom diagnóstico de meningite por:","options":{"A":"Streptococcus pneumoniae e Neisseria meningitidis.","B":"Streptococcus pneumoniae e Mycobacterium tuberculosis.","C":"Mycobacterium tuberculosis e Haemophilus influenzae tipo B.","D":"Neisseria meningitidis e Haemophilus influenzae tipo B.","E":"Streptococcus pneumoniae e Haemophilus influenzae tipo B."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-284211","number":"284211","sourceNumber":"284211","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"As meningites virais têm distribuição universal. Podem ocorrer casos isolados e surtos\nprincipalmente relacionados aos enterovírus. A frequência de casos se eleva nos meses do outono\ne da primavera. Sendo correto o item:","options":{"A":"O aumento de casos nunca pode estar relacionado a epidemias de varicela, sarampo, caxumba\ne também a eventos adversos pós-vacinais.","B":"O aumento de casos pode estar relacionado a epidemias de varicela, sarampo, caxumba e não\na eventos adversos pós-vacinais.","C":"O aumento de casos pode estar relacionado a epidemias de varicela, sarampo, caxumba e\ntambém a eventos adversos pós-vacinais.","D":"O aumento de casos pode estar relacionado a epidemias de varicela, sarampo, caxumba e\ntambém a eventos adversos pré-vacinais."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-274979","number":"274979","sourceNumber":"274979","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança, 2 anos, 15 kg, sexo masculino, trazida ao pronto-atendimento em crise\nconvulsiva com duração de 10 minutos, foi\nmedicada com diazepam 2x com resolução da crise. Ao\nexame: REG, corado, hidratado, acianótico, anictérico. Temperatura: 36,9 °C. Glasgow 14, pupilas\nisocóricas e fotorreagentes, sem sinais de irritação meníngea, sem déficits motores. Oroscopia e\notoscopia normais. AP: murmúrio vesicular presente, sem ruídos adventícios. ACV: RCR 2T sem\nsopro. Abdome: flácido, indolor, sem massas ou visceromegalias, RHA +. Pulsos +, perfusão 2\nsegundos. Exames laboratoriais: Hb 12 / Ht 37 / Leuco: 8500 sem desvio / Plaquetas: 200 mil. PCR\n4 (valor de referência 5). Na= 140. K= 4,9. Ca= 10. Mg= 2,0. Gasometria arterial: pH 7,401 / pCO?=\n41 / pO?= 98 / Bic= 23 / BE= 0,2 / Sat= 99% / Lactato= 1,0. Com adição aos dados, observe o TC\nde crânio sem contraste. Qual o provável diagnóstico?","options":{"A":"Crise convulsiva febril.","B":"Hidrocefalia.","C":"Acidente vascular encefálico isquêmico.","D":"Meningite.","E":"Tumor."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-14/274979.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-220236","number":"220236","sourceNumber":"220236","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher, 40 anos, moradora de rua, trazida pelo SAMU após crise convulsiva\npresenciada em via pública. Admitida com Glasgow\n13, sonolenta, confusa, pupilas\nisofotorreagentes, desidratada 2+/4+, temperatura de 38°C e ao fletir a cabeça apresentou um\nlevantamento involuntário das pernas. PA = 100 x 80 mmHg. FC = 111 bpm. A conduta inicial é:","options":{"A":"Punção liquórica e antibioticoterapia empírica com vancomicina.","B":"Tomografia computadorizada de crânio, punção liquórica e antibioticoterapia empírica com\nceftriaxona.","C":"Tomografia computadorizada de crânio, punção liquórica e antibioticoterapia empírica com\nvancomicina.","D":"Hidantalização com fenobarbital, punção liquórica e antibioticoterapia empírica com ceftriaxone."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-177134","number":"177134","sourceNumber":"177134","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Dona Márcia traz sua filha, Clara, de 10 anos, ao ambulatório, com queixa de cefaleia\nfrontal há aproximadamente 3 anos. Informa\nque as crises não têm horário preferencial, são\nassociadas a náuseas e palidez labial e duram cerca de 1 hora. Dona Márcia relata que percebeu\nque as crises pioram em períodos de provas escolares e quando Clara fica muito tempo assistindo\nTV. Diante de crianças com quadro semelhante ao de Clara, assinale a alternativa correta:","options":{"A":"a avaliação da acuidade visual está indicada em toda criança com queixa de cefaleia.","B":"a duração da dor por períodos menores de 2 horas afasta o diagnóstico de enxaqueca","C":"radiografia dos seios da face, fazem parte da triagem diagnóstica dessas crianças","D":"o diagnóstico de enxaqueca é muito raro em crianças com menos de 8 anos de idade"},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-183431","number":"183431","sourceNumber":"183431","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre a cefaleia por uso excessivo de medicamentos, é correto afirmar que","options":{"A":"é uma cefaleia rara, encontrada com mais frequência em associação com outras cefaleias\nsecundárias.","B":"ante ao diagnóstico nunca se deve orientar a suspensão abrupta do fármaco em abuso, uma vez\nque isso pode gerar uma grave síndrome de\nabstinência.","C":"a psicoeducação e a retirada da medicação usada em excesso são pilares importantes no\ntratamento.","D":"o uso recorrente de combinações de analgésicos, com ácido acetilsalicílico, cafeína e\nparacetamol, minimiza o risco desse tipo de cefaleia.","E":"não existe esse tipo de cefaleia secundária."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-156238","number":"156238","sourceNumber":"156238","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 25 anos com antecedente hígido, há dois dias apresenta febre aferida de\n39-40°C, com calafrios e mialgia difusa. Nas últimas 24 horas, houve significativa queda de estado\ngeral. Ao exame, observam-se petéquias subconjuntivais e algumas esparsas nos membros\ninferiores e na cintura. Não há rigidez de nuca. Considere também os seguintes dados:\n(CONFORME IMAGEM NO CADERNO DE QUESTÕES). A hipótese diagnótica é de","options":{"A":"Meningococcemia.","B":"Púrpura Trombocitopênica Imune.","C":"Leucemia Aguda.","D":"Dengue Hemorrágica.","E":"Púrpura Trombocitopênica Trombótica."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-152299","number":"152299","sourceNumber":"152299","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em uma criança com quadro clínico compatível com meningoencefalite viral, qual dos\nseguintes elementos é o MAIS relevante para decidir sobre o tratamento com aciclovir?","options":{"A":"Tomografia computadorizada de crânio.","B":"PCR positivo para Vírus Herpes simples no LCR.","C":"Contato familiar.","D":"Sinais clínicos e/ou laboratorias sugestivos e relevantes de encefalite herpética."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-156274","number":"156274","sourceNumber":"156274","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Entre os fatores comprovadamente associados a quadros de cefaleia, constam: I.\nSobrepeso; II. Sedentarismo; III. Tabagismo; IV. Uso de telefones celulares; Quais estão corretas?","options":{"A":"Apenas I, II e III.","B":"Apenas I, II e IV.","C":"Apenas I, III e IV.","D":"Apenas II, III e IV,","E":"Todas."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-151015","number":"151015","sourceNumber":"151015","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Criança de 5 anos chega ao pronto atendimento com história de 10 horas de febre e\ncefaleia. Há 5 horas passou apresentar vômitos em jato e apatia. Ao exame físico encontra-se\nsonolenta, febril, taquicárdica, perfusão periférica diminuída, rigidez de nuca e com sufusões\nhemorrágicas no tronco. Qual é a conduta imediata recomendada para esse caso?","options":{"A":"Encaminhar a criança para internação em UTI.","B":"Administrar antitérmico e antibiótico e aguardar vaga na enfermaria para internação.","C":"Encaminhar para a coleta de liquor para definir a terapêutica mais adequada.","D":"Obter acesso venoso, iniciar expansão de volume e antibioticoterapia parenteral."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-133819","number":"133819","sourceNumber":"133819","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente feminina, 40 anos de idade, deu entrada no hospital após acidente\nmotociclístico, com grave traumatismo\ncranioencefálico. Foram iniciadas diversas medidas durante\nessa emergência. Para clinicamente controlar a hipertensão intracraniana, podemos propor, após\nadequadamente monitorizada,","options":{"A":"Posicionamento da cabeça.","B":"Controle da PO2.","C":"Nimodipina.","D":"Hipertensão induzida."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-133844","number":"133844","sourceNumber":"133844","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Quando do insulto primário do infarto cerebral, ocorre uma importante tendência na\nmaioria dos acometidos de Acidente Vascular Cerebral Isquêmico de aumento dos níveis de\npressão arterial, principalmente nos primeiros dias após a lesão. A necessidade de tolerância de\naumento da Pressão Arterial deve-se","options":{"A":"A não necessidade de tratar por normalização espontânea.","B":"Ao aumento do risco de transformação hemorrágica.","C":"Evitar aumento da área de insulto secundário.","D":"Evitar outras complicações à distância."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-138041","number":"138041","sourceNumber":"138041","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Mulher de 52 anos deu entrada em um serviço de emergência com história de cefaleia\nsúbita intensa seguida de perda de consciência.\nAo exame, apresentava-se com pressão arterial de\n200/120 mmHg, frequência cardíaca de 90 batimentos por minuto, frequência respiratória de 18\nincursões respiratórias por minuto, escala de coma de Glasgow 9 e rigidez de nuca. Qual o primeiro\nexame a ser pedido para confirmar o diagnóstico do caso?","options":{"A":"Tomografia computadorizada de crânio com contraste.","B":"Tomografia computadorizada de crânio sem contraste.","C":"Punção lombar para análise do líquor.","D":"Angiotomografia de vasos intracranianos.","E":"Ressonância magnética de crânio com contraste."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-138007","number":"138007","sourceNumber":"138007","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Entre os efeitos adversos no tratamento farmacológico das vertigens, observam-se\ntremores tipo parkinsonismo com uso por tempo\nprolongado dos seguintes fármacos:","options":{"A":"Betaistina e pentoxifilina.","B":"Flunarizina e cinarizina.","C":"Clonazepam e diazepam.","D":"Meclizina e dimenidrinato.","E":"Ginkgo biloba e ondansetrona."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-132247","number":"132247","sourceNumber":"132247","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Homem, 35 anos, com quadro progressivo de perda da força iniciada em perna direita,\nseguida de perda de força em perna esquerda associada a anestesia em ambas as pernas, com\nascensão até nível de D10 bilateralmente, e incontinência urinária e fecal. Tal progressão ocorreu\nnum prazo de 24 horas. Qual a topografia da lesão:","options":{"A":"Tronco encefálico - ponte.","B":"Tronco encefálico - bulbo.","C":"Sistema nervoso periférico - nervos e raízes.","D":"Sistema nervoso central - medula ao nível D10."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-138013","number":"138013","sourceNumber":"138013","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"As seguintes condições são causas comuns de síndrome demencial reversível, exceto","options":{"A":"Corpúsculos de Lewy.","B":"Depressão.","C":"Hipovitaminose B12.","D":"Hipotireoidismo.","E":"Neurossífilis."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-132272","number":"132272","sourceNumber":"132272","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 68 anos com quadro de dificuldade de marcha há 01 ano, com piora\nlentamente progressiva, evoluindo após 8 meses com\nurgência miccional e déficit de memória\nrecente. Na avaliação neurológica apresentava quadro de síndrome parkinsoniana bilateral e déficit\nde memória recente. Sem déficit de força ou sensibilidade, ou alteração de pares cranianos, exceto\npela lentidão das sácades do olhar. Qual o diagnóstico mais provável e tratamento indicado?","options":{"A":"Demência de Alzheimer em estágio avançado - anticolinesterásicos.","B":"Demência por corpos de Lewy - anticolinesterásicos.","C":"Hidrocefalia de pressão normal - derivação ventriculoperitoneal.","D":"Demência frontotemporal - anticolinesterásicos."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-132278","number":"132278","sourceNumber":"132278","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual teste abaixo não faz parte das provas de comprovação de morte encefálica:","options":{"A":"Reflexo pupilar - avaliação do diâmetro pupilar e fotomotor direto.","B":"Reflexo córneo-palpebral.","C":"Reflexo óculo-cefálico.","D":"Reflexo cílio espinhal."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-111786","number":"111786","sourceNumber":"111786","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Uma mulher, 68 anos, sem comorbidades prévias conhecidas, começou a apresentar,\nsubitamente, hemiplegia direita. É trazida à emergência por seu esposo, 30 minutos após o início\ndo quadro neurológico. Ao exame: paciente vígil; consciente; PA: 170 x 100 mmHg; hemiplégica à\ndireita e afásica. Exames laboratoriais normais e TC de crânio sem contraste: sem anormalidades.\nDiante do caso, assinale a conduta terapêutica CORRETA:","options":{"A":"Início imediato de anti-hipertensivo e do AAS após 48 horas.","B":"Controle rigoroso da pressão arterial com medicação intravenosa e heparinização plena.","C":"Repouso, monitorização não invasiva da pressão arterial de 15/15 minutos e início de trombólise\ncom rt-PA (alteplase).","D":"Monitorização invasiva da pressão arterial e início de anti-hipertensivo intravenoso.","E":"Repouso e monitorização neurológica intensiva."},"answer":"C","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-106974","number":"106974","sourceNumber":"106974","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Atualmente, a escala neurológica mais utilizada para avaliação neurológica é a Escala\nde Coma de Glasgow, pois ela se mostra\nadequada à avaliação de Traumatismo Craniano. Dessa\nforma, podemos considerar INADEQUADO.","options":{"A":"Definir necessidade de manobras de reanimação cardiorrespiratória.","B":"Definir necessidade de manejo de vias aéreas.","C":"Indicar a incapacidade de proteção de via aérea por parte do paciente.","D":"Indicar gravidade do traumatismo craniano."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-106839","number":"106839","sourceNumber":"106839","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Qual demência tem evolução rapidamente progressiva:","options":{"A":"Alzheimer.","B":"Demência de Pick.","C":"Demência semântica.","D":"Creutzfeldt Jacob.","E":"Demência vascular."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-60210","number":"60210","sourceNumber":"60210","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente do sexo masculino, 30 anos, com quadro de cefaleia com a seguinte\nsemiologia: supraorbitária à direita, muito intensa,\ndurando 40 minutos, associado à hiperemia\nconjuntival; lacrimejamento; congestão nasal; miose e ptose (ipsilaterais); 3 crises ao dia há 2\nmeses. É o quinto episódio (3 em 2008 e 2 em 2010). Com base nestas informações, a melhor\nhipótese diagnóstica para o caso é:","options":{"A":"Migrânea com aura.","B":"Migrânea sem aura.","C":"Hemicrania paroxística crônica.","D":"Hemicrania paroxística episódica.","E":"Cefaleia em salvas episódica."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-64954","number":"64954","sourceNumber":"64954","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente de 50 anos, com quadro de tetraparesia crônica progressiva, atrofia muscular,\nfasciculações nas quatro extremidades, hiper-reflexia nas quatro extremidades, sinal de Babinski\nbilateral, reflexo massetérico aumentado, atrofia de língua bilateral, fasciculações de língua,\ndisfagia e disartrofonia. Qual é a hipótese diagnóstica e a conduta adequada, respectivamente?","options":{"A":"Esclerose lateral amiotrófica, e ressonância magnética nuclear craniana e eletroneuromiografia.","B":"Mononeuroterapia motora múltipla com bloqueio de condução e eletroneuromiografia.","C":"Esclerose múltipla, e exame de liquor e ressonância magnética nuclear craniana.","D":"Paralisia pseudobulbar e ressonância magnética nuclear craniana.","E":"Mielopatia cervical, e exame de liquor e ressonância magnética nuclear craniana."},"answer":"A","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-45877","number":"45877","sourceNumber":"45877","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Em relação à doença de Alzheimer, assinale a alternativa correta:","options":{"A":"O diagnóstico é confirmado por achados característicos na Ressonância nuclear magnética,\ncomo a atrofia hipocampal.","B":"No diagnóstico histopatológico, quando possível, é característica a presença de peptídeo\na-amiloide no córtex frontal.","C":"O elemento chave na história clínica dos pacientes é a progressão rápida de comprometimento\ncognitivo.","D":"A imensa maioria dos casos da doença de Alzheimer é devido à doença esporádica (não\ngenética).","E":"Entre todos os indivíduos com mais de 65 anos, a prevalência da doença de Alzheimer é\nestimada em cerca de 18%."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-45521","number":"45521","sourceNumber":"45521","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre a avaliação semiológica do II, III, IV e VI nervos cranianos, assinale a\nalternativa\ncorreta.","options":{"A":"As fibras parassimpáticas no terceiro nervo craniano têm disposição central no nervo e vasculite\ndo vaso nervorum desse nervo dilatam a pupila.","B":"Lesão compressivas do terceiro nervo craniano alteram, primeiramente, a Motricidade Ocular\nExtrínseca (MOE).","C":"O VI nervo craniano inerva o músculo reto lateral da MOE e o IV o oblíquo inferior.","D":"Uma lesão completa do trato óptico à direita afeta o tamanho da pupila em repouso por danificar\na aferência.","E":"A pupila de Argyll Robertson é também tradicionalmente atribuída a dano na área periaquedutal,\nsendo um sinal clássico da neurossífilis."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-34543","number":"34543","sourceNumber":"34543","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Paciente com acidente vascular cerebral isquêmico apresentando quadro de\nhemiparesia contralateral com perda sensorial (pior\nna face), afasia expressiva e desorientação\nespacial, quadrantanopsia contralateral inferior, provavelmente está relacionado com a obstrução\ndo seguinte vaso sanguíneo:","options":{"A":"Artéria cerebral anterior.","B":"Artéria cerebral média.","C":"Artéria cerebral posterior.","D":"Artéria basilar.","E":"Artéria vertebral."},"answer":"B","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-31873","number":"31873","sourceNumber":"31873","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Sobre a avaliação semiológica do II, III, IV e VI nervos cranianos, assinale a\nalternativa\ncorreta.","options":{"A":"As fibras parassimpáticas no terceiro nervo craniano têm disposição central no nervo e vasculite\ndo vaso nervorum desse nervo dilatam a pupila.","B":"Lesões compressivas do terceiro nervo craniano alteram, primeiramente, a motricidade ocular\nextrínseca (MOE).","C":"O VI nervo craniano inerva o músculo reto lateral da MOE e o IV o oblíquo inferior.","D":"Uma lesão completa do nervo óptico não afeta o tamanho da pupila em repouso, por causa da\nnatureza consensual do reflexo luminoso.","E":"A pupila de Argyll Robertson é, também, tradicionalmente atribuída a dano na área\nperiaquedutal, sendo um sinal clássico de neurossífilis."},"answer":"E","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-31868","number":"31868","sourceNumber":"31868","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"O hematoma subdural é dito crônico quando o evento determinante ocorreu:","options":{"A":"Há 7 dias.","B":"De 7 a 10 dias.","C":"Após a segunda semana.","D":"Após a terceira semana.","E":"Só é considerado crônico após 1 mês do evento determinante."},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-14-25682","number":"25682","sourceNumber":"25682","collectionBlock":"med:med-clinica-medica-med-clm-14","collectionLabel":"MED · MED CLM 14","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 14","subtopic":"","stem":"Na fase aguda de um quadro de Acidente Vascular Encefálico Isquêmico podemos\nencontrar os seguintes achados na tomografia\ncomputadorizada de crânio, exceto:","options":{"A":"Sinal da artéria hiperdensa","B":"Apagamento de sulcos corticais","C":"Perda da diferenciação branco-cinzenta","D":"Hiperdensidade","E":"Hipodensidade"},"answer":"D","source":"Clinica médica/MED CLM 14/MED CLM 14.txt","sourceLabel":"MED · MED CLM 14","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 14","MED"],"answerSource":"explicit","commentDeferred":true}]};
